  "当上一节点审批人同意后，从设置的选择范围中选择本节点审批人。上一审批节点必须配置“通过意见”，否则此配置不生效。若涉及多人审批，仅在或签模式下支持此操作。": "이전 노드의 결재자가 승인하면 설정된 선택 범위에서 이 노드의 결재자를 선택합니다。이전 결재 노드에 “승인 의견”이 설정되어 있어야 적용됩니다。여러 명이 결재하는 경우에는 1인 결재 모드에서만 지원됩니다。",
  "当以上指定的其中一个字段新增或更新时将触发流程，如未指定则表示任何字段新增或更新时都会触发": "위에서 지정한 필드 중 하나가 추가되거나 업데이트되면 프로세스가 실행됩니다。지정하지 않으면 모든 필드의 추가 또는 업데이트 시 실행됩니다",
  "原模型已下架，将使用系统替代模型": "기존 모델이 제공 중단되어 시스템 대체 모델을 사용합니다",
