  "检测到当前表已配置以下依赖项，开启后将影响引用字段的实时性：": "현재 테이블에 다음 종속 항목이 설정되어 있습니다。활성화하면 참조 필드의 실시간 업데이트에 영향을 줍니다：",
  "已有影响项": "영향받는 기존 항목",
  "汇总字段：": "집계 필드：",
  "他表字段：": "다른 테이블 필드：",
  "以上字段引用的数据之后如果发生变更，将不会自动更新，只能手动刷新。": "위 필드가 참조하는 데이터가 변경되어도 자동으로 업데이트되지 않으며 수동으로 새로고침해야 합니다。",
  "单向关联：": "단방향 연결：",
  "仅在当前表维护关联关系": "현재 테이블에서만 연결 관계 관리",
  "双向关联：": "양방향 연결：",
  "什么是双向关联？": "양방향 연결이란？",
  "💡 适用于被高频引用的标签、省市区、费用科目等字典表。开启后，关联时不向目标表写入反向数据，从而提升表单性能。": "💡 자주 참조되는 태그、행정구역、비용 항목 등의 참조 테이블에 적합합니다。활성화하면 연결 시 대상 테이블에 역방향 데이터를 쓰지 않아 양식 성능이 향상됩니다。",
  "勾选后：": "선택 시：",
  "- 汇总、他表字段（存储数据类型）不会自动更新，只能手动刷新。": "- 집계 및 다른 테이블 필드（데이터 저장 유형）는 자동으로 업데이트되지 않으며 수동으로 새로고침해야 합니다。",
  "- 当关联的记录被删除时，不会自动取消关联，将显示为已删除。": "- 연결된 레코드가 삭제되어도 연결은 자동으로 해제되지 않으며，삭제된 상태로 표시됩니다。",
  "建立双向关联": "양방향 연결 설정",
  "关联工作表": "워크시트 연결",
  "检测到有可建立的双向关联": "설정 가능한 양방향 연결을 찾았습니다",
  "“%0”中存在可添加到当前工作表的反向字段，是否使用已有关系添加反向字段？关闭后将会创建一组新的关联关系。": "“%0”에 현재 워크시트에 추가할 수 있는 역방향 필드가 있습니다。기존 관계를 사용하여 역방향 필드를 추가할까요？비활성화하면 새 연결 관계를 만듭니다。",
  "%0 中的已有关联关系": "%0의 기존 연결 관계",
  "选择其他工作表中已关联 \"%0\" 的字段建立双向关联。建立后，可在两个工作表中维护同一关联关系": "다른 워크시트에서 이미 \"%0\"에 연결된 필드를 선택하여 양방향 연결을 만드세요。설정 후 두 워크시트에서 같은 연결 관계를 관리할 수 있습니다",
  "配置建议：": "권장 설정：",
  "如仅需在当前表中查看记录，可使用“查询记录”字段，无需创建双向关联。如：在客户表中查看关联当前客户的订单。": "현재 테이블에서 레코드를 조회하기만 한다면 양방향 연결 없이 “레코드 조회” 필드를 사용하세요。예: 고객 테이블에서 해당 고객의 주문 조회。",
  "如需在两个工作表中同时维护关联关系。如：项目与成员、用户与角色。则需创建为双向关联。": "프로젝트와 멤버、사용자와 역할처럼 두 워크시트에서 연결 관계를 모두 관리하려면 양방향 연결을 만드세요。",
  "关联其他工作表中的记录，并保存记录之间的关系。如：订单关联客户。": "다른 워크시트의 레코드를 연결하고 레코드 간 관계를 저장합니다。예: 주문에 고객 연결。",
  "添加关联记录字段": "연결 레코드 필드 추가",
  "在当前表中存储数据，存储后他表字段可用于工作表搜索、筛选、排序、统计，或被公式、文本组合字段使用。": "현재 테이블에 데이터를 저장합니다。저장 후 다른 테이블 필드를 워크시트 검색、필터링、정렬、통계에 사용하거나 수식 및 텍스트 조합 필드에서 사용할 수 있습니다。",
  "当前关联记录已开启【轻量级单向关联】：当引用的数据源的字段变更后，不会同步更新本表的他表字段数据。": "현재 연결 레코드에 【경량 단방향 연결】이 활성화되어 있습니다：참조 데이터 소스의 필드가 변경되어도 이 테이블의 다른 테이블 필드 데이터는 자동으로 업데이트되지 않습니다。",
  "当前关联记录已开启【轻量级单向关联】，当引用的数据源字段变更后，不会同步更新本表的汇总字段数据": "현재 연결 레코드에 【경량 단방향 연결】이 활성화되어 있습니다。참조 데이터 소스의 필드가 변경되어도 이 테이블의 집계 필드 데이터는 자동으로 업데이트되지 않습니다",
  "未选择时，系统自动推荐": "선택하지 않으면 시스템이 자동으로 추천합니다",
