  "反馈失败，请稍后重试": "피드백 전송에 실패했습니다。잠시 후 다시 시도하세요",
  "关联方式": "연결 방식",
  "反馈使用中遇到的错误或提出改进意见": "사용 중 발생한 오류나 개선 의견을 보내세요",
  "反馈ID": "피드백 ID",
  "反馈内容": "피드백 내용",
  "所有接口": "전체 API",
  "获取更多信息": "추가 정보 가져오기",
  "获取人员的汇报关系信息": "사용자의 보고 관계 정보 가져오기",
  "包含人员的直属上司、直接下属、所有下属；无需汇报关系时建议取消勾选，提升查询效率": "직속 상사、직속 관리 대상 직원、모든 관리 대상 직원을 포함합니다；보고 관계가 필요하지 않으면 선택을 해제하여 조회 속도를 높이세요",
  "获取当前组织已集成的第三方用户 ID（企业微信/钉钉/飞书/Lark/Miacrosoft Entra）；无需第三方用户 ID时建议取消勾选，提升查询效率": "현재 조직에 연동된 외부 사용자 ID（WeCom/DingTalk/Feishu/Lark/Microsoft Entra）를 가져옵니다；외부 사용자 ID가 필요하지 않으면 선택을 해제하여 조회 속도를 높이세요",
  "单次最多上传%0个图标": "한 번에 최대 %0개 아이콘을 업로드할 수 있습니다",
  "无法获取补充资料，请重试或重新验证身份": "추가 정보를 가져올 수 없습니다。다시 시도하거나 본인 인증을 다시 진행하세요",
  "重新验证": "다시 인증",
  "无法完成授权": "권한을 부여할 수 없습니다",
  "回调地址不是本机地址，可能是被伪造的授权链接，已阻止跳转。": "콜백 주소가 로컬 주소가 아니므로 위조된 권한 부여 링크일 수 있습니다。이동을 차단했습니다。",
  "授权本地开发工具": "로컬 개발 도구에 권한 부여",
  "mdye-cli 将获得当前账号的登录凭证，用于在本地调试插件。请确认这次授权是你本人发起的。": "mdye-cli가 로컬 플러그인 디버깅을 위해 현재 계정의 로그인 자격 증명을 받습니다。직접 요청한 권한 부여인지 확인하세요。",
  "当前账号：%0": "현재 계정：%0",
  "。需开通 Code 功能，并建议使用最新版客户端。": "。Code 기능을 활성화해야 하며，최신 클라이언트 사용을 권장합니다。",
  "组织者": "주최자",
  "反馈入口暂未开放": "피드백 기능이 아직 제공되지 않습니다",
  "当前请求暂不可反馈": "현재 요청에 대한 피드백을 보낼 수 없습니다",
  "反馈服务暂不可用，请稍后重试": "피드백 서비스를 일시적으로 사용할 수 없습니다。잠시 후 다시 시도하세요",
  "打开反馈页面失败，请稍后重试": "피드백 페이지를 열지 못했습니다。잠시 후 다시 시도하세요",
  "2.支付渠道：拉卡拉(费率0.3%)、微信支付/支付宝支付(费率以签约渠道为准)。": "2.결제 채널：Lakala(수수료율 0.3%)、WeChat Pay/Alipay(수수료율은 계약한 채널 기준)。",
  "拉卡拉": "Lakala",
  "填写代理服务器的 IP 地址或域名，如 192.168.1.10 或 proxy.example.com，不包含 http://、https://": "프록시 서버의 IP 주소 또는 도메인을 입력하세요。예: 192.168.1.10 또는 proxy.example.com。http://、https://는 포함하지 마세요",
  "由拉卡拉提供，暂时需要联系顾问线下申请商户入网；支持微信和支付宝聚合支付，费率固定为0.3%": "Lakala에서 제공합니다。현재는 컨설턴트를 통해 오프라인으로 가맹점 등록을 신청해야 합니다；WeChat과 Alipay 통합 결제를 지원하며 수수료율은 0.3%로 고정됩니다",
  "请联系您的专属顾问协助完成商户入网": "전담 컨설턴트에게 가맹점 등록 지원을 요청하세요",
  "是指通过代理访问的目标 URL 的协议类型": "프록시를 통해 접근하는 대상 URL의 프로토콜 유형입니다",
  "文本组合%04000": "텍스트 조합",
  "汇总关联记录或子表中的数据，如：汇总订单明细中的商品总价，最大支持汇总1000行数据。": "연결된 레코드나 하위 테이블의 데이터를 집계합니다，예：주문 상세 내역의 상품 총액 집계，최대 1000행의 데이터를 집계할 수 있습니다。",
