  "验证码短信": "인증 코드 문자 메시지",
  "仅支持发送登录/注册验证码。只需配置一个服务商，若配置了多个服务商，则发送验证码短信时每次会随机选择一个。": "로그인/가입 인증 코드 전송만 지원합니다。서비스 제공업체는 하나만 설정하면 됩니다，여러 업체를 설정하면 인증 코드 문자 메시지를 보낼 때마다 무작위로 하나를 선택합니다。",
  "自定义短信功能": "사용자 지정 문자 메시지 기능",
  "开启后将显示短信相关功能入口（如：工作流发送短信节点、手机号邀请用户、外部门户短信通知等）。为保障功能实际可用，需要自行申请第三方短信服务商账号，然后自主集成或由官方技术团队定制开发": "활성화하면 문자 메시지 관련 기능 메뉴가 표시됩니다（예：워크플로 문자 메시지 전송 노드，휴대폰 번호로 사용자 초대，외부 포털 문자 메시지 알림 등）。실제로 기능을 사용하려면 타사 문자 메시지 서비스 계정을 직접 신청한 후 직접 연동하거나 공식 기술팀에 맞춤 개발을 요청해야 합니다",
  "了解自主集成": "직접 연동 알아보기",
  "%0短信配置服务": "%0 문자 메시지 서비스 설정",
  "如果组织内不使用以下第三方平台，可取消勾选": "조직에서 아래 타사 플랫폼을 사용하지 않으면 선택을 해제할 수 있습니다",
  "地图服务": "지도 서비스",
  "开启后将显示地图相关功能入口（如：地图视图、定位字段、个人偏好设置>地图）。若要保证功能正常使用，还需要在下方配置并开启地图服务。个人偏好>地图的初始值将跟随列表中第一个开启的地图服务": "활성화하면 지도 관련 기능 메뉴가 표시됩니다（예：지도 보기，위치 필드，개인 환경설정>지도）。기능을 정상적으로 사용하려면 아래에서 지도 서비스를 설정하고 활성화해야 합니다。개인 환경설정>지도의 초기값은 목록에서 첫 번째로 활성화된 지도 서비스를 따릅니다",
