  "可自定义工作台显示的资源列表项": "업무 홈에 표시되는 리소스 목록 항목을 사용자 지정할 수 있습니다",
  "是否开启两步验证 ?": "2단계 인증을 활성화할까요 ?",
  "开启后，除了基于账号密码的登录认证，还需要通过手机号或邮箱接收验证码进行二次认证，所以请确保组织成员的手机号、邮箱的合法性，同时确保系统内的短信服务、邮件服务已正常启用。": "활성화하면 계정과 비밀번호 인증 외에 휴대폰이나 이메일로 받은 인증 코드로 추가 인증을 진행해야 합니다，따라서 조직 구성원의 휴대폰 번호와 이메일이 유효하며 시스템의 문자 메시지 및 이메일 서비스가 정상적으로 활성화되어 있는지 확인하세요。",
  "二次验证": "추가 인증",
  "二次验证方式优先级": "추가 인증 방법 우선순위",
  "此项为“登录二次验证”，开启后，除了基于账号密码的登录认证，还需要通过手机号或邮箱接收验证码进行二次认证，所以请确保组织成员的手机号、邮箱的合法性，同时确保系统内的短信服务、邮件服务已正常启用。": "이 항목은 “로그인 추가 인증”입니다，활성화하면 계정과 비밀번호 인증 외에 휴대폰이나 이메일로 받은 인증 코드로 추가 인증을 진행해야 합니다，따라서 조직 구성원의 휴대폰 번호와 이메일이 유효하며 시스템의 문자 메시지 및 이메일 서비스가 정상적으로 활성화되어 있는지 확인하세요。",
  "登录时优先采用设置的验证方式进行验证": "로그인 시 설정된 인증 방법을 우선 사용합니다",
