  "首次登录需修改密码": "최초 로그인 시 비밀번호 변경 필수",
  "过期天数": "만료까지의 일수",
  "在首次登录自主创建的账号、导入的预设账号、被管理员重置密码的账号时生效": "직접 생성한 계정，가져온 사전 설정 계정，관리자가 비밀번호를 초기화한 계정의 최초 로그인 시 적용됩니다",
  "密码规则": "비밀번호 규칙",
  "启用后，平台用户密码安全策略将按配置进行强校验": "활성화하면 설정된 비밀번호 보안 정책에 따라 플랫폼 사용자 비밀번호를 엄격하게 검증합니다",
  "开启时，平台账户可自行配置设备登录限制(账户管理-->安全设置)；关闭后，平台用户仅可在同设备类型登录一个终端，例如在Web浏览器登录后，将会使其他Web浏览器登录的同一账号强制退出登录，以确保账户登录安全，手机APP同理": "활성화하면 플랫폼 계정에서 기기 로그인 제한을 직접 설정할 수 있습니다(계정 관리-->보안 설정)；비활성화하면 기기 유형별로 하나의 기기에만 로그인할 수 있습니다，예를 들어 웹 브라우저에 로그인하면 계정 보안을 위해 다른 웹 브라우저의 동일 계정이 강제로 로그아웃됩니다，모바일 앱에도 동일하게 적용됩니다",
  "提示说明": "안내 설명",
  "接口防护": "인터페이스 보호",
  "平台中部分接口需在未鉴权的情况下被调用，如：全局固定的配置信息；关联表字段结构；对外公开分享、查询和填写等。如果需要接口严格鉴权或响应体加密返回，可开启此配置。": "플랫폼의 일부 인터페이스는 인증 없이 호출되어야 합니다，예：전역 고정 설정 정보；연관 테이블 필드 구조；외부 공개 공유，조회 및 작성 등。엄격한 인터페이스 인증이나 암호화된 응답 본문이 필요하면 이 설정을 활성화하세요。",
