  "名称最多40个字符": "이름은 최대 40자까지 입력할 수 있습니다",
  "为保护您账户的安全，请妥善保管此凭证": "계정 보안을 위해 이 자격 증명을 안전하게 보관하세요",
  "组织管理员不允许使用个人访问令牌": "조직 관리자가 개인용 접근 토큰 사용을 허용하지 않습니다",
  "个人访问令牌代表您的身份，用于 HAP 数据的操作访问。您可自定义权限范围和数据访问权限。️安全提示：令牌具有账户权限，请勿分享给他人。": "개인용 접근 토큰은 사용자 신원을 나타내며，HAP 데이터 접근 및 작업에 사용됩니다。권한 범위와 데이터 접근 권한을 지정할 수 있습니다。️보안 안내：토큰에는 계정 권한이 있으므로，다른 사람과 공유하지 마세요。",
  "5. 可通过代码 #{[qrcode]字段名$[20*20]$} 或 #{[barcode]字段名$[40*10]$} 获取任意字段的二维码 或 条形码。二维码编码方式：QR-code，最大包含150个字（支持汉字）；条形码编码方式：code128，最大包含30个字符（仅支持数字、字母、符号）。如需隐藏条形码下方的显示值字段，则增加_NT控制隐藏，例如 #{[barcode]字段名$[40*10_NT]$} 隐藏条形码下方文字；不加 _NT 仍按原逻辑显示。": "5. 코드 #{[qrcode]字段名$[20*20]$} 또는 #{[barcode]字段名$[40*10]$}로 모든 필드의 QR 코드 또는 바코드를 가져올 수 있습니다。QR 코드 인코딩 방식：QR-code，최대 150자 포함（한자 지원）；바코드 인코딩 방식：code128，최대 30자 포함（숫자、영문자、기호만 지원）。바코드 하단의 표시 값 필드를 숨기려면 _NT를 추가하세요。예를 들어 #{[barcode]字段名$[40*10_NT]$}는 바코드 하단 텍스트를 숨깁니다；_NT를 추가하지 않으면 기존 방식대로 표시됩니다。",
  "仅自己可见，可用于自己管理的所有应用（包含其他组织的应用）": "나에게만 표시되며，관리 중인 모든 애플리케이션에서 사용 가능（다른 조직의 애플리케이션 포함）",
  "全组织所有应用可见，所有应用管理员均可使用": "조직의 모든 애플리케이션에서 표시되며，모든 애플리케이션 관리자가 사용 가능",
  "无法创建字段模板，你对关联表%0无管理权限": "필드 템플릿을 생성할 수 없습니다，연결된 테이블 %0에 대한 관리 권한이 없습니다",
  "已自动添加引用字段，以确保模版完整可用": "템플릿을 온전히 사용할 수 있도록 참조 필드를 자동으로 추가했습니다",
  "模板名称不允许重复": "템플릿 이름은 중복될 수 없습니다",
  "未添加引用字段，无法创建字段模板": "참조 필드가 추가되지 않아，필드 템플릿을 생성할 수 없습니다",
  "模板最多包含 30 个字段（含引用字段），请减少选择后重试": "템플릿에는 최대 30개 필드（참조 필드 포함）를 포함할 수 있습니다，선택 항목을 줄인 후 다시 시도하세요",
  "编辑字段模版": "필드 템플릿 편집",
  "添加字段模版": "필드 템플릿 추가",
  "便于后续搜索和判断使用场景": "이후 검색 및 사용 상황 파악에 도움",
  "模板包含关联字段，发布后所有应用管理员使用此模板创建字段时，可查看关联工作表的结构与数据": "템플릿에 연결 필드가 포함되어 있습니다。게시 후 모든 애플리케이션 관리자가 이 템플릿으로 필드를 생성할 때，연결된 워크시트의 구조와 데이터를 볼 수 있습니다",
  "模板中的字段（包含引用字段）": "템플릿의 필드（참조 필드 포함）",
  "所选字段均不支持创建字段模板": "선택한 필드는 모두 필드 템플릿 생성을 지원하지 않습니다",
  "%0的关联表配置无效，目标表不存在或已被删除，请关联一张有效的工作表后再保存。": "%0의 연결 테이블 설정이 유효하지 않습니다。대상 테이블이 없거나 삭제되었습니다，유효한 워크시트를 연결한 후 저장하세요。",
  "创建字段模版": "필드 템플릿 생성",
