  "确定要删除此字段模板？": "이 필드 템플릿을 삭제할까요？",
  "删除字段模板后，使用该模板的字段不会被删除。": "필드 템플릿을 삭제해도 해당 템플릿으로 만든 필드는 삭제되지 않습니다。",
  "注意：设置后，新保存的字段值将按照新规则加密，历史值不会自动刷新。之后您需要手动刷新历史数据，未刷新时历史数据可查看，但无法被筛选。": "참고：설정 후 새로 저장되는 필드 값은 새 규칙으로 암호화되며，기존 값은 자동으로 갱신되지 않습니다。이후 기존 데이터를 수동으로 갱신해야 합니다。갱신 전에도 기존 데이터를 볼 수 있지만，필터링할 수는 없습니다。",
