  "优先从每月赠送的AI福利点中扣除，费用 20信用点/百万token": "매월 무료로 제공되는 AI 크레딧부터 차감되며，요금은 100만 토큰당 20 크레딧입니다",
  "「信用点」用于系统中 AI 功能、发送邮件、短信等计费服务自动扣费。为避免系统功能不可用，请确保账户信用点余额充足。": "「크레딧」은 시스템의 AI 기능、이메일 및 문자 발송 등의 유료 서비스 이용 시 자동으로 차감됩니다。시스템 기능을 계속 사용할 수 있도록 계정의 크레딧 잔액을 충분히 유지하세요。",
  "其中「AI福利点」为每月平台赠送额度，仅抵扣AI搭建应用费用；使用用AI搭建应用时会优先消耗AI福利点，额度用尽后再从通用信用点扣费。": "이 중 「AI 크레딧」은 플랫폼에서 매월 무료로 제공하는 한도로，AI 애플리케이션 구축 비용에만 적용됩니다；AI로 애플리케이션을 구축할 때 AI 크레딧이 먼저 차감되며，한도를 모두 사용하면 일반 크레딧이 차감됩니다。",
  "在「管理」中可查看扣费标准，或关闭自动扣费。": "「관리」에서 요금 기준을 확인하거나 자동 차감을 끌 수 있습니다。",
  "预警（<%0）": "경고（<%0）",
  "AI 福利点:": "AI 크레딧:",
  "每月1日00:00自动刷新为 %0福利点，不累加": "매월 1일 00:00에 %0 AI 크레딧으로 자동 갱신되며，누적되지 않습니다",
  "每月刷新": "매월 갱신",
  "包含当前所有及未来新增模型。若选择范围过大，可能导致高成本模型被批量开放。": "현재 모든 모델과 향후 추가되는 모델을 포함합니다。범위를 너무 넓게 선택하면 비용이 높은 모델이 일괄 허용될 수 있습니다。",
  "仅下方模型进入本规则授权范围": "아래 모델만 이 규칙의 허용 범위에 포함",
  "包含当前所有及未来新增应用": "현재 모든 애플리케이션과 향후 추가되는 애플리케이션 포함",
  "仅下方应用可使用本规则模型；多规则命中时取并集。": "아래 애플리케이션만 이 규칙의 모델을 사용할 수 있습니다；여러 규칙이 적용되면 허용 범위를 합칩니다。",
  "指的是本规则授权哪些模型；未被任何生效规则授权的模型不可用。": "이 규칙에서 허용하는 모델을 의미합니다；어떤 활성 규칙에서도 허용되지 않은 모델은 사용할 수 없습니다。",
  "指的是哪些应用可使用本规则内的模型；未被任何生效规则授权的应用不可使用 AI 模型。": "이 규칙의 모델을 사용할 수 있는 애플리케이션을 의미합니다；어떤 활성 규칙에서도 허용되지 않은 애플리케이션은 AI 모델을 사용할 수 없습니다。",
  "1、仅启用规则内授权的「模型 × 应用」组合可用，不在规则内的应用不可使用AI 模型": "1、활성화된 규칙에서 허용한 「모델 × 애플리케이션」 조합만 사용할 수 있으며，규칙에 포함되지 않은 애플리케이션은 AI 모델을 사용할 수 없습니다",
  "1 、未创建规则或所有规则均已关闭时，默认全部模型的使用权限": "1 、규칙이 없거나 모든 규칙이 비활성화된 경우，기본적으로 모든 모델의 사용 권한이 부여됩니다",
  "2 、创建并启用规则后，仅规则内授权的「模型 x 应用」组合可用": "2 、규칙을 생성하고 활성화하면，규칙에서 허용한 「모델 x 애플리케이션」 조합만 사용할 수 있습니다",
