  "推荐待搭建应用": "구축할 애플리케이션 추천",
  "「AI 福利点」（1福利点=1个信用点）可用于抵扣 mingo 中AI搭建和查询功能费用，组织所有用户共享；使用 AI 搭建应用时会优先消耗 AI 福利点，额度用尽后再从通用信用点扣费": "「AI 크레딧」（AI 크레딧 1개=크레딧 1개）은 Mingo의 AI 구축 및 조회 기능 비용에 사용할 수 있으며，조직의 모든 사용자가 공유합니다；AI로 애플리케이션을 구축할 때 AI 크레딧이 먼저 차감되며，한도를 모두 사용하면 일반 크레딧이 차감됩니다",
  "Mingo AI 功能": "Mingo AI 기능",
  "关闭后，当AI福利点用完后，将不会继续扣除信用点，且无法使用MingoAI付费功能": "끄면 AI 크레딧을 모두 사용한 후 일반 크레딧이 추가로 차감되지 않으며，Mingo AI 유료 기능을 사용할 수 없습니다",
  "Mingo搭建—AI搭建应用、创建工作表、填充示例数据、优化名称和图标、填写记录": "Mingo 구축—AI로 애플리케이션 구축、워크시트 생성、샘플 데이터 입력、이름 및 아이콘 개선、레코드 작성",
  "Mingo查询—使用Mingo查询应用数据": "Mingo 조회—Mingo로 애플리케이션 데이터 조회",
  "使用帮助问答不扣费": "사용 도움말 질의응답은 무료입니다",
  "「信用点」用于系统中Mingo AI功能、发送邮件、短信等计费服务自动扣费。为避免系统功能不可用，请确保账户信用点余额充足。": "「크레딧」은 시스템의 Mingo AI 기능、이메일 및 문자 발송 등의 유료 서비스 이용 시 자동으로 차감됩니다。시스템 기능을 계속 사용할 수 있도록 계정의 크레딧 잔액을 충분히 유지하세요。",
  "其中「AI 福利点」为平台赠送额度（1福利点=1个信用点），仅抵扣 Mingo AI功能费用；使用时会优先消耗 AI 福利点，额度用尽后再从通用信用点扣费。": "이 중 「AI 크레딧」은 플랫폼에서 무료로 제공하는 한도（AI 크레딧 1개=크레딧 1개）로，Mingo AI 기능 비용에만 적용됩니다；사용 시 AI 크레딧이 먼저 차감되며，한도를 모두 사용하면 일반 크레딧이 차감됩니다。",
  "完成步骤 1 后，填入CorpId、AgentId、ClientId、ClientSecret后可对接应用与同步通讯录": "1단계를 완료한 후，CorpId、AgentId、ClientId、ClientSecret을 입력하면 애플리케이션 연동 및 연락처 동기화를 사용할 수 있습니다",
