  "允许将视图公开分享，获得链接的所有人都可以查看视图和视图下的全部记录": "보기 공개 공유를 허용하며，링크가 있는 모든 사람이 보기와 해당 보기의 모든 레코드를 볼 수 있습니다",
  "允许将记录公开分享，获得链接的所有人都可以查看记录": "레코드 공개 공유를 허용하며，링크가 있는 모든 사람이 레코드를 볼 수 있습니다",
  "公开分享链接": "공개 공유 링크",
  "使用业务库创建用户": "업무 데이터베이스로 사용자 생성",
  "通过解析内部成员访问或公开分享的记录链接来获取对应的记录对象，供流程中的其他节点使用。场景例如：仓库管理员在PC端使用扫描枪来扫描商品的二维码，将指向的记录链接写入文本框，由工作流解析出关联的产品，实现自动化出入库。": "내부 구성원이 접근하거나 공개 공유된 레코드 링크를 분석하여 해당 레코드 객체를 가져오고，워크플로의 다른 노드에서 사용합니다。예를 들어：창고 관리자가 PC에서 바코드 스캐너로 상품 QR 코드를 스캔해 레코드 링크를 텍스트 상자에 입력하면，워크플로가 연결된 제품을 식별하여 입출고를 자동화합니다。",
  "选中记录不满足条件": "선택한 레코드가 조건을 충족하지 않습니다",
  "○ 创建「唯一索引」时，选择的索引字段在已有记录里不能存在重复值（包含回收站内的记录）；": "○ 「고유 인덱스」를 만들 때，선택한 인덱스 필드의 기존 레코드에 중복 값이 없어야 합니다（휴지통의 레코드 포함）；",
  "○ 一张工作表只能创建一个「文本索引」；": "○ 워크시트마다 「텍스트 인덱스」를 하나만 만들 수 있습니다；",
  "每张工作表只能创建一个「文本索引」；创建「文本索引」时，不能包含「选项字段」；每个索引只能包含一个「选项字段」": "워크시트마다 「텍스트 인덱스」를 하나만 만들 수 있습니다；「텍스트 인덱스」를 만들 때 「선택 필드」를 포함할 수 없습니다；각 인덱스에는 「선택 필드」를 하나만 포함할 수 있습니다",
  "20秒": "20초",
  "示例：=ENCODEURICOMPONENT('name=系统')，结果：'name%3D%E7%B3%BB%E7%BB%9F'": "예：=ENCODEURICOMPONENT('name=系统')，결과：'name%3D%E7%B3%BB%E7%BB%9F'",
  "示例：=DECODEURICOMPONENT('name%3D%E7%B3%BB%E7%BB%9F')，结果：\"name=系统\"": "예：=DECODEURICOMPONENT('name%3D%E7%B3%BB%E7%BB%9F')，결과：\"name=系统\"",
  "版本%26016": "버전",
  "升级后将立即执行发布更新，升级期间应用无法正常使用，完成后会推送结果。请确认此操作。": "업그레이드하면 게시 업데이트가 즉시 실행되며，업그레이드 중에는 애플리케이션을 정상적으로 사용할 수 없습니다。완료 후 결과가 전송됩니다。이 작업을 확인하세요。",
  "还原至 %0 版本": "%0 버전으로 복원",
  "确认后，将当前应用还原为该历史版本的应用结构，未发布的变更项将被丢弃，请谨慎操作。": "확인하면 현재 애플리케이션이 해당 이전 버전의 구조로 복원되며，게시되지 않은 변경 사항은 삭제되므로 신중하게 진행하세요。",
  "确认还原": "복원 확인",
  "驳回理由": "반려 사유",
  "通过后将进入待升级状态，可手动执行升级": "승인 후 업그레이드 대기 상태로 전환되며，수동으로 업그레이드할 수 있습니다",
  "请填写应用审核不通过的理由": "애플리케이션 심사 반려 사유를 입력하세요",
