  "隔离结构，锁定生产应用结构，仅能在沙盒中编辑测试": "구조 격리，운영 애플리케이션 구조를 잠그고 샌드박스에서만 편집 및 테스트 가능",
  "隔离数据，可选择同步生产数据至沙盒用于测试": "데이터 격리，테스트를 위해 운영 데이터를 샌드박스에 동기화 가능",
  "沙盒搭建-发布审核-更新至生产，支持版本回滚": "샌드박스 구축-게시 심사-운영 환경 업데이트，버전 롤백 지원",
  "组织级数据": "조직 수준 데이터",
  "共用组织级数据，包含组织后台、API 集成、插件配置": "조직 관리、API 연동、플러그인 설정을 포함한 조직 수준 데이터 공유",
  "运行与观测": "실행 및 모니터링",
  "隔离不同环境中运行产生通知、计费、日志等数据": "각 환경에서 실행 중 생성되는 알림、과금、로그 등의 데이터 격리",
  "应用沙盒": "애플리케이션 샌드박스",
  "应用沙盒是一个与正式环境完全隔离的“实验场”。在这里，您可以自由修改测试应用结构，且不会影响到正式环境运行的业务。": "애플리케이션 샌드박스는 운영 환경과 완전히 격리된 “테스트 공간”입니다。여기에서 운영 중인 업무에 영향을 주지 않고 애플리케이션 구조를 자유롭게 수정하고 테스트할 수 있습니다。",
