  "支持登录密码、短信验证码、邮件验证码、身份验证器 4 种验证方式。未开启的方式需前往「个人账户 > 安全设置」配置后使用。": "로그인 비밀번호、문자 인증 코드、이메일 인증 코드、인증 앱의 4가지 인증 방식을 지원합니다。활성화되지 않은 방식은 「개인 계정 > 보안 설정」에서 설정한 후 사용할 수 있습니다。",
