  "所选%0个应用中，%1个尚未保存，需保存后才能重置。确定将把其余%2个应用的工作流执行数重置为0吗？": "선택한 애플리케이션 %0개 중 %1개는 아직 저장되지 않아 저장 후 초기화할 수 있습니다。나머지 애플리케이션 %2개의 워크플로 실행 횟수를 0으로 초기화할까요？",
  "所选%0个应用中，%1个尚未保存，需保存后才能重置。确定将把其余%2个应用的已使用附件上传量重置为0吗？": "선택한 애플리케이션 %0개 중 %1개는 아직 저장되지 않아 저장 후 초기화할 수 있습니다。나머지 애플리케이션 %2개의 첨부 파일 업로드 사용량을 0으로 초기화할까요？",
  "确定将所选%0个应用的工作流执行数重置为0吗？": "선택한 애플리케이션 %0개의 워크플로 실행 횟수를 0으로 초기화할까요？",
  "确定将所选%0个应用的已使用附件上传量重置为0吗？": "선택한 애플리케이션 %0개의 첨부 파일 업로드 사용량을 0으로 초기화할까요？",
  "确定将“%0”的工作流执行数重置为0吗？": "“%0”의 워크플로 실행 횟수를 0으로 초기화할까요？",
  "确定将“%0”的已使用附件上传量重置为0吗？": "“%0”의 첨부 파일 업로드 사용량을 0으로 초기화할까요？",
  "选择的应用总数上限%0个": "선택 가능한 애플리케이션은 최대 %0개입니다",
  "请输入IP": "IP를 입력하세요",
  "沙盒环境": "샌드박스 환경",
  "审核与升级": "심사 및 업그레이드",
  "免审": "심사 면제",
  "1、沙盒是完全独立的测试环境，应用结构与数据与生产环境完全隔离。共用生产环境的组织架构、API 集成、插件。": "1、샌드박스는 완전히 독립된 테스트 환경으로，애플리케이션 구조와 데이터가 운영 환경과 분리됩니다。조직 구조、API 연동、플러그인은 운영 환경과 공유합니다。",
  "2、应用开启沙盒环境后，正式环境中的结构将被锁定。在沙盒环境测试与开发，不会影响正式环境的运行，验证通过后可以发布至正式环境。": "2、애플리케이션의 샌드박스를 활성화하면 운영 환경의 구조가 잠깁니다。샌드박스의 테스트 및 개발은 운영 환경에 영향을 주지 않으며，검증 후 운영 환경에 게시할 수 있습니다。",
  "3、不同环境中运行产生的通知、计费、日志数据也完全隔离。": "3、각 환경에서 생성된 알림、청구、로그 데이터도 완전히 분리됩니다。",
  "沙盒": "샌드박스",
  "访问沙盒环境": "샌드박스 환경으로 이동",
