  "选择的应用共%0个，已超过上限%1个，请重新选择": "선택한 애플리케이션 %0개가 한도 %1개를 초과합니다。다시 선택하세요",
  "沙盒环境 - 应用沙盒": "샌드박스 환경 - 애플리케이션 샌드박스",
  "选择要开启沙盒的应用和同步的数据范围，自动校验并添加关联应用，关联需同步开启沙盒。": "샌드박스를 활성화할 애플리케이션과 동기화할 데이터 범위를 선택하세요。연결된 애플리케이션을 자동 확인하여 추가하며，함께 샌드박스를 활성화해야 합니다。",
  "审核": "심사",
  "沙盒环境 - 审核与升级": "샌드박스 환경 - 심사 및 업그레이드",
