  "用于概括应用的主要用途和业务定位，便于AI正确理解和使用。备注内容不会直接展示给普通用户。": "AI가 정확히 이해하고 활용할 수 있도록 애플리케이션의 주요 용도와 업무상 역할을 요약하세요。메모는 일반 사용자에게 직접 표시되지 않습니다。",
