  "继承关联工作表设置的列样式。如果指定的关联视图是表格视图、则使用该视图设置的列样式。": "연결된 워크시트의 열 스타일을 상속합니다。지정한 연결 보기가 테이블 보기이면 해당 보기의 열 스타일을 사용합니다。",
  "使用本节点前，请先确认已有蓝字发票。电子开票为异步处理，节点执行时会等待开票结果后再继续。此节点为自动开票，无需管理员审核。": "이 노드를 사용하기 전에 원본 청구서가 있는지 확인하세요。전자 청구서는 비동기로 처리되며，노드는 발행 결과를 기다린 후 계속 실행합니다。이 노드는 관리자 심사 없이 자동으로 청구서를 발행합니다。",
  "添加关注者": "팔로워 추가",
  "将指定用户添加为记录关注者，关注者将在记录更新或新增讨论时收到通知": "지정한 사용자를 레코드 팔로워로 추가합니다。팔로워는 레코드 업데이트나 새 토론 추가 시 알림을 받습니다",
  "移除关注者": "팔로워 제거",
  "将指定用户从记录关注者中移除，移除后将不再接收该记录的通知": "지정한 사용자를 레코드 팔로워에서 제거합니다。제거된 사용자는 해당 레코드의 알림을 더 이상 받지 않습니다",
  "覆盖关注者": "팔로워 교체",
  "使用指定用户替换当前关注者列表，原有关注者将被移除": "지정한 사용자로 현재 팔로워 목록을 교체합니다。기존 팔로워는 제거됩니다",
  "通过该节点可更新记录的关注用户，包括添加、移除或覆盖关注者。关注者将在新增讨论时收到系统通知。": "이 노드로 레코드 팔로워를 추가、제거 또는 교체할 수 있습니다。팔로워는 새 토론이 추가되면 시스템 알림을 받습니다。",
