  "开启后，执行该操作时需完成身份校验，验证方式以操作人个人账户的安全设置为准。": "활성화하면 이 작업을 실행할 때 본인 확인이 필요합니다。인증 방식은 작업자의 개인 계정 보안 설정을 따릅니다。",
  "获取第三方企业身份 ID": "외부 기업 사용자 ID 가져오기",
  "同时获取第三方企业身份 ID": "외부 기업 사용자 ID 함께 가져오기",
  "同时获取当前组织组织已集成的第三方用户 ID（企业微信/钉钉/飞书/Lark/Miacrosoft Entra）；如果您的使用场景无需第三方用户 ID，推荐不勾选以提升您的查询效率": "현재 조직에 연동된 외부 사용자 ID（WeCom/DingTalk/Feishu/Lark/Microsoft Entra）도 가져옵니다；외부 사용자 ID가 필요하지 않으면 선택하지 않는 것이 조회 효율에 좋습니다",
  "允许审批/填写人添加抄送人": "결재자/작성자의 참조 수신자 추가 허용",
  "开启后，审批人或填写人在处理当前节点时，可手动添加抄送人；被添加的抄送人可查看当前记录的相关内容。": "활성화하면 결재자나 작성자가 현재 노드를 처리할 때 참조 수신자를 직접 추가할 수 있습니다；추가된 참조 수신자는 현재 레코드의 관련 내용을 볼 수 있습니다。",
  "校验登录身份": "로그인 사용자 확인",
  "开启后，点击邮件中的审批按钮时，需先登录并校验当前账号是否为该审批的可操作人，校验通过后才可完成审批操作": "활성화하면 이메일의 결재 버튼을 클릭할 때 먼저 로그인하고 현재 계정의 결재 처리 권한을 확인합니다。검증을 통과해야 결재할 수 있습니다",
