  "获取应用数据失败": "애플리케이션 데이터를 가져오지 못했습니다",
  "选择要开启沙盒的应用和同步的数据范围，关联应用需同步开启沙盒。": "샌드박스를 활성화할 애플리케이션과 동기화할 데이터 범위를 선택하세요。연결된 애플리케이션도 함께 샌드박스를 활성화해야 합니다。",
