  "选择沙盒应用进行发布，若选择了多个应用，则需每个应用管理员都审核通过/组织管理员一键通过后，再一起升级": "게시할 샌드박스 애플리케이션을 선택하세요。여러 개를 선택하면 각 애플리케이션 관리자가 모두 승인하거나 조직 관리자가 일괄 승인한 후 함께 업그레이드해야 합니다",
