  "请稍后重试": "잠시 후 다시 시도하세요",
  "立即升级 %0 个应用": "애플리케이션 %0개 지금 업그레이드",
  "驳回 %0 个应用": "애플리케이션 %0개 반려",
  "通过 %0 个应用审核": "애플리케이션 %0개 심사 승인",
  "仅同步应用结构": "애플리케이션 구조만 동기화",
  "每张表最多同步10000条记录": "테이블당 최대 10000개 레코드 동기화",
  "自定义同步的记录数量": "동기화할 레코드 수 지정",
  "不同步": "동기화 안 함",
  "已删除/未开启沙盒": "삭제됨/샌드박스 비활성화",
  "查看生产应用": "운영 애플리케이션 보기",
  "版本号必须高于 %0": "버전 번호는 %0보다 높아야 합니다",
  "暂无变更": "변경 사항 없음",
  "获取应用变更失败，请稍后重试": "애플리케이션 변경 내역을 가져오지 못했습니다。잠시 후 다시 시도하세요",
  "暂无驳回原因": "반려 사유 없음",
  "开启沙盒后，正式环境中的应用结构将被锁定，所有调整均需通过发布进行更新，您可按需同步部分生产数据用于调试。关联应用也需开启沙盒，否则会导致引用失效。": "샌드박스를 활성화하면 운영 환경의 애플리케이션 구조가 잠기며，모든 변경 사항은 게시를 통해 반영해야 합니다。디버깅에 필요한 운영 데이터 일부를 동기화할 수 있습니다。참조 오류를 방지하려면 연결된 애플리케이션도 샌드박스를 활성화해야 합니다。",
  "检查沙盒环境失败，请稍后重试": "샌드박스 환경을 확인하지 못했습니다。잠시 후 다시 시도하세요",
  "获取组织沙盒配置失败，请稍后重试": "조직 샌드박스 설정을 가져오지 못했습니다。잠시 후 다시 시도하세요",
  "对当前应用提问": "현재 애플리케이션에 질문",
  "对当前应用继续搭建": "현재 애플리케이션 계속 구축",
  "@应用提问": "@애플리케이션에 질문",
  "开始搭建一个新应用": "새 애플리케이션 구축 시작",
  "创建失败，请稍后重试": "생성에 실패했습니다。잠시 후 다시 시도하세요",
  "已选择 %0 / %1 组对话": "대화 %0 / %1개 선택됨",
  "当前组织已禁止使用MingoAI功能": "현재 조직에서 Mingo AI 기능 사용을 금지했습니다",
  "认证提示": "인증 안내",
  "重复日期": "반복 날짜",
  "出席者头像": "참석자 프로필 사진",
  "任务参与者头像": "작업 참여자 프로필 사진",
  "支持登录密码、短信验证码、邮件验证码、身份验证器 4 种验证方式。短信、邮件验证码需先绑定手机号或邮箱；身份验证器需先开启两步认证并完成配置。": "로그인 비밀번호、SMS 인증 코드、이메일 인증 코드、인증 앱의 4가지 방식을 지원합니다。SMS나 이메일 인증은 휴대폰 번호 또는 이메일을 먼저 연결해야 합니다；인증 앱은 2단계 인증을 활성화하고 설정해야 합니다。",
