  "配置全员默认拥有的功能权限。关闭后，该功能将仅对特定【权限组】的授权成员开放。": "모든 사용자에게 기본 제공할 기능 권한을 설정합니다。비활성화한 기능은 특정 【권한 그룹】에서 권한을 받은 멤버만 사용할 수 있습니다。",
