  "勾选后，将向 AI Agent 提供除附件外的所有字段信息。如需使用附件，请在动态值中手动添加。": "선택하면 첨부 파일을 제외한 모든 필드 정보를 AI 에이전트에 제공합니다。첨부 파일을 사용하려면 동적 값에 수동으로 추가하세요。",
  "开启后用户需要在系统设置的时间内完成交易，逾期平台将关闭交易，后续需重新创建订单发起支付": "활성화하면 사용자는 시스템에 설정된 시간 내에 거래를 완료해야 합니다。기한이 지나면 플랫폼에서 거래를 종료하며，이후에는 주문을 다시 생성하여 결제해야 합니다",
  "对外分享、自定义短信签名等功能需完成组织身份认证（注意：非个人身份）": "외부 공유、사용자 지정 문자 발신 서명 등의 기능은 조직 인증을 완료해야 사용할 수 있습니다（참고：개인 인증 제외）",
  "查看历史待办消息": "이전 할 일 메시지 보기",
  "历史待办": "이전 할 일",
  "AI 动作消耗的Token将从组织信用点扣除": "AI 작업에 사용된 토큰 비용은 조직 크레딧에서 차감됩니다",
  "工作表无权限或者已删除": "워크시트 접근 권한이 없거나 삭제되었습니다",
  "描述机器人的目标和功能，以及他的服务对象。例如：“订单统计助手，可通过对话快速查询客户订单明细并统计金额。”": "봇의 목표와 기능，서비스 대상을 설명하세요。예：“대화를 통해 고객 주문 상세 내역을 빠르게 조회하고 금액을 집계하는 주문 통계 도우미。”",
  "无法使用此功能，请先完成企业认证": "이 기능을 사용할 수 없습니다，먼저 기업 인증을 완료하세요",
  "此证照已被其他组织认证使用，请勿重复认证": "이 증명서는 다른 조직의 인증에 사용되었습니다，중복 인증하지 마세요",
  "使用短信自定义签名等功能时需要完成企业认证": "사용자 지정 문자 발신 서명 등의 기능을 사용하려면 기업 인증을 완료해야 합니다",
  "请上传您有效的企业相关证书，以及与证书一致的法人身份证人像面与国徽面，并输入与身份证一致的实名制手机号，系统会自动进行匹配认证并保证您的隐私安全，若信息正确但未能有效通过认证，可联系在线客服或专属顾问": "유효한 기업 관련 증명서와 증명서에 기재된 법정 대표자의 신분증 사진 면 및 국장 면을 업로드하고，신분증과 일치하는 실명 등록 휴대폰 번호를 입력하세요。시스템에서 자동으로 정보를 대조하여 인증하고 개인정보를 안전하게 보호합니다。정보가 정확한데도 인증되지 않으면 온라인 고객 지원 또는 전담 담당자에게 문의하세요",
  "您将通过选择的%0个审批事项 ?": "선택한 결재 항목 %0개를 승인할까요 ?",
  "试用、免费版需组织完成身份认证后可充值信用点；对外分享、自定义短信签名等功能需完成企业身份认证": "체험판 및 무료 버전은 조직 인증 완료 후 크레딧을 충전할 수 있습니다；외부 공유、사용자 지정 문자 발신 서명 등의 기능은 기업 인증을 완료해야 사용할 수 있습니다",
  "对外分享、自定义短信签名等功能需完成企业身份认证": "외부 공유、사용자 지정 문자 발신 서명 등의 기능은 기업 인증을 완료해야 사용할 수 있습니다",
  "应短信运营商要求，需完成企业身份认证才可自定义短信签名": "문자 통신사의 요구에 따라，기업 인증을 완료해야 사용자 지정 발신 서명을 사용할 수 있습니다",
  "流程分享": "프로세스 공유",
  "完成企业认证": "기업 인증 완료",
  "暂无可见动态": "표시할 피드가 없습니다",
