  "启用水印配置后，将在外部门户门户所有页面显示水印。可自定义水印文字": "워터마크 설정을 활성화하면 외부 포털의 모든 페이지에 워터마크가 표시됩니다。워터마크 텍스트를 지정할 수 있습니다",
