  "发送至中国大陆地区的短信服务由平台提供，费用自动从组织信用点中扣除": "중국 본토로 발송하는 문자 서비스는 플랫폼에서 제공하며，요금은 조직 크레딧에서 자동 차감됩니다",
  "；发送港澳台/国际短信，需组织集成国际短信服务。": "；홍콩·마카오·대만/국제 문자를 발송하려면 조직에서 국제 문자 서비스를 연동해야 합니다。",
  "使用文本类型字段必须包含手机区号（+86），否则无法发送。": "텍스트 유형 필드를 사용하려면 국가 전화번호 코드（+86）를 포함해야 합니다，그렇지 않으면 발송할 수 없습니다。",
  "提示:": "안내:",
  "发送港澳台或国际短信需先配置服务商，否则将无法送达。请前往组织后台完成配置。": "홍콩·마카오·대만 또는 국제 문자를 발송하려면 먼저 서비스 제공업체를 설정해야 하며，그렇지 않으면 전달되지 않습니다。조직 관리에서 설정을 완료하세요。",
  "标点、空格及字母均计为 1 个字。发送至中国大陆地区的短信超 70 字（含签名）按 67 字/条计费。": "문장 부호、공백 및 영문자는 각각 1자로 계산합니다。중국 본토로 발송하는 문자가 70자（발신 서명 포함）를 초과하면 67자당 1건으로 과금됩니다。",
  "注意：若发送对象为外部用户，请选择与外部门户一致的微信服务号，否则会发送失败。": "참고：수신자가 외부 사용자인 경우，외부 포털과 동일한 WeChat 서비스 계정을 선택하세요，그렇지 않으면 발송에 실패합니다。",
  "请输入检索内容": "검색 내용을 입력하세요",
  "从向量知识库数组获取数据": "벡터 지식 베이스 배열에서 데이터 가져오기",
  "检索%0个知识库": "지식 베이스 %0개 검색",
  "更多动作": "추가 작업",
  "查询向量知识库": "벡터 지식 베이스 조회",
  "类目开票": "분류별 청구서 발행",
  "按“开票类目”合并汇总，每个类目生成一条发票明细行，开票更快捷，适合汇总开票场景。": "“청구서 발행 분류”별로 합산하여 각 분류에 하나의 청구서 상세 행을 생성합니다。발행이 더 빠르며，통합 청구서 발행에 적합합니다。",
  "明细开票": "상세 내역별 청구서 발행",
  "按订单/商品明细逐条生成发票明细行，便于与订单——对账。": "주문/상품 상세 내역별로 청구서 상세 행을 생성하여，주문과 대조하기 쉽습니다。",
  "需要”工作流获取组织信息”权限才可以添加": "추가하려면 ”워크플로에서 조직 정보 가져오기” 권한이 필요합니다",
