  "选择后，提取第一个分割符前的文本进行匹配。如：张三-简历.pdf，设置分割符-，则使用张三匹配工作表字段": "선택하면 첫 번째 구분자 앞의 텍스트로 일치 항목을 찾습니다。예：홍길동-이력서.pdf에서 구분자를 -로 설정하면，홍길동으로 워크시트 필드와 비교합니다",
  "选择分隔符": "구분자 선택",
