  "将应用数据转化为 AI 可理解的知识。通过向量化技术，实现基于自然语言的语义检索": "애플리케이션 데이터를 AI가 이해할 수 있는 지식으로 변환합니다。벡터화 기술로 자연어 기반 시맨틱 검색을 지원합니다",
