  "删除后，所有向量化内容将被永久清空，相关工作流节点将无法检索此知识库。": "삭제하면 모든 벡터화된 내용이 영구 삭제되며，관련 워크플로 노드에서 이 지식 베이스를 검색할 수 없습니다。",
  "我确认删除知识库及所有向量化内容": "지식 베이스 및 모든 벡터화된 내용의 삭제를 확인합니다",
  "重新初始化知识库": "지식 베이스 다시 초기화",
  "确认后，将先删除所有内容，再重新初始化。在此期间无法检索该知识库。": "확인하면 먼저 모든 내용을 삭제한 후 다시 초기화합니다。이 기간에는 해당 지식 베이스를 검색할 수 없습니다。",
