  "统计设置": "통계 설정",
  "设置需要统计的字段及其统计方式": "통계를 계산할 필드 및 계산 방식 설정",
  "可在表格中查看更多字段数据，最大批量选中的记录数量为100条。": "테이블에서 더 많은 필드 데이터를 볼 수 있으며，한 번에 최대 100개 레코드를 선택할 수 있습니다。",
  "列表仅显示标题字段，支持批量选中更多记录。": "목록에 제목 필드만 표시하며，더 많은 레코드를 일괄 선택할 수 있습니다。",
  "使用该节点对象": "이 노드 객체 사용",
  "流程中止时更新": "프로세스 중단 시 업데이트",
  "流程中止后，更新数据对象的字段值": "프로세스 중단 후，데이터 객체의 필드 값 업데이트",
  "审批流程中允许查看他人填写字段": "결재 프로세스에서 다른 사람이 작성한 필드 보기 허용",
  "新增失败时继续执行": "추가 실패 시 계속 실행",
  "审批和填写节点中查看他人填写内容": "결재 및 작성 노드에서 다른 사람의 작성 내용 보기",
  "未勾选时，如果新增失败（如工作表中配置了唯一索引）则中止流程。勾选后，则仍继续执行，此时本节点数据对象为空，后续节点在使用本节点时将跳过。": "선택하지 않으면 추가 실패 시（워크시트에 고유 인덱스가 설정된 경우 등）프로세스가 중단됩니다。선택하면 계속 실행되며，이 노드의 데이터 객체는 비어 있게 됩니다。이후 노드에서 이 노드를 사용할 때는 건너뜁니다。",
  "最多重复": "최대 반복 횟수",
  "检索类型": "검색 유형",
  "检索类召回数量(TOP K)": "검색 결과 수(TOP K)",
  "融合排序参数": "결합 순위 매개변수",
  "用于融合“向量+全文”的排序。数值越大排序波动越小，越小越强调最靠前结果；建议默认 60。": "“벡터+전문” 검색 순위를 결합하는 데 사용합니다。값이 클수록 순위 변동이 작고，작을수록 최상위 결과를 강조합니다；기본값 60을 권장합니다。",
  "相关度阈值": "관련도 임계값",
  "低于该值的结果将被过滤；调高更严格（结果更少更准），调低更宽松（结果更多）。": "이 값보다 낮은 결과는 제외됩니다；값을 높이면 더 엄격해지고（결과가 적고 정확해짐），낮추면 더 관대해집니다（결과가 많아짐）。",
  "其他应用下的知识库": "다른 애플리케이션의 지식 베이스",
  "检索内容": "검색 내용",
  "混合检索：同时使用语义理解和关键词匹配，兼顾精准度和全面性，效果最均衡。": "하이브리드 검색：의미 이해와 키워드 일치를 함께 사용하여，정확도와 검색 범위를 균형 있게 확보합니다。",
  "AI 智能选择：由系统智能判断最合适的检索方式，无需手动选择，适合大多数场景。": "AI 자동 선택：시스템이 가장 적합한 검색 방식을 자동으로 판단하므로 수동 선택이 필요 없으며，대부분의 상황에 적합합니다。",
  "语义检索：根据问题的含义去理解和匹配，即使用词不同也能找到相关内容，适合自然语言提问。": "시맨틱 검색：질문의 의미를 이해하여 일치하는 내용을 찾으며，다른 표현을 사용해도 관련 내용을 찾을 수 있어 자연어 질문에 적합합니다。",
  "关键词检索：根据关键词进行匹配查找，适合搜索包含特定词汇、名称或编号的内容。": "키워드 검색：키워드 일치로 검색하며，특정 단어、이름 또는 번호가 포함된 내용을 찾는 데 적합합니다。",
  "所有位置": "모든 위치",
  "指定位置": "지정 위치",
  "固定位置": "고정 위치",
  "默认视图显示": "기본 보기 표시",
  "当前位置需要站点使用 HTTPS 才能生效；否则将使用默认城市。": "현재 위치를 사용하려면 사이트가 HTTPS를 사용해야 합니다；그렇지 않으면 기본 도시를 사용합니다。",
  "设置位置": "위치 설정",
  "成员字段用于识别重复记录时，仅支持“人员ID”匹配，请修改匹配方式": "구성원 필드로 중복 레코드를 식별할 때는 “사용자 ID” 일치만 지원합니다，일치 방식을 변경하세요",
  "支持的字段类型：文本、电话、邮箱、证件、自动编号、记录ID、成员(单选)。选择多个字段时需同时匹配(\"且\"关系)，最多支持5个字段": "지원되는 필드 유형：텍스트、전화번호、이메일、신분증、자동 번호、레코드 ID、구성원(단일 선택)。여러 필드를 선택하면 모두 일치해야 하며(\"AND\" 관계)，최대 5개 필드를 지원합니다",
  "新增%0行记录，更新%1行记录，其中%2个附件导入失败": "레코드 %0행 추가，레코드 %1행 업데이트，첨부 파일 %2개 가져오기 실패",
  "非组织超级管理员无法修改组织超级管理员姓名/手机号/邮箱": "조직 최고 관리자만 조직 최고 관리자의 이름/휴대폰 번호/이메일을 수정할 수 있습니다",
  "，可": "，가능",
  "选择知识范围（1/3）": "지식 범위 선택（1/3）",
  "配置向量字段（2/3）": "벡터 필드 설정（2/3）",
  "设置名称和说明（3/3）": "이름 및 설명 설정（3/3）",
  "配置 “%0” 数据过滤条件": "“%0” 데이터 필터 조건 설정",
  "开始创建向量知识库": "벡터 지식 베이스 생성 시작",
  "点击创建后，将先为您计算分块数量和向量化预计消耗的token量，确认后开始正式执行向量化": "생성을 클릭하면 먼저 청크 수와 벡터화에 필요한 예상 토큰 사용량을 계산하며，확인 후 벡터화를 실행합니다",
  "没有可选的工作表": "선택 가능한 워크시트가 없습니다",
  "为选中的工作表添加需要语义分析的文本类型字段或记录讨论": "선택한 워크시트에서 의미 분석할 텍스트 유형 필드 또는 레코드 토론을 추가하세요",
  "AI 推荐方案": "AI 추천 계획",
