  "将使用模型：%0 进行初始化。初始化完成可正常使用": "초기화에 사용할 모델：%0。초기화가 완료되면 정상적으로 사용할 수 있습니다",
  "初始化过程中，无法修改知识库范围": "초기화 중에는 지식 베이스 범위를 수정할 수 없습니다",
  "记录：%0 个分块": "레코드：청크 %0개",
