  "附件：%0 个分块": "첨부 파일：청크 %0개",
  "共 %0 个分块": "총 청크 %0개",
  "正在为数据库\"向量数据库名称\"添加新的工作表，请为选中的工作表添加需要语义分析的文本类型字段或记录讨论": "데이터베이스 \"벡터 데이터베이스 이름\"에 새 워크시트를 추가하고 있습니다，선택한 워크시트에서 의미 분석할 텍스트 유형 필드 또는 레코드 토론을 추가하세요",
  "对已向量化的数据同时生效": "이미 벡터화된 데이터에도 적용",
  "知识范围或解析方式有调整。确认保存后将对已向量化的数据重新向量化。重新向量化需要一定时间，此期间该知识源暂无法被检索。": "지식 범위 또는 분석 방식이 변경되었습니다。저장을 확인하면 이미 벡터화된 데이터를 다시 벡터화합니다。재벡터화에는 시간이 걸리며，이 기간에는 해당 지식 소스를 검색할 수 없습니다。",
  "知识范围或解析方式有调整，确认保存后将对新变更的数据生效，历史数据不受影响。": "지식 범위 또는 분석 방식이 변경되었습니다，저장을 확인하면 새로 변경된 데이터에 적용되며，기존 데이터에는 영향을 주지 않습니다。",
  "重新向量化工作表": "워크시트 다시 벡터화",
  "确认后，将先删除所有内容，再重新向量化。在此期间无法检索此工作表。": "확인하면 먼저 모든 내용을 삭제한 후 다시 벡터화합니다。이 기간에는 해당 워크시트를 검색할 수 없습니다。",
  "我确认重新向量化工作表": "워크시트 재벡터화를 확인합니다",
  "删除数据源 “%0”": "데이터 소스 “%0” 삭제",
  "删除后，工作表中所有向量化内容将被永久清空，且无法被语义检索到。": "삭제하면 워크시트의 모든 벡터화된 내용이 영구 삭제되며，시맨틱 검색으로 찾을 수 없습니다。",
  "我确认删除所有向量化内容": "모든 벡터화된 내용의 삭제를 확인합니다",
  "查看分块位置": "청크 위치 보기",
