  "检索方式": "검색 방식",
  "召回数量(TOP K)": "검색 결과 수(TOP K)",
  "最低相关度": "최소 관련도",
  "RRF 融合参数": "RRF 결합 매개변수",
  "优化名称、图标": "이름 및 아이콘 개선",
  "优化名称": "이름 개선",
  "优化图标": "아이콘 개선",
  "开始优化": "개선 시작",
  "我根据当前应用信息，智能优化名称、图标。如果您对优化内容有具体要求也可以告诉我。": "현재 애플리케이션 정보를 바탕으로 이름과 아이콘을 개선합니다。개선할 내용에 구체적인 요구 사항이 있으면 알려 주세요。",
  "启用后，超过保留周期的执行历史将自动删除且不可找回（不包含审批流程执行历史），请谨慎使用。": "활성화하면 보관 기간이 지난 실행 기록이 자동 삭제되며 복구할 수 없습니다（결재 프로세스 실행 기록 제외），신중하게 사용하세요。",
  "勾选后，超过保留周期的执行历史将自动删除且不可找回，请谨慎使用。": "선택하면 보관 기간이 지난 실행 기록이 자동 삭제되며 복구할 수 없습니다，신중하게 사용하세요。",
  "未设置时，检索所有类型": "설정하지 않으면 모든 유형 검색",
  "最大召回数 (Top K)": "최대 검색 결과 수 (Top K)",
  "无可选工作表": "선택 가능한 워크시트가 없습니다",
  "AI 推荐": "AI 추천",
  "暂时无法查看分块": "현재 청크를 볼 수 없습니다",
  "知识库模型不可用，知识库无法进行更新和检索。": "지식 베이스 모델을 사용할 수 없어，지식 베이스를 업데이트하거나 검색할 수 없습니다。",
  "使用平台模型重新初始化": "플랫폼 모델로 다시 초기화",
  "知识库未启用，无法进行检索。": "지식 베이스가 활성화되지 않아，검색할 수 없습니다。",
  "重新初始化知识库 %0": "지식 베이스 %0 다시 초기화",
  "知识库当前模型Qwen Embedding-v3-0.6b已失效。确认后，系统将先删除所有内容，并使用平台默认嵌入模型Qwen Embedding-v3-8b重新初始化。": "지식 베이스의 현재 모델 Qwen Embedding-v3-0.6b가 유효하지 않습니다。확인하면 시스템이 먼저 모든 내용을 삭제한 후，플랫폼 기본 임베딩 모델 Qwen Embedding-v3-8b로 다시 초기화합니다。",
  "最大召回数（TOP K）": "최대 검색 결과 수（TOP K）",
  "错误详情": "오류 상세 정보",
  "全部忽略": "모두 무시",
  "全部重试": "모두 다시 시도",
  "失败详情": "실패 상세 정보",
  "源字段": "원본 필드",
  "Twilio 国际短信": "Twilio 국제 문자",
  "调用微信支付失败": "WeChat Pay 호출 실패",
  "主表": "기본 테이블",
  "动态表格": "동적 테이블",
  "选择主表": "기본 테이블 선택",
  "请选择打印数据的主表。系统将以该表作为主要数据来源，其余表将自动按动态表格（关联类型）处理。": "인쇄 데이터의 기본 테이블을 선택하세요。시스템은 이 테이블을 주요 데이터 소스로 사용하며，나머지 테이블은 자동으로 동적 테이블（연결 유형）로 처리합니다。",
  "开放平台提供的 appId 与 appSecret，用于完成与第三方云打印服务的安全对接。配置完成后，系统将通过云端接口向快麦云发送打印指令，由快麦云负责将数据转发至已绑定的打印设备，实现小票、标签等场景的远程打印。": "개방형 플랫폼에서 제공하는 appId와 appSecret은 타사 클라우드 인쇄 서비스와의 안전한 연동에 사용됩니다。설정 완료 후 시스템은 클라우드 API를 통해 Kuaimai Cloud에 인쇄 명령을 전송하며，Kuaimai Cloud는 데이터를 연결된 인쇄 장치로 전달하여 영수증、라벨 등을 원격으로 인쇄합니다。",
  "appId": "appId",
  "确认退出？": "나갈까요？",
  "当前内容校验未通过，确认是否退出。": "현재 내용이 유효성 검사를 통과하지 못했습니다，나갈지 확인하세요。",
  "Microsoft Entra 管理员已授权此组织，平台将以只读方式访问您的Microsoft Entra目录，用于同步员工账号信息，不会修改任何数据。": "Microsoft Entra 관리자가 이 조직에 권한을 부여했습니다。플랫폼은 직원 계정 정보를 동기화하기 위해 Microsoft Entra 디렉터리에 읽기 전용으로 접근하며，어떤 데이터도 수정하지 않습니다。",
  "知识库向量化": "지식 베이스 벡터화",
  "“%0” 分块成功，共 %1 个分块。确认后，进行向量化入库": "“%0” 청킹 완료，총 %1개 청크입니다。확인 후 벡터화하여 저장합니다",
  "知识库向量化入库中...": "지식 베이스 벡터화 및 저장 중...",
  "“%0” 向量化入库中...": "“%0” 벡터화 및 저장 중...",
