  "“%0” 向量化入库完成": "“%0” 벡터화 및 저장 완료",
  "允许用户读写指定数据库": "사용자가 지정한 데이터베이스를 읽고 쓰도록 허용",
  "只在admin数据库中可用，赋予用户所有分片和复制集相关函数的管理权限;": "admin 데이터베이스에서만 사용할 수 있으며，사용자에게 모든 샤드 및 복제본 세트 관련 함수의 관리 권한을 부여합니다;",
  "只在admin数据库中可用，赋予用户所有数据库的读权限;": "admin 데이터베이스에서만 사용할 수 있으며，사용자에게 모든 데이터베이스의 읽기 권한을 부여합니다;",
  "只在admin数据库中可用，赋予用户所有数据库的userAdmin权限;": "admin 데이터베이스에서만 사용할 수 있으며，사용자에게 모든 데이터베이스의 userAdmin 권한을 부여합니다;",
  "只在admin数据库中可用，赋予用户所有数据库的dbAdmin权限;": "admin 데이터베이스에서만 사용할 수 있으며，사용자에게 모든 데이터베이스의 dbAdmin 권한을 부여합니다;",
  "对数值、日期、文本进行数学或函数运算": "숫자、날짜、텍스트에 수학 연산 또는 함수 연산 수행",
