  "生成链接后复制进”PC端首页地址“即可使用": "링크를 생성한 후 ”PC 홈페이지 주소“에 복사하면 사용할 수 있습니다",
  "1. 前往钉钉开发者平台 — 定位到“应用开发”": "1. DingTalk 개발자 플랫폼으로 이동 — “애플리케이션 개발” 찾기",
  "前往钉钉开发者平台 — 定位到“应用开发”": "DingTalk 개발자 플랫폼으로 이동 — “애플리케이션 개발” 찾기",
  "选择“应用开发”下的“企业内部应用”": "“애플리케이션 개발” 아래의 “기업 내부 애플리케이션” 선택",
  "2. 点击创建应用，完善应用信息": "2. 애플리케이션 생성을 클릭하고 애플리케이션 정보 입력",
  "3. 完善接口信息": "3. API 정보 입력",
  "定位到“网页应用”的 网页应用配置信息，讲以下链接填入对应输入框内": "“웹 애플리케이션”의 설정 정보로 이동하여，아래 링크를 해당 입력란에 입력하세요",
  "切换至“凭证与基础信息”，将AgentId、ClientId、ClientScret分别填入明道云的“组织管理 - 企业身份 - 钉钉 - 对接信息录入”对应输入框内": "“자격 증명 및 기본 정보”로 전환한 후，AgentId、ClientId、ClientScret을 Mingdao의 “조직 관리 - 기업 신원 - DingTalk - 연동 정보 입력”에 있는 각 입력란에 입력하세요",
  "4.申请开通企业通讯录权限": "4.기업 연락처 접근 권한 신청",
  "重置知识库": "지식 베이스 초기화",
  "确认后将清空数据并重新分块（期间不可检索），分块完成后需您再次确认以开始向量化。": "확인하면 데이터를 비우고 다시 청킹합니다（진행 중 검색 불가），청킹 완료 후 다시 확인해야 벡터화를 시작합니다。",
  "我确认重置知识库": "지식 베이스 초기화를 확인합니다",
  "当前记录，没有讨论内容": "현재 레코드에 토론 내용이 없습니다",
  "分块计算成功，共 %0 个。当前组织剩余额度不足，尚缺 %1 分块，无法完成向量化入库。请联系管理员增购额度。": "청크 계산 완료，총 %0개입니다。현재 조직의 잔여 한도가 부족하며，청크 %1개가 더 필요하여 벡터화 및 저장을 완료할 수 없습니다。관리자에게 한도 추가 구매를 요청하세요。",
  "分块计算成功，共 %0 个分块": "청크 계산 완료，총 %0개 청크",
  "%0 个分块": "청크 %0개",
  "已绑定 %0 个": "%0개 연결됨",
  "绑定服务号": "서비스 계정 연결",
  "附件解析增强": "첨부 파일 고급 분석",
  "该应用已被 %0 设为维护状态，暂停访问": "%0이 이 애플리케이션을 유지보수 상태로 설정하여，접근이 일시 중지되었습니다",
  "请选择%0对应的日期": "%0에 해당하는 날짜를 선택하세요",
  "添加失败：%0": "추가 실패：%0",
  "每%0周(%1) %2": "%0주마다(%1) %2",
  "请输入Messaging Service SID": "Messaging Service SID를 입력하세요",
  "购买向量知识库分块数": "벡터 지식 베이스 청크 구매",
  "扩充向量知识库分块数": "벡터 지식 베이스 청크 수 확장",
  "100 元/1万块/年（版本剩余时间）": "청크 1만 개당 연 100위안（버전 잔여 기간）",
  "选择向量化内容：支持标题、文本、文本组合、富文本、级联/关联（单条）、附件字段，以及讨论（含附件）。每条记录为一个分块，包含字段名和字段值，最高容纳 3500 字；附件、记录讨论按规则单独分块。": "벡터화할 내용 선택：제목、텍스트、텍스트 조합、서식 있는 텍스트、종속 선택/연결（단일）、첨부 파일 필드 및 토론（첨부 파일 포함）을 지원합니다。레코드마다 하나의 청크로 구성되며，필드 이름과 값을 포함하여 최대 3500자까지 저장합니다；첨부 파일과 레코드 토론은 규칙에 따라 별도로 청킹합니다。",
  "开启后，对 %0 格式的附件使用视觉模型解析，提升复杂文档的结构还原准确率。": "활성화하면 %0 형식의 첨부 파일을 비전 모델로 분석하여，복잡한 문서의 구조 복원 정확도를 높입니다。",
  "\"打开Outlook，在工具>账户设置>Internet日历中新建，并粘贴\n刚才获得的ICAL格式日历地址\"": "\"Outlook을 열고 도구>계정 설정>인터넷 일정에서 새로 만들기를 선택한 후，\n앞서 복사한 ICAL 형식의 일정 주소를 붙여넣으세요\"",
  "每%0周(%1) %2 触发": "%0주마다(%1) %2에 트리거",
  "限时免费": "기간 한정 무료",
  "确认后将清空数据并重新分块（期间不可检索），分块完成后需您再次确认以开始向量数据入库。": "확인하면 데이터를 비우고 다시 청킹합니다（진행 중 검색 불가），청킹 완료 후 다시 확인해야 벡터 데이터를 데이터베이스에 저장하기 시작합니다。",
