  "导入 Excel": "Excel 가져오기",
  "发票备注销方信息": "청구서 비고의 판매자 정보",
  "开启后，支付订单及工作流开票的发票备注中将自动附加销方相关信息；需在百望云-基础-配置管理的销方信息页面完善销方信息。": "활성화하면 결제 주문 및 워크플로에서 발행하는 청구서의 비고에 판매자 정보가 자동으로 추가됩니다；Baiwang Cloud-기본-설정 관리의 판매자 정보 페이지에서 판매자 정보를 모두 입력해야 합니다。",
  "只勾选微信登录时首次扫码后需要输入手机号与微信绑定，后续可单独微信扫码快速登录。": "WeChat 로그인만 선택하면 처음 QR 코드를 스캔한 후 휴대폰 번호를 입력하여 WeChat에 연결해야 합니다。이후에는 WeChat QR 코드 스캔만으로 빠르게 로그인할 수 있습니다。",
  "发送验证码的短信或邮件费用将自动从组织信用点中扣除。": "인증 코드 발송에 사용되는 문자 또는 이메일 요금은 조직 크레딧에서 자동 차감됩니다。",
  "FINDA(原文本, 开始字符, 结束字符)": "FINDA(원본 텍스트, 시작 문자, 종료 문자)",
