  "组织授权到期，知识库暂不可用": "조직 라이선스가 만료되어 지식 베이스를 일시적으로 사용할 수 없습니다",
  "请先完成签名": "먼저 서명을 완료하세요",
  "根据当前记录内容，自动执行数据查询、字段更新、邮件发送等一系列复杂任务。": "현재 레코드 내용을 바탕으로，데이터 조회、필드 업데이트、이메일 발송 등 일련의 복잡한 작업을 자동 실행합니다。",
  "一键配置，即刻自动化。": "한 번의 설정으로 즉시 자동화。",
