  "密钥名称不能为空": "키 이름을 입력하세요",
  "创建密钥": "키 생성",
  "密钥创建完成后不能修改，请及时保存": "키는 생성 후 수정할 수 없습니다，바로 저장하세요",
  "密钥名称": "키 이름",
  "AI模型服务": "AI 모델 서비스",
  "确定禁用此密钥?": "이 키를 비활성화할까요?",
  "禁用后，此密钥提供的云服务将会调用失败，导致相关功能异常。": "비활성화하면 이 키를 사용하는 클라우드 서비스 호출이 실패하여，관련 기능에 오류가 발생합니다。",
  "禁用": "비활성화",
  "确定删除此密钥?": "이 키를 삭제할까요?",
  "删除后，此密钥提供的云服务将会调用失败，导致相关功能异常。": "삭제하면 이 키를 사용하는 클라우드 서비스 호출이 실패하여，관련 기능에 오류가 발생합니다。",
