  "密钥创建成功": "키 생성 완료",
  "请妥善保存您的密钥，因为创建后将无法再次查看。如果遗失，您需要重新生成": "생성 후에는 키를 다시 확인할 수 없으므로 안전하게 보관하세요。분실하면 다시 생성해야 합니다",
  "白名单最多支持 100 条": "허용 목록은 최대 100개 항목을 지원합니다",
  "请输入正确的 IP 地址或 CIDR 网段": "올바른 IP 주소 또는 CIDR 대역을 입력하세요",
  "可设置多个，需要用英文字符\",\"或换行隔开": "여러 개 설정할 수 있으며，영문 문자 \",\" 또는 줄바꿈으로 구분하세요",
  "请输入 IP 白名单": "IP 허용 목록을 입력하세요",
  "组织 - 云服务": "조직 - 클라우드 서비스",
  "云服务": "클라우드 서비스",
  "云服务用于调用明道云提供的在线服务能力（如 AI 模型服务）。创建云服务密钥后，可在接口调用中使用该密钥进行身份校验，便于统一管理授权与调用记录。为了增强安全性，API 密钥采用加密存储；创建后的密钥将不再以明文形式展示。请在创建时及时复制您的密钥，之后无法重新查看。": "클라우드 서비스로 Mingdao에서 제공하는 온라인 서비스 기능（AI 모델 서비스 등）을 호출할 수 있습니다。클라우드 서비스 키를 생성하면 API 호출 시 해당 키로 인증할 수 있어，권한과 호출 내역을 통합 관리하기 쉽습니다。보안을 강화하기 위해 API 키는 암호화되어 저장됩니다；생성된 키는 다시 일반 텍스트로 표시되지 않습니다。이후 다시 확인할 수 없으므로 생성할 때 키를 복사하세요。",
  "使用平台级 OAuth 应用": "플랫폼 수준 OAuth 애플리케이션 사용",
  "已开启：": "활성화됨：",
  "使用个人访问凭证": "개인용 접근 자격 증명 사용",
  "个人 API 访问策略": "개인 API 접근 정책",
  "允许使用以下授权方式，按个人身份权限调用 API 访问组织数据": "다음 인증 방식을 사용하여 개인 권한으로 API를 호출하고 조직 데이터에 접근하도록 허용",
  "会同步开启/关闭平台级 OAuth 应用集成配置": "플랫폼 수준 OAuth 애플리케이션 연동 설정도 함께 켜거나 끕니다",
  "销售邮件": "영업 이메일",
  "关闭后，用户将不允许选择当前组织生成个人访问凭证，且已生成的凭证会立即失效": "끄면 사용자가 현재 조직을 선택하여 개인용 접근 자격 증명을 생성할 수 없으며，이미 생성된 자격 증명은 즉시 무효화됩니다",
  "限制成员使用个人身份权限（OAuth 授权、个人访问凭证）直接调用 API，降低数据外泄风险。": "구성원이 개인 자격의 권한（OAuth 권한 부여、개인용 접근 자격 증명）으로 API를 직접 호출하는 것을 제한하여，데이터 유출 위험을 줄입니다。",
  "财务邮件": "재무 이메일",
  "财务管理": "재무 관리",
  "工资管理": "급여 관리",
  "资金报销": "비용 정산",
  "未配置邮箱": "이메일 미설정",
  "应用邮件服务": "애플리케이션 이메일 서비스",
  "其他所有应用": "기타 모든 애플리케이션",
  "所有应用默认使用默认服务。如需为特定应用（如工作流、外部门户）更改发送服务，请将其添加至对应的邮件服务下": "모든 애플리케이션은 기본 발송 서비스를 사용합니다。특정 애플리케이션（워크플로、외부 포털 등）의 발송 서비스를 변경하려면，해당 이메일 서비스에 애플리케이션을 추가하세요",
  "配置应用于工作流、外部门户的邮件通知使用的发送服务": "워크플로 및 외부 포털의 이메일 알림에 사용할 발송 서비스 설정",
