  "解析出 %0 个组织下成员，请确认": "조직 소속 구성원 %0명을 식별했습니다，확인하세요",
  "请输入需要办理离职的成员 ID，每行输入一个。最多批量离职50个成员": "퇴사 처리할 구성원 ID를 한 줄에 하나씩 입력하세요。한 번에 최대 50명을 퇴사 처리할 수 있습니다",
