  "个人访问令牌可以您个人的权限操作 HAP 数据，可以选择授予令牌访问的权限及数据数据范围，为保护您账户的安全，不要与他人共享您的个人访问令牌。": "개인용 접근 토큰으로 개인 권한에 따라 HAP 데이터를 조작할 수 있으며，토큰에 부여할 접근 권한 및 데이터 범위를 선택할 수 있습니다。계정 보안을 위해 개인용 접근 토큰을 다른 사람과 공유하지 마세요。",
  "创建个人访问令牌": "개인용 접근 토큰 생성",
