  "短信内容包含链接：短信将只能使用签名 【明道云】（不可删除）。 短信内容不包含链接：可使用自定义签名；可在短信里描述外部门户的打开路径替代链接地址。": "문자 내용에 링크가 포함된 경우：문자 발신 서명은 【明道云】만 사용할 수 있습니다（삭제 불가）。 문자 내용에 링크가 없는 경우：사용자 지정 발신 서명을 사용할 수 있습니다；링크 주소 대신 문자에 외부 포털을 여는 경로를 설명할 수 있습니다。",
