  "短信收费标准：短信%0/条，自动从企业账户中心扣除。70字计一条短信，超过70字以67字每条计费。每个标点、空格、英文字母都算一个字。短信实际发送可能有10-20分钟的延时。": "문자 요금 기준: 문자당 %0, 기업 계정 센터에서 자동 차감됩니다. 70자까지는 1건으로 계산하며, 70자를 초과하면 67자마다 1건으로 과금됩니다. 모든 구두점, 공백, 영문자 각각은 1자로 계산됩니다. 실제 발송에는 10~20분 지연될 수 있습니다.",
  "发票金额：": "청구서 금액:",
  "表名称-视图名称": "표 이름-보기 이름",
  "尝试描述这个对话机器人的目标和功能，以及它为谁服务。例如:“订单统计助手，通过对话快速查询客户订单和明细，统计订单金额”": "이 대화형 챗봇의 목표와 기능, 그리고 대상 사용자를 간단히 설명하세요. 예: “주문 통계 도우미 — 대화를 통해 고객 주문 및 상세를 빠르게 조회하고, 주문 금액을 집계합니다.”",
