  "我可以为您的工作表添加一些示例数据，方便你进行数据测试。如果您对添加的数据有具体要求也可以告诉我。": "워크시트에 예시 데이터를 추가해 드릴게요. 데이터 테스트에 활용하세요. 추가할 데이터에 대한 구체적인 요구 사항이 있으면 알려주세요.",
  "验证码短信%0每条，自动从企业账户扣除，信用点不足时无法获取验证码。": "인증 코드 문자 메시지는 건당 %0이며, 기업 계정에서 자동 차감됩니다. 크레딧이 부족하면 인증 코드를 받을 수 없습니다.",
