  "当前企业税号已在其他组织开通电子开票服务；每个税号仅能开通一次，当前组织不可重复开通。": "현재 기업 세금 번호는 다른 조직에서 전자 청구서 서비스를 활성화했습니다；세금 번호당 한 번만 활성화할 수 있어，현재 조직에서는 중복 활성화할 수 없습니다。",
