  "2、电子发票由知名数电开票合作服务商": "2、전자 청구서는 전문 디지털 청구서 발행 제휴 서비스 제공업체",
  "1、完成组织的企业认证或已有支付商户号即可创建开票税号。每个开票税号开通后，享有 7 天免费试用": "1、조직의 기업 인증을 완료했거나 결제 가맹점 번호가 있으면 청구서 발행 세금 번호를 생성할 수 있습니다。각 세금 번호는 활성화 후 7일간 무료로 체험할 수 있습니다",
  "联系邮箱": "연락 이메일",
  "百望": "Baiwang",
  "提供。开票资料需与营业执照信息 保持一致，且真实有效": "에서 제공합니다。발행 정보는 사업자등록증과 일치하고，사실에 부합하며 유효해야 합니다",
  "发件人": "발신자",
  "3、已有百望账号？请联系组织管理员或平台客服人员，协助完成账号绑定": "3、기존 Baiwang 계정이 있나요？조직 관리자 또는 플랫폼 고객 지원에 계정 연결 지원을 요청하세요",
  "请您先在百望完成企业信息与登录验证等配置，否则无法开票。具体操作步骤请查看": "먼저 Baiwang에서 기업 정보 및 로그인 인증 등의 설정을 완료하세요，그렇지 않으면 청구서를 발행할 수 없습니다。자세한 절차는 다음을 확인하세요",
  "1、导入的“商品管理表”将作为开票时选择的商品类目/税收分类编码的数据来源。": "1、가져온 “상품 관리 테이블”은 청구서 발행 시 선택할 상품 분류/세금 분류 코드의 데이터 소스로 사용됩니다。",
  "开启并确认开票登录验证（验证码/人脸认证）以保障自动开票": "자동 발행을 위해 청구 로그인 인증(인증 코드/안면 인증)을 활성화하고 확인하세요.",
  "2、电子税局的商品管理表有更新时，请重新导入以同步最新税率与编码。": "2、전자 세무국의 상품 관리 테이블이 업데이트되면，다시 가져와 최신 세율 및 코드를 동기화하세요。",
  "开票主体(销方)": "청구서 발행 주체(판매자)",
  "完成组织认证": "조직 인증 완료",
  "请前往": "이동하세요.",
  "创建后不能更换且不能删除，请谨慎选择": "생성 후에는 변경하거나 삭제할 수 없습니다，신중하게 선택하세요",
  "企业税号（统一社会信用代码）": "기업 세금 번호（통합사회신용코드）",
  "开启后，在二级域名下使用飞书扫一扫，直接登录": "켜면 서브도메인에서 Feishu 스캔으로 바로 로그인합니다.",
  "用于接收百望账号开通等消息通知，已有百望账号时不会发送账号信息": "Baiwang 계정 활성화 등의 알림을 받는 데 사용하며，기존 Baiwang 계정이 있으면 계정 정보를 발송하지 않습니다",
  "开通7天试用": "7일 체험 시작",
  "流程待办同步至Lark审批中心": "프로세스 할 일 Lark 결재 센터로 동기화",
  "为当前开票税号开启 7 天免费试用，期间可正常开票；到期自动停用，购买后可继续使用。每个税号仅一次试用。": "현재 청구서 발행 세금 번호의 7일 무료 체험을 시작하며，체험 중에는 정상적으로 발행할 수 있습니다；만료 시 자동 비활성화되며，구매 후 계속 사용할 수 있습니다。세금 번호당 한 번만 체험할 수 있습니다。",
  "当组织信用点余额低于": "조직의 크레딧 잔액이 다음 값보다 낮을 때",
  "请先创建授权密钥": "먼저 권한 키를 생성하세요.",
  "开通中...": "활성화 중...",
  "确认开通": "활성화 확인",
  "每个选项单列一行。若选项与选项列表重复，保存时将忽略重复选项；若选项与回收站内选项重复，保存时将自动恢复回收站的选项": "각 옵션을 한 줄에 하나씩 입력하세요. 옵션이 옵션 목록과 중복되면 저장 시 중복 옵션은 무시됩니다. 옵션이 휴지통의 옵션과 중복되면 저장 시 휴지통의 옵션이 자동으로 복원됩니다.",
  "百望开票平台": "Baiwang 청구서 발행 플랫폼",
