  "使用邮件中的账号登录": "이메일로 받은 계정으로 로그인",
  "（账号与初始密码已发送至": "（계정 및 초기 비밀번호 발송 대상",
  "助力 AI 编程，选择密钥生成 MCP Server 配置，将下方 JSON 配置添加到 IDE 的 MCP 配置文件中，当 API 文档有更新时，Server也会同步更新，提示：必须安装 Node.js 环境（版本号 >= 18.0.0）。": "AI 코딩 지원. 키를 선택해 MCP Server 설정을 생성하세요. 아래 JSON 설정을 IDE의 MCP 설정 파일에 추가하세요. API 문서가 업데이트되면 Server도 함께 업데이트됩니다. 안내: Node.js 환경이 반드시 설치되어 있어야 합니다(버전 >= 18.0.0).",
  "新建关联表": "새 연관 테이블 생성",
  "补充/确认企业与税务信息，按照百望页面提交资质。": "기업 및 세금 정보를 추가/확인하고，Baiwang 페이지 안내에 따라 증빙을 제출하세요。",
