  "开启后，我的流程中的待办（待审批、待填写）同时会进入飞书待办任务，处理状态会同步更新": "켜두면 내 프로세스의 할 일(결재 대기, 작성 대기)이 동시에 Feishu 할 일에 등록되며, 처리 상태가 동기화됩니다.",
  "下载商品管理表，然后导入数据": "상품 관리 테이블을 다운로드한 후 데이터 가져오기",
