  "将自定义的选项转为选项集。选项集可以被其他选项字段中共用使用,并在应用中统一维护数据源": "사용자 지정 옵션을 옵션 세트로 변환하세요. 옵션 세트는 다른 옵션 필드에서 공용으로 사용할 수 있으며, 애플리케이션에서 데이터 소스를 일괄 관리합니다.",
  "现金": "현금",
  "包含应用、工作表、聚合表、应用角色、选项集 API、工作流": "애플리케이션, 워크시트, 집계 테이블, 애플리케이션 역할, 옵션 집합 API, 워크플로 포함",
  "包含附件的讨论": "첨부 파일이 포함된 토론",
  "输入发票抬头": "청구서 수취인 이름 입력",
  "4、审核操作通常由财务人员完成，建议在": "4. 검토 작업은 보통 재무 담당자가 수행합니다. 권장 설정: \"",
  "发票金额(含税)": "청구서 금액(세금 포함)",
