  "蓝字发票": "원본 청구서",
  "定义模型的查询范围，未配置意味着Agent会查询工作表中的所有数据": "모델의 조회 범위를 정의하세요. 설정하지 않으면 Agent가 워크시트의 모든 데이터를 조회합니다.",
  "跳过，暂不创建": "건너뛰기, 아직 생성하지 않음",
  "开启后，当月剩余执行额度为2%时，自动购买100信用点/1万次的单月包，自动从企业账务中心扣除（开启后仍可以在组织管理后台的工作流处关闭）": "켜두면 해당 월 남은 실행 한도가 2%일 때 100 크레딧/1만 회 단월 패키지를 자동 구매하고, 기업 결제 센터에서 자동 차감합니다. (켜둔 후에도 조직 관리 백오피스의 워크플로에서 끌 수 있음)",
  "张": "장",
  "最多充值金额 999999 信用点": "최대 충전 금액 999999 크레딧",
  "指定工作表": "워크시트 지정",
  "1、每个开票税号开通后，享有 7 天免费试用，到期后自动停用，付费开通后可继续使用": "1、각 청구서 발행 세금 번호는 활성화 후 7일간 무료로 체험할 수 있으며，만료 시 자동 비활성화됩니다。유료로 활성화하면 계속 사용할 수 있습니다",
  "维度和数值不能相同": "차원과 값은 같을 수 없습니다.",
  "开启后，当月剩余执行额度为2%时，自动购买 100信用点/10万行 的单月包，自动从企业账务中心扣除。（开启后可以在数据集成的同步任务中关闭）": "켜두면 당월 남은 실행 한도가 2%일 때 100 크레딧/10만 행의 월 단위 패키지를 자동 구매하며, 기업 결제 센터에서 자동 차감됩니다. (켜둔 뒤에는 데이터 연동의 동기화 작업에서 끌 수 있습니다)",
  "已关注 %0": "%0을(를) 팔로우 중입니다.",
  "2、一个税号仅可绑定一个组织，不可重复开通": "2、하나의 세금 번호는 하나의 조직에만 연결할 수 있으며，중복 활성화할 수 없습니다",
  "请选择聚合表": "집계 테이블을 선택하세요.",
  "用户对话后立即执行": "사용자 대화 직후 실행",
  "3、用户提交开票申请后，需由管理员在 开票记录 审核并确认，用户才能下载发票": "3、사용자가 청구서 발행을 신청하면，관리자가 청구서 발행 내역에서 심사 및 확인한 후 사용자가 청구서를 다운로드할 수 있습니다",
  "暂不支持当前设备": "현재 기기는 지원되지 않습니다.",
  "应付/结算": "미지급/정산",
  "从聚合表获取多条记录": "집계 테이블에서 다수 레코드 가져오기",
  "查看已删除选项(%0)": "삭제된 옵션 보기(%0)",
  "开启网络代理": "네트워크 프록시 활성화",
  "组织-管理员": "조직-관리자",
  "删除对话机器人": "대화형 봇 삭제",
  "AI推荐": "AI 추천",
  "选择充值信用点": "충전할 크레딧 선택",
  "附件可来自用户上传或工作表字段，智能体会将附件内容作为上下文传递给模型。使用该功能可能产生较多费用。图片、PDF 仅能在选择了具备图像识别能力的模型时解析；文档由文档识别服务解析。": "첨부 파일은 사용자 업로드 또는 워크시트 필드에서 가져올 수 있습니다. AI 에이전트가 첨부 파일의 내용을 컨텍스트로 모델에 전달합니다. 이 기능 사용 시 비용이 많이 발생할 수 있습니다. 이미지와 PDF는 이미지 인식 기능을 갖춘 모델을 선택한 경우에만 분석됩니다. 문서는 문서 인식 서비스로 분석됩니다.",
  "中配置财务角色，并将相关人员加入角色执行审核开票": "에서 재무 역할을 설정하고 관련 구성원을 추가하여 청구서 심사 및 발행을 수행하세요",
  "其它应用下的聚合表": "다른 애플리케이션의 집계 테이블",
  "确认继续退款？": "환불을 계속할까요？",
  "将当前字段的所有选项复制为文本,用于为其他选项字段批量添加相同选项": "현재 필드의 모든 옵션을 텍스트로 복사하여 다른 옵션 필드에 동일한 옵션을 일괄 추가합니다.",
  "请输入信用点": "크레딧을 입력하세요.",
  "图片上传中...": "이미지 업로드 중...",
  "所选关联字段 <b>%0</b> 暂无已有工作表，将为您创建工作表后再继续添加字段": "선택한 연관 필드 <b>%0</b>에 연결된 워크시트가 없습니다. 워크시트를 생성한 뒤 필드를 계속 추가합니다.",
  "当前订单正在申请开票，全额退款后，系统会将开票状态改为已取消": "현재 주문의 청구서 발행을 신청 중이며，전액 환불하면 시스템이 발행 상태를 취소됨으로 변경합니다",
  "确定以【信用点付款】方式进行本次付款？": "이번 결제를 신용 포인트로 진행할까요?",
