  "本次测试消耗 %0 tokens， 计费 %1 信用点": "이번 테스트에 %0 tokens이(가) 소모되었으며, 비용은 %1 크레딧입니다.",
  "如何实现飞书扫码登录": "Feishu QR 로그인 구현 방법",
  "继续退款": "환불 계속",
  "开启后，我的流程中的待办（待审批、待填写）同时会进入Lark待办任务，处理状态会同步更新": "켜면 내 프로세스의 할 일(결재 대기, 작성 대기)이 동시에 Lark 할 일에 추가되며, 처리 상태가 동기화되어 업데이트됩니다.",
  "支票": "수표",
  "识别中...": "인식 중...",
  "用于向使用者介绍应用的功能、使用方法和注意事项。填写的内容会在用户首次打开应用时展示。": "사용자에게 애플리케이션의 기능、사용 방법 및 주의 사항을 안내합니다。입력한 내용은 사용자가 애플리케이션을 처음 열 때 표시됩니다。",
