  "n.查看、创建、更新、删除审批应用相关信息": "n.결재 애플리케이션 관련 정보 조회、생성、업데이트、삭제",
  "o.查看、创建、更新、删除三方审批定义相关信息": "o.타사 결재 정의 관련 정보 조회、생성、업데이트、삭제",
  "需要增加两个待办相关的权限，请前往Lark开放平台找到当前集成的应用，在权限管理-点击开通权限找到审批相关的以下两个权限，选择并确认开通权限。": "할 일 관련 권한 2개를 추가해야 합니다。Lark 개방형 플랫폼에서 현재 연동된 애플리케이션을 찾아，권한 관리-권한 활성화를 클릭한 후 결재 관련 다음 두 권한을 선택하고 활성화를 확인하세요。",
  "需要增加两个待办相关的权限，请前往飞书开放平台找到当前集成的应用，在权限管理-点击开通权限找到审批相关的以下两个权限,选择并确认开通权限。": "할 일 관련 권한 2개를 추가해야 합니다。Feishu 개방형 플랫폼에서 현재 연동된 애플리케이션을 찾아，권한 관리-권한 활성화를 클릭한 후 결재 관련 다음 두 권한을 선택하고 활성화를 확인하세요。",
  "开通后需要重新发布版本，发布成功后才可生效。": "활성화 후 버전을 다시 게시해야 하며，게시가 완료되어야 적용됩니다。",
  "已停用，无法取消部门负责人": "비활성화되어，부서 책임자를 해제할 수 없습니다",
  "已停用，无法设置部门负责人": "비활성화되어，부서 책임자를 설정할 수 없습니다",
