  "开启后，Agent 按系统预设的格式、语气与结构回复；关闭后，可在提示词中约束回复格式。": "활성화하면 에이전트가 시스템의 기본 형식、어조 및 구조에 따라 답변하고；끄면 프롬프트에서 응답 형식을 지정할 수 있습니다。",
