  "通知所有讨论；取消关注仅@你或回复时通知。": "모든 토론 알림을 받습니다；팔로우를 해제하면 @멘션 또는 답글이 있을 때만 알림을 받습니다。",
  "将自定义选项转换为选项集，实现在应用中统一维护，并被其他字段引用。": "사용자 지정 선택 항목을 선택 항목 집합으로 변환하여，애플리케이션에서 통합 관리하고 다른 필드에서 참조할 수 있습니다。",
  "使用系统预设的回复风格": "시스템 기본 응답 스타일 사용",
  "开启后，Agent 按系统预设的格式、语气与结构回复；关闭后，可在提示词中约束回复风格。": "활성화하면 에이전트가 시스템의 기본 형식、어조 및 구조에 따라 답변하고；끄면 프롬프트에서 응답 스타일을 지정할 수 있습니다。",
  "对话触发后，系统将依序执行工作流中各节点。所有 AI Agent 节点的输出内容作为本轮对话的回复，依序展示给用户": "대화가 트리거되면 시스템은 워크플로의 각 노드를 순서대로 실행합니다。모든 AI 에이전트 노드의 출력 내용을 이번 대화의 응답으로 사용자에게 순서대로 표시합니다",
  "没有符合规则的数据": "규칙에 맞는 데이터가 없습니다",
