  "停用选项集 DELETE": "선택 항목 집합 비활성화 DELETE",
  "定位后拍照": "위치 확인 후 촬영",
  "可配置应用导航/分组、工作流、工作表、自定义页面、对话机器人、用户角色新增/编辑/删除（包含外部门角色）、外部门户设置（ 包含外部门户域名配置）": "애플리케이션 탐색/그룹、워크플로、워크시트、사용자 지정 페이지、챗봇、사용자 역할의 추가/편집/삭제（외부 포털 역할 포함）、외부 포털 설정（ 외부 포털 도메인 설정 포함）을 구성할 수 있습니다",
  "受运营商政策影响，含链接的邀请短信可能被拦截。如未收到短信，请通过邮箱或邀请链接发送邀请": "통신사 정책에 따라 링크가 포함된 초대 문자가 차단될 수 있습니다。문자를 받지 못하면 이메일 또는 초대 링크로 초대하세요",
  "详细": "상세",
  "勾选后，用户填写时可输入不在备选项中的内容，并添加至选项列表。若不勾选，通过工作流、API写入、批量导入等操作仍可将新的选项添加至选项列表。": "선택하면 사용자가 기존 선택 항목에 없는 내용을 입력하여 선택 목록에 추가할 수 있습니다。선택하지 않아도 워크플로、API 입력、일괄 가져오기 등의 작업으로 새 항목을 선택 목록에 추가할 수 있습니다。",
  "节点对象已删除": "노드 객체가 삭제되었습니다",
  "扣费记录存在约 5 分钟延迟，同时系统会将 5 分钟内相同操作自动合并成一条扣费记录，如5分钟内相同流程的扣费信息": "요금 차감 내역에는 약 5분의 지연이 있으며，시스템은 5분 내 동일한 작업을 하나의 차감 내역으로 자동 통합합니다。예를 들어 5분 내 동일한 프로세스의 요금 정보가 통합됩니다",
