  "的已使用附件上传量重置为0?": "의 첨부 파일 업로드 사용량을 0으로 초기화할까요?",
  "配置结构化输出后，无法使用预设风格": "구조화된 출력을 설정하면 기본 스타일을 사용할 수 없습니다",
  "默认定位到起始日期": "기본적으로 시작 날짜로 이동",
  "勾选后，打开时间选择器优先显示起始日期所在日期；未勾选时优先显示当前日期。": "선택하면 시간 선택기를 열 때 시작 날짜를 우선 표시하고；선택하지 않으면 현재 날짜를 우선 표시합니다。",
  "未能获取精确位置": "정확한 위치를 가져오지 못했습니다",
  "当前可能无法获取高精度坐标，定位结果可能仅为城市或区域范围。为提升定位准确性，可尝试：": "현재 정밀 좌표를 가져오지 못할 수 있으며，위치 결과가 도시 또는 지역 수준으로만 표시될 수 있습니다。위치 정확도를 높이려면 다음을 시도하세요：",
  "· 确认已开启系统定位服务及应用定位权限": "· 시스템 위치 서비스 및 애플리케이션 위치 권한이 활성화되어 있는지 확인하세요",
  "· 建议开启 Wi-Fi，可提升室内定位效果": "· Wi-Fi를 켜면 실내 위치 정확도가 높아질 수 있습니다",
  "· 若正在使用 VPN / 代理，尝试关闭后再试": "· VPN / 프록시를 사용 중이라면 끈 후 다시 시도하세요",
  "您仍可以继续尝试定位，但结果可能存在偏差。": "위치 확인을 계속 시도할 수 있지만，결과가 부정확할 수 있습니다。",
  "仍要定位": "위치 확인 계속",
  "对账 ID": "대조 ID",
  "正在获取经纬度，请稍后": "위도와 경도를 가져오고 있습니다，잠시 기다려 주세요",
  "等待上传": "업로드 대기",
  "异步执行的工作流扣费存在约 5 分钟延迟，同时系统会将 5 分钟内相同操作自动合并成一条扣费记录，如5分钟内相同流程的扣费信息": "비동기 워크플로의 요금 차감에는 약 5분의 지연이 있으며，시스템은 5분 내 동일한 작업을 하나의 차감 내역으로 자동 통합합니다。예를 들어 5분 내 동일한 프로세스의 요금 정보가 통합됩니다",
