  "1、每个开票税号开通后，到期后自动停用，付费开通后可继续使用": "1、각 청구서 발행 세금 번호는 활성화 후 만료 시 자동 비활성화되며，유료로 활성화하면 계속 사용할 수 있습니다",
  "只勾选微信登录时首次扫码后需要输入手机号与微信绑定，后续可单独微信扫码快速登录。发送验证码的短信或邮件费用将自动从组织信用点中扣除。": "WeChat 로그인만 선택하면 처음 QR 코드를 스캔한 후 휴대폰 번호를 입력하여 WeChat에 연결해야 합니다。이후에는 WeChat QR 코드 스캔만으로 빠르게 로그인할 수 있습니다。인증 코드 발송에 사용되는 문자 또는 이메일 요금은 조직 크레딧에서 자동 차감됩니다。",
  "选择用于 AIGC 的大语言模型。Token 消耗将从组织信用点扣除": "AIGC에 사용할 대규모 언어 모델을 선택하세요。토큰 사용 비용은 조직 크레딧에서 차감됩니다",
  "附件可来自用户上传或工作表字段，Agent 会将附件内容作为上下文传递给模型。使用该功能可能产生较多费用。": "사용자가 업로드한 파일 또는 워크시트 필드의 첨부 파일을 사용할 수 있으며，에이전트가 내용을 맥락으로 모델에 전달합니다。이 기능은 비용이 많이 발생할 수 있습니다。",
  "仅支持文档类型的附件，如PDF、Word、Excel。如需使用图片，请选择支持图片识别的模型。": "PDF、Word、Excel 등의 문서 첨부 파일만 지원합니다。이미지를 사용하려면 이미지 인식을 지원하는 모델을 선택하세요。",
  "支持的附件格式：PNG、JPG、JPEG、PDF、Word、Excel": "지원되는 첨부 파일 형식：PNG、JPG、JPEG、PDF、Word、Excel",
  "尝试描述：Agent 需要完成什么任务、服务什么用户、需要避免那些行为？": "다음을 설명해 보세요：에이전트가 수행할 작업、서비스 대상 사용자、피해야 할 행동은 무엇인가요？",
