  "反馈成功，平台将尽快解决": "피드백을 보냈습니다，플랫폼에서 최대한 빠르게 해결하겠습니다",
  "向指定手机号发送短信邀请用户注册外部门户，并在外部门户下自动创建一条对应的用户数据（成员状态为“未激活”）。短信费用自动从组织信用点中扣除": "지정한 휴대폰 번호로 외부 포털 가입 초대 문자를 발송하고，외부 포털에 해당 사용자 데이터를 자동 생성합니다（구성원 상태는 “미활성화”）。문자 요금은 조직 크레딧에서 자동 차감됩니다",
