  "Chrome 最近限制了本地脚本的加载，出现这种情况时，请使用 Firefox 开发插件。": "최근 Chrome에서 로컬 스크립트 로드를 제한하고 있습니다。이 문제가 발생하면 Firefox에서 플러그인을 개발하세요。",
