  "导入配置存在错误，匹配字段异常，请联系管理员处理": "가져오기 설정의 일치 필드에 오류가 있습니다，관리자에게 문의하세요",
  "导入配置存在错误，依据字段异常，请联系管理员处理": "가져오기 설정의 기준 필드에 오류가 있습니다，관리자에게 문의하세요",
  "无权限或已删除": "권한이 없거나 삭제되었습니다",
  "添加短信签名": "문자 발신 서명 추가",
  "自定义签名到达率受运营商风控等因素影响，若实际到达率不佳，建议您可以尝试切换到平台默认提供的签名。": "사용자 지정 발신 서명의 전달률은 통신사 보안 정책 등의 영향을 받습니다。실제 전달률이 낮으면 플랫폼에서 제공하는 기본 서명으로 전환해 보세요。",
  "注意：运营商新规，短信内容不能带有链接/域名/联系方式等引流信息，否则极大概率短信被运营商所拦截。": "참고：통신사의 새 규정에 따라 문자 내용에 링크/도메인/연락처 등의 유도 정보를 포함할 수 없습니다，포함하면 통신사에서 차단할 가능성이 매우 높습니다。",
