  "AI 动作用于在记录上下文中解决特定业务场景的问题，例如分析讨论内容、给出行动建议或产出沟通文案；AI 动作将显示在记录页右侧，供用户点击触发": "AI 작업은 레코드 맥락에 따라 토론 분석、실행 제안 또는 메시지 작성 등 특정 업무 문제를 해결합니다；AI 작업은 레코드 페이지 오른쪽에 표시되며，사용자가 클릭하여 실행할 수 있습니다",
