  "附件字段生成预览链接": "첨부 파일 필드 미리보기 링크 생성",
  "导出的Excel中对每个附件字段都会新增一列「预览链接」，点击后可以直接在浏览器中预览附件（按照查看者的账号权限）": "내보낸 Excel에서 각 첨부 파일 필드에 「미리보기 링크」 열이 추가됩니다。클릭하면 브라우저에서 첨부 파일을 바로 미리 볼 수 있습니다（뷰어의 계정 권한에 따름）",
  "导出 Excel 数值格式": "Excel 숫자 형식으로 내보내기",
  "对以下字段类型：数值、金额、等级、公式（数值类型）、汇总（数值类型），在导出时只保留纯数值（不含前后缀），便于在excel中分析或重新导入；取消勾选后，则按包含前后缀的文本导出。": "숫자、금액、등급、수식（숫자 유형）、집계（숫자 유형）필드는 내보낼 때 접두사와 접미사를 제외한 숫자만 유지하여，Excel 분석이나 다시 가져오기에 활용할 수 있습니다；선택을 해제하면 접두사와 접미사가 포함된 텍스트로 내보냅니다。",
  "同时导出数据ID": "데이터 ID 함께 내보내기",
