  "域名不能为空": "도메인을 입력하세요",
  "客户端不能为空": "클라이언트를 입력하세요",
  "编辑应用访问策略": "애플리케이션 접근 정책 편집",
  "新建应用访问策略": "새 애플리케이션 접근 정책",
  "黑名单": "차단 목록",
  "整体禁止访问，允许访问下方添加的应用": "전체 접근을 금지하되，아래에 추가한 애플리케이션 접근은 허용",
  "整体允许访问，禁止访问下方添加的应用": "전체 접근을 허용하되，아래에 추가한 애플리케이션 접근은 금지",
  "黑/白名单": "차단/허용 목록",
  "白名单:%0个应用": "허용 목록:애플리케이션 %0개",
  "黑名单:%0个应用": "차단 목록:애플리케이션 %0개",
  "高级配置": "고급 설정",
  "关闭失败": "끄기 실패",
  "确认删除策略“%0”": "정책 “%0” 삭제 확인",
  "最多创建10个策略": "정책은 최대 10개까지 생성할 수 있습니다",
  "组织默认策略：允许访问应用": "조직 기본 정책：애플리케이션 접근 허용",
  "当成员未命中其他策略时将正常访问其有权限的全部应用。建议创建禁止访问应用的策略，限制特定访问场景": "구성원에게 다른 정책이 적용되지 않으면 권한이 있는 모든 애플리케이션에 정상적으로 접근할 수 있습니다。특정 상황의 접근을 제한하려면 애플리케이션 접근 금지 정책을 생성하는 것이 좋습니다",
  "策略名称": "정책 이름",
  "策略": "정책",
  "连接测试成功才可保存": "연결 테스트에 성공해야 저장할 수 있습니다",
  "加密请求地址不能为空": "암호화 요청 주소를 입력하세요",
  "解密请求地址不能为空": "복호화 요청 주소를 입력하세요",
  "连接测试成功": "연결 테스트 성공",
  "连接测试失败": "연결 테스트 실패",
  "编辑加密规则": "암호화 규칙 편집",
  "连接测试": "연결 테스트",
  "配置加密与解密请求地址。当字段数据需要加密或解密时，将请求这些接口完成转换": "암호화 및 복호화 요청 주소를 설정합니다。필드 데이터를 암호화하거나 복호화할 때，이 API를 호출하여 변환합니다",
