  "显示%0个": "%0개 표시",
  "扫码注册商户号的微信号将做为商户号的超级管理员。": "상점 번호를 스캔하여 등록한 WeChat 계정이 상점 번호의 최고 관리자입니다.",
  "3、支付宝退款退费：退款时服务费不退回，请及时充值保证后续退款成功": "3. Alipay 환불/수수료: 환불 시 서비스 수수료는 반환되지 않습니다. 이후 환불이 원활히 진행되도록 잔액을 충전하세요.",
  "通过手机扫码上传附件": "휴대폰으로 QR 코드를 스캔해 첨부 파일을 업로드하세요.",
  "获取扫码链接失败": "스캔 링크를 가져오지 못했습니다.",
  "扫码完成人脸识别，自动审核，无需等待": "QR 스캔으로 얼굴 인식 완료, 자동 심사로 대기 없음",
  "当前组织内有其他 0 个用户。如果您已不需要使用此组织，可以选择关闭组织": "현재 조직에 다른 사용자 0명이 있습니다. 이 조직이 더 이상 필요 없다면 조직을 종료할 수 있습니다.",
  "按钮样式": "버튼 스타일",
  "2、当排序方式为【按添加顺序】时，支持拖拽排序，且当关联记录数量小于50条时生效。": "2. 정렬 방식이 [추가 순서]일 때 드래그 앤 드롭 정렬을 지원합니다. 연결된 레코드가 50개 미만일 때만 적용됩니다.",
