  "同意按钮": "동의 버튼",
  "取消操作": "작업 취소",
  "无法使用此功能，请先前往Web端完成认证": "이 기능을 사용할 수 없습니다. 먼저 Web에서 인증을 완료하세요.",
  "获取带付款按钮的记录分享链接，得到此链接的所有人都可以查看记录并进行付款。": "결제 버튼이 포함된 레코드 공유 링크를 생성합니다. 이 링크를 받은 모든 사용자는 레코드를 조회하고 결제할 수 있습니다.",
  "组织信用代码不一致": "조직 신용 코드가 일치하지 않습니다.",
  "区分大小写": "대소문자 구분",
  "拒绝按钮": "거부 버튼",
  "单位名称": "단위 이름",
  "证书超过有效期": "인증서가 유효 기간을 초과했습니다.",
  "示例：=DECODEURI('name%3D%E7%B3%BB%E7%BB%9F')，结果：\"name=系统\"": "문구 예시: =DECODEURI('name%3D%E7%B3%BB%E7%BB%9F'), 결과: \"name=시스템\"",
  "签名已经上传成功": "서명이 업로드되었습니다.",
  "选择用户扩展信息作为用户权限标签字段（仅支持关联记录字段），可启用的字段上限为3个，每个标签字段的有限值上限为1000个，超过时默认取前1000个，当其他工作表记录也关联了此标签字段时，可以在角色权限、或筛选器中过滤出当前用户对应的标签记录。": "사용자 확장 정보를 사용자 권한의 태그 필드로 선택합니다(연결된 레코드 필드만 지원). 활성화할 수 있는 필드는 최대 3개이며, 각 태그 필드의 허용 값은 최대 1000개입니다. 초과 시 상위 1000개만 사용됩니다. 다른 워크시트의 레코드에서도 이 태그 필드를 연결했다면, 역할 권한 또는 필터에서 현재 사용자에 해당하는 태그 레코드를 필터링할 수 있습니다.",
