  "8.将以上步骤中获取到的相关信息填写到HAP的支付宝支付配置中": "8. 위 단계에서 받은 정보를 HAP의 알리페이 결제 설정에 입력하세요.",
  "此二维码已失效，请重新点击扫码上传附件": "이 QR 코드는 만료되었습니다. 다시 클릭해 스캔 후 첨부 파일을 업로드하세요.",
  "请选择5MB以内的jpg, jpeg或png图片": "5MB 이하의 jpg, jpeg 또는 png 이미지를 선택하세요.",
