  "始终显示开始和结束时间字段": "시작 시간과 종료 시간 필드를 항상 표시",
  "4、当关联记录显示方式为表格时无以上限制。": "4. 연결된 레코드의 표시 방식이 표 형태일 때는 위 제한이 적용되지 않습니다.",
  "默认方式下，用户可自行切换使用模糊匹配或精确匹配搜索，适合大多数筛选场景": "기본 설정에서 사용자가 모호 일치와 정확 일치 검색을 자유롭게 전환할 수 있습니다. 대부분의 필터링 상황에 적합합니다.",
