  "启用后，成员可在组织专属登录页使用 LDAP 登录。系统将通过邮箱进行身份匹配，请确保成员账号已绑定对应邮箱": "사용 설정 시, 구성원은 조직 전용 로그인 페이지에서 LDAP로 로그인할 수 있습니다. 시스템이 이메일로 신원을 매칭하므로, 구성원 계정에 해당 이메일이 연결되어 있는지 확인하세요.",
