  "例如: 跟进销售线索的客户管理系统": "예: 영업 리드 후속 관리를 위한 고객 관리 시스템",
  "设为只读后，标签页内所有字段均为只读。但仍可在自定义按钮和工作流中编辑": "문안을 읽기 전용으로 설정하면 탭의 모든 필드가 읽기 전용이 됩니다. 하지만 사용자 지정 버튼과 워크플로에서는 여전히 편집할 수 있습니다.",
  "记录已被修改，无法继续编辑。点击获取最新记录": "레코드가 수정되어 더 이상 편집할 수 없습니다. 최신 레코드 가져오기를 클릭하세요.",
