  "可配置应用导航/分组、工作流、工作表、自定义页面、对话机器人、用户角色新增/编辑/删除（包含外部门胡角色）、外部门户设置（ 包含外部门户域名配置）": "구성 가능한 애플리케이션 내비게이션/그룹, 워크플로, 워크시트, 사용자 지정 페이지, 대화형 봇, 사용자 역할 추가/편집/삭제(외부 포털 역할 포함), 외부 포털 설정(외부 포털 도메인 설정 포함)",
