  "添加您的个人状态": "개인 상태 추가",
  "修改成功，无编辑权限或已锁定的%0无法修改": "수정되었습니다. 편집 권한이 없거나 잠금 상태인 %0은 수정할 수 없습니다.",
  "编辑自定义动作": "사용자 지정 동작 편집",
  "添加后，支持设置部门对应的职位信息，设置后在成员的个人资料中展示。原本的“职位”将显示为“全部职位”汇总多任职信息中的职位信息，并在系统中使用。": "문구를 추가하면 부서별 직무 정보를 설정할 수 있으며, 설정한 내용은 구성원 프로필에 표시됩니다. 기존의 ‘직무’는 ‘전체 직무’로 표시되어 다중 재직 정보의 직무를 집계해 보여주며, 시스템에서 해당 값이 사용됩니다.",
  "4. 可获取附件字段中的图片缩略图和文件名。字段代码为：#{附件$[90*auto_L]$_name}。其中：90*auto 表示图片宽/高尺寸（单位mm）；_L表示获取的图片质量；_name表示获取文件名。": "4. 첨부 파일 필드에서 이미지 썸네일과 파일명을 가져올 수 있습니다. 필드 코드: #{첨부 파일$[90*auto_L]$_name}. 여기서 90*auto는 이미지 가로/세로 크기(단위 mm)를 의미하고, _L은 가져올 이미지 품질, _name은 파일명 가져오기를 의미합니다.",
  "收起分组": "그룹 접기",
  "配置流程": "설정 프로세스",
  "群组创建时间": "그룹 생성 시간",
