  "将所选字段的字段值作为分组显示记录。看板添加分组后最多加载1000条记录": "선택한 필드의 값으로 레코드를 그룹화해 표시합니다. 칸반에 그룹을 추가하면 최대 1000개의 레코드만 로드됩니다.",
