  "开启后，应用管理员、运营者可以使用不同的角色身份访问应用。开发者暂不支持使用此功能。": "켜면 애플리케이션 관리자와 운영자는 서로 다른 역할로 앱에 접근할 수 있습니다. 개발자는 아직 이 기능을 지원하지 않습니다.",
