  "我的状态": "내 상태",
  "编辑 Basic Auth 测试数据": "Basic Auth 테스트 데이터 편집",
  "开启后可上传附件。使用该功能可能产生较多费用。为保证体验，请选择上下文长度较大的模型。图片和PDF 由模型解析（需在 AI 智能体节点配置具备图像识别能力的模型）；文档由文档识别服务解析（0.72 信用点/附件）": "켜면 첨부 파일을 업로드할 수 있습니다. 이 기능은 비용이 많이 발생할 수 있습니다. 원활한 사용을 위해 컨텍스트 길이가 큰 모델을 선택하세요. 이미지와 PDF는 모델이 분석합니다(AI 에이전트 노드에서 이미지 인식 기능이 있는 모델을 설정해야 함). 문서는 문서 인식 서비스가 분석합니다(첨부 파일당 0.72 크레딧).",
  "欢迎语": "환영 문구",
