  "公开表单、外部门户及工作流短信通知节点统一改为此签名；": "공개 양식, 외부 포털 및 워크플로 문자 알림 노드의 문구를 모두 이 서명으로 통일했습니다.",
  "手机号/邮箱:": "휴대폰 번호/이메일:\"",
  "开启此功能需满足的条件为：支付开启公开表单、支付金额字段选择金额/数值、设置交易有效期": "이 기능을 사용하려면 다음 조건을 충족해야 합니다: 결제 공개 양식 활성화, 결제 금액 필드에서 금액/숫자 선택, 거래 유효 기간 설정.",
