  "您好，HAP中有任何使用问题，都可以向我提问": "안녕하세요. HAP 사용 중 궁금한 점이 있으면 질문하세요.",
  "用于工作流短信节点或外部门户发送邮件，费用0.03信用点/封": "워크플로 문자 노드 또는 외부 포털에서 이메일 발송 시 사용됩니다. 비용: 0.03 크레딧/건.",
  "数电专票": "전자 전용 세금계산서",
