  "勾选后，当编号规则含时间相关字段时，对应的时间将按照应用时区显示。": "선택하면, 번호 규칙에 시간 관련 필드가 포함된 경우 해당 시간이 애플리케이션 시간대에 따라 표시됩니다.",
