  "1.支付功能服务费：按商户号收取，年费999元/商户，月费199元/商户；新商户可申请一周免费试用，试用期间单笔订单限额1元。": "1. 결제 기능 서비스 요금: 가맹점 번호 기준 부과, 연 999위안/가맹점, 월 199위안/가맹점. 신규 가맹점은 1주 무료 체험 신청 가능하며, 체험 기간 단일 주문 한도는 1위안입니다.",
  "只有能访问该视图的用户，才能看到并使用配置的快速筛选": "해당 보기에 접근 가능한 사용자만 설정된 빠른 필터를 보고 사용할 수 있습니다.",
  "是否物理删除(true：物理删除，false：逻辑删除，默认为false)，物理删除后数据不进入回收站，且不可恢复，请谨慎操作！": "물리 삭제 여부(true: 물리 삭제, false: 논리 삭제, 기본값은 false). 물리 삭제 시 데이터는 휴지통으로 이동하지 않으며 복구할 수 없습니다. 신중하게 진행하세요.",
  "设置应用、工作表消耗的服务资源额度上限。可全局配置额度，也可以单独设置": "애플리케이션과 워크시트가 사용하는 서비스 리소스 한도를 설정합니다. 전역 한도를 설정하거나 항목별로 개별 설정할 수 있습니다.",
  "目前仅支持按类目汇总开具发票，税率与编码随类目自动匹配。": "현재는 카테고리별 합산 발행만 지원합니다. 세율과 코드가 카테고리에 따라 자동 매칭됩니다.",
