  "卡片样式": "카드 스타일",
  "开票单号异常不支持开票": "청구서 번호 이상으로 청구서 발행을 지원하지 않습니다.",
  "关注后接收全部提醒，未关注仅@你或回复时通知": "팔로우하면 모든 알림을 받습니다. 팔로우하지 않으면 @멘션되거나 답글이 있을 때만 알림이 옵니다.",
  "成员已存在，不能重复邀请": "이미 구성원이 존재합니다. 중복 초대할 수 없습니다.",
