  "每周二": "매주 화요일",
  "controlName：控件名称，必填": "controlName: 컨트롤 이름, 필수 입력",
  "当前视图使用的\"%0\"和\"%1\"的字段类型不同，视图将使用日期时间的字段类型绘制。建议使用两个同为日期类型或同为日期时间类型的字段。": "현재 보기에서 \"%0\"와 \"%1\"의 필드 유형이 다릅니다. 보기는 날짜-시간 필드 유형으로 표시됩니다. 두 필드 모두 날짜 유형이거나 날짜-시간 유형인 필드를 사용하는 것을 권장합니다.",
