  "此签名适用的短信场景:外部门户用户注册登录、邀请外部用户注册、外部用户审核(通过/拒绝)": "이 서명은 다음 문자 메시지 시나리오에 적용됩니다: 외부 포털 사용자 가입·로그인, 외부 사용자 가입 초대, 외부 사용자 심사(승인/거부)",
