  "设置一天内每个应用的工作流执行次数上限。可为所有应用全局配置，也可以为特殊的应用单独设置。": "하루 동안 각 애플리케이션의 워크플로 실행 횟수 상한을 설정합니다. 모든 애플리케이션에 전역으로 적용하거나 특정 애플리케이션에 개별 설정할 수 있습니다.",
  "解锁成功": "잠금 해제됨",
  "添加到工作表": "워크시트에 추가",
  "（3）默认代码中不包含文件名，需要时可自行拼接_name。例如：#{附件$[90*auto_L]$_name}表示同时获取图片缩略图和文件名；#{附件_name}表示只获取文件名。备注：Excel模版不支持图片与文件名同步显示。": "(3) 기본 코드에는 파일명이 포함되지 않습니다. 필요 시 _name을 직접 이어 붙여 사용하세요. 예: #{附件$[90*auto_L]$_name}은 이미지 썸네일과 파일명을 함께 가져오고, #{附件_name}은 파일명만 가져옵니다. 참고: Excel 템플릿은 이미지와 파일명의 동시 표시를 지원하지 않습니다.",
  "我可以为您解析文字或图片内容，智能填写到表单字段": "텍스트와 이미지를 분석해 양식 필드를 자동으로 채웁니다.",
  "在视图上呈现流程名称、状态、审批完成时间、节点负责人、节点开始、剩余时间、发起人、发起时间": "보기에서 프로세스 이름, 상태, 결재 완료 시간, 노드 책임자, 노드 시작, 남은 시간, 프로세스 시작자, 시작 시간을 표시합니다.",
  "保存记录": "레코드 저장",
  "取消区分大小写": "대소문자 구분 해제",
  "必须修改后才能继续保存": "수정해야 계속 저장할 수 있습니다.",
  "二维码已失效，请刷新后重新扫码": "QR 코드가 만료되었습니다. 새로고침 후 다시 스캔하세요.",
