  "提示错误后": "오류 알림 후",
  "如何根据条件控制字段显隐": "조건에 따라 필드 표시/숨김 제어 방법",
  "晚上好🌛": "좋은 저녁이에요🌛",
  "支付与开票": "결제 및 청구서 발행",
  "认证组织+10信用点": "인증 조직 +10 크레딧",
  "添加多任职信息": "복수 직무 정보 추가",
  "满足条件时，将在记录保存后生效锁定。锁定记录无法被编辑或删除，仅应用管理员可解锁记录。只能添加一条锁定规则。": "조건을 만족하면 레코드 저장 후 잠금이 적용됩니다. 잠긴 레코드는 편집하거나 삭제할 수 없으며, 애플리케이션 관리자만 잠금 해제할 수 있습니다. 잠금 규칙은 한 개만 추가할 수 있습니다.",
  "开启后，Web 端可使用SSO登录。当用户通过SSO完成登录后，在退出登录时将会被重定向回SSO登录页": "활성화하면 Web에서 SSO 로그인을 사용할 수 있습니다. 사용자가 SSO로 로그인한 뒤 로그아웃하면 SSO 로그인 페이지로 리디렉션됩니다.",
  "请输入正确的 url 格式": "올바른 URL 형식을 입력하세요.",
  "使用 SSL 连接": "SSL로 연결",
  "操作失败，已启用“Lark”集成": "작업에 실패했습니다. 이미 Lark 연동이 활성화되어 있습니다.",
  "开始生成": "생성 시작",
  "备份将于下个周期凌晨时段开始自动执行": "백업은 다음 주기 새벽 시간대에 자동으로 실행됩니다.",
  "签名设置完成后，": "서명 설정을 완료한 후,",
  "关闭群组后，群组将不能被访问。您可以在 组织管理-群组 中找到并重新开启这个群组": "그룹을 비활성화하면 접근할 수 없습니다. 조직 관리 > 그룹에서 이 그룹을 찾아 다시 활성화할 수 있습니다.",
  "视图别名": "보기 별칭",
  "确保连接数据库时的账号具有当前数据库的 db_owner 或以上权限": "데이터베이스에 연결하는 계정이 현재 데이터베이스의 db_owner 이상 권한을 가지고 있는지 확인하세요.",
  "名称和说明": "이름 및 설명",
  "新版对记录详情界面进行了重构，如遇问题，可点击按钮返回旧版本。": "신규 버전에서 레코드 상세 화면을 재구성했습니다. 문제가 있으면 버튼을 눌러 구버전으로 돌아가세요.",
  "基于指令理解，自动调用工具完成任务": "지시에 따라 이해하고 자동으로 도구를 호출해 작업을 완료합니다.",
  "触发编辑以记录上方出现“正在修改表单数据…”的蓝色提示为准；": "상단에 ‘양식 데이터를 수정하는 중…’이라는 파란 안내가 표시될 때를 기준으로 편집 트리거를 기록하세요.\"",
  "工具是智能体在流程中可被动态调用的功能模块。智能体会根据上下文自动选择合适的工具，在流程中完成记录查询、新增、更新、汇总及外部接口调用等操作": "도구는 프로세스에서 AI 에이전트가 동적으로 호출할 수 있는 기능 모듈입니다. 에이전트는 문맥에 따라 적절한 도구를 자동으로 선택해 레코드 조회, 추가, 업데이트, 집계 및 외부 API 호출 등의 작업을 수행합니다.",
  "额度管理": "한도 관리",
  "将记录移动到...": "레코드를 이동합니다…",
  "手机扫描邀请成员加入": "휴대폰으로 스캔해 구성원 초대하기",
