  "弹窗选择方式": "팝업 선택 방식",
  "dot：保留小数位（0-14），控件类型为6:数值,8:金额时填入": "dot: 소수 자릿수(0-14). 컨트롤 유형이 6: 수치, 8: 금액일 때 입력하세요.",
  "设置每个工作表行记录数量上限。可为所有工作表全局配置，也可以为特殊的工作表单独设置。组织可设置最大上限为 100万行 / 每个表": "워크시트당 행 레코드 수 상한을 설정합니다. 모든 워크시트에 전역으로 적용하거나 특정 워크시트에 개별 설정할 수 있습니다. 조직별 최대 상한은 워크시트당 100만 행입니다.",
