  "名称不能包含以下字符:": "이름에는 다음 문자를 포함할 수 없습니다:\"",
  "单选选择方式时，使用成员字段设置默认值，将取成员所在主部门": "단일 선택 방식에서 멤버 필드로 기본값을 설정하면, 해당 멤버의 소속 주요 부서를 가져옵니다.",
  "批量编辑可以统一将字段值改为相同内容。一次最多修改前1000条未锁定且有编辑权限的记录。": "일괄 편집으로 필드 값을 동일한 내용으로 변경할 수 있습니다. 한 번에 잠금 해제되어 있고 편집 권한이 있는 레코드 최대 1000개까지 수정할 수 있습니다.",
  "支持格式：PNG、JPG、JPEG、PDF、Word、Excel。一次消息最多上传 %0 个附件": "지원 형식: PNG, JPG, JPEG, PDF, Word, Excel. 한 메시지당 최대 %0개의 첨부 파일을 업로드할 수 있습니다.",
  "GB / 每个应用": "GB/애플리케이션당",
