  "true：返回批量增加的rowIds，false返回时成功的条数": "true: 배치 추가된 rowIds를 반환합니다. false: 성공한 개수만 반환합니다.",
  "工作流直接生成支付订单，获得链接的人可以直接付款": "워크플로에서 바로 결제 주문을 생성하고, 링크를 받은 사용자는 즉시 결제할 수 있습니다.",
  "每周六": "매주 토요일",
  "当满足条件时,可对指定字段进行提示。": "조건을 만족하면 지정된 필드에 안내를 표시할 수 있습니다.",
  "修改完成": "수정 완료",
