  "数电普票": "전자 일반 발행서",
  "正在开票中...": "청구서 발행 중...",
  "添加到": "추가 대상",
  "在表单中显示“AI填写”按钮。支持上传文字、图片或文档，AI 将自动解析并填写字段": "양식에 ‘AI 작성’ 버튼을 표시합니다. 텍스트, 이미지 또는 문서를 업로드하면 AI가 자동으로 분석하여 필드를 채웁니다.",
  "设置在浏览器中，当有新消息时以何种方式提示": "브라우저에서 새 메시지 알림 방식 설정",
