  "名称(源)": "이름(원본)",
  "联系人手机号码与姓名和身份证不一致": "연락처 휴대폰 번호가 이름 및 주민등록번호와 일치하지 않습니다.",
  "如果您需要长期使用请及时转为群组，可以管理群成员、聊天内容和文件，信息沟通更安全": "장기간 사용하려면 그룹으로 전환하세요. 구성원, 채팅, 파일을 관리할 수 있어 커뮤니케이션이 더 안전합니다.",
  "设置每个工作表行记录数量上限。可为所有工作表全局配置，也可以为特殊的工作表单独设置。组织可设置最大上限为 %0万行 / 每个表": "워크시트마다 행 레코드 수 상한을 설정하세요. 모든 워크시트에 대한 전역 설정이거나 특정 워크시트에 개별 설정으로 지정할 수 있습니다. 조직은 워크시트당 최대 %0만 행까지 설정할 수 있습니다.",
  "描述使用过程中遇到的问题，提交反馈至 HAP，会自动收集提问、AI 回答、工具请求参数，不会收集具体业务数据。": "사용 중 발생한 문제를 설명하고 HAP에 피드백을 제출하세요. 질문, AI 응답, 도구 요청 파라미터는 자동으로 수집되며, 구체적인 업무 데이터는 수집하지 않습니다.",
  "选择已有动作": "기존 동작 선택",
  "定期备份已关闭": "정기 백업이 꺼져 있습니다.",
  "勾选时覆盖应用、应用项、视图、工作流、角色的名称和说明": "체크 시 애플리케이션, 애플리케이션 항목, 보기, 워크플로, 역할의 이름과 설명을 덮어씁니다.",
  "转化率": "전환율",
  "编辑中···": "편집 중···",
  "编辑保护不会拦截行式编辑、公开表单、工作流或通过API修改记录等操作。": "편집 보호는 행 단위 편집, 공개 양식, 워크플로, 또는 API를 통한 레코드 수정 같은 작업을 차단하지 않습니다.",
