  "取消关注": "팔로우 취소",
  "名称不符合规范": "이름이 규정에 맞지 않습니다.",
  "如何为应用添加外部链接": "애플리케이션에 외부 링크 추가하기 방법",
  "微软": "Microsoft",
  "已存在一条关联记录，修改失败！": "이미 연결된 레코드가 있어 수정에 실패했습니다!",
  "管理员审核确认之后，发票将由合作服务商百望发送至您的邮箱": "관리자 검토가 완료되면, 협력 서비스사 Baiwang에서 고객님의 이메일로 세금계산서를 발송합니다.",
  "发票已取消申请": "세금계산서 신청이 취소되었습니다.",
  "根据当前流程节点中的记录对象，生成特定的对外支付链接，可以通过邮件、短信的正文里引用此节点，邀请用户下单或者付款": "현재 워크플로 노드의 레코드 객체를 기준으로 외부 결제 전용 링크를 생성합니다. 이메일이나 문자 메시지 본문에서 이 노드를 참조해 주문 또는 결제를 요청할 수 있습니다.",
  "在组织专属登录页，当开启了SSO、LDAP或第三方平台账号登录时，可关闭平台账号登录入口": "조직 전용 로그인 페이지에서 SSO, LDAP 또는 서드파티 계정 로그인을 활성화하면 플랫폼 계정 로그인 항목을 비활성화할 수 있습니다.",
  "当变更为以下条件时，锁定": "다음 조건으로 변경되면 잠금",
  "附件上传总量": "첨부 파일 업로드 총량",
  "%0已锁定，修改失败": "%0이(가) 잠겨 있어 수정에 실패했습니다.",
  "开启后，登录后需用户再额外绑定邮箱或者手机号，绑定后方可使用应用": "이 옵션을 켜면 로그인 후 추가로 이메일 또는 휴대폰 번호를 연결해야 하며, 연결 완료 후에만 애플리케이션을 사용할 수 있습니다.",
  "超级搜索 - 搜索记录": "슈퍼 검색 - 검색 기록",
  "联系人、群组": "연락처, 그룹",
  "模型参数": "모델 매개변수",
