  "查询账户": "계정 조회",
  "工作表行记录数量上限": "워크시트 행 레코드 수 최대값",
  "勾选后，选择“其他”时清空常规选项，选择常规选项时清空“其他”。": "선택 후 ‘기타’를 선택하면 기본 옵션을 초기화하고, 기본 옵션을 선택하면 ‘기타’를 초기화합니다.",
  "0.15信用点": "0.15 크레딧",
  "60天内可在 回收站 找回已删除%0。未锁定且有删除权限的%1才可被删除。": "삭제한 %0는 60일 이내에 휴지통에서 복구할 수 있습니다. 잠금 해제 상태이며 삭제 권한이 있는 %1만 삭제할 수 있습니다.",
  "由 HAP 向指定邮箱代发自定义内容的邮件": "HAP이 지정한 이메일로 사용자 지정 내용의 메일을 대리 발송합니다.",
  "分享卡片设置": "공유 카드 설정",
  "使用短信自定义签名功能需要完成组织认证": "SMS 사용자 지정 서명 기능을 사용하려면 조직 인증을 완료하세요.",
  "2、平台支持多渠道对接支付收款，微信支付/支付宝支付由签约渠道制定费率": "2. 플랫폼은 다채널 결제 수납 연동을 지원합니다. WeChat Pay/Alipay의 수수료율은 계약된 채널에서 결정됩니다.",
  "设置应用中工作表附件字段、讨论附件，上传量的上限。可为所有应用全局配置，也可以为特殊的应用单独设置。": "애플리케이션의 워크시트 첨부 파일 필드와 토론 첨부 파일에 대한 업로드 용량 상한을 설정합니다. 모든 애플리케이션에 공통으로 적용하거나 특정 애플리케이션에 개별 설정할 수 있습니다.",
  "上传时请勿关闭此浮层": "업로드 중에는 이 떠 있는 창을 닫지 마세요.",
  "修改联系人信息": "연락처 정보 수정",
  "type：控件类型，目前支持控件类型有 2:文本、6:数值、9:单选、10:多选、46:时间、15:日期（年-月-日）、16:日期 （年-月-日 时:分）、26:成员、14:附件、29:关联记录": "type: 컨트롤 유형. 현재 지원되는 컨트롤 유형은 다음과 같습니다: 2: 텍스트, 6: 숫자, 9: 단일 선택, 10: 다중 선택, 46: 시간, 15: 날짜(연-월-일), 16: 날짜(연-월-일 시:분), 26: 구성원, 14: 첨부 파일, 29: 연관 레코드.",
  "账号密码（SASL）": "계정 비밀번호(SASL)",
  "AI生成": "AI 생성",
  "与关联记录的排序保持一致": "연관 레코드의 정렬과 일치시키기",
  "已选中%0条记录。一次最多处理1000条记录。": "%0개 레코드를 선택했습니다. 한 번에 최대 1000개 레코드까지 처리할 수 있습니다.",
  "当前为个人创建的临时聊天。如果您需要长期使用请及时转为群组，可以管理群成员、聊天内容和文件，信息沟通更安全": "현재 개인이 만든 임시 채팅입니다. 장기간 사용하려면 그룹으로 전환하세요. 그룹원, 대화 내용과 파일을 관리할 수 있어 정보 소통이 더 안전합니다.",
  "请告诉我您想创建的工作表，或上传参考图片 😉": "만들고 싶은 워크시트를 알려주시거나 참고 이미지를 업로드하세요 😉",
  "编辑已超时，无法继续编辑。点击获取最新记录": "편집 시간이 초과되어 더 이상 편집할 수 없습니다. 최신 레코드를 가져오려면 클릭하세요.",
  "请务必确认所有应用成员都不再需要此对话机器人后，再执行此操作。": "이 작업을 실행하기 전에 애플리케이션의 모든 구성원이 더 이상 이 대화형 봇이 필요하지 않은지 반드시 확인하세요.",
  "一": "일",
  "导入商品管理表": "상품 관리 워크시트로 가져오기",
  "解锁": "잠금 해제",
  "被退回的节点重新提交时": "반려된 노드를 재제출할 때",
  "确定取消申请该发票吗？": "정말 이 청구서 신청을 취소할까요?",
  "法人手机号码有误": "법인 휴대폰 번호가 올바르지 않습니다.",
  "所有值计数": "모든 값 개수",
  "开启后，不能多人同时编辑同一条记录。当有用户在详情页触发编辑时，该记录即进入保护状态，仅当前用户可编辑记录，其他用户仅能查看。当该用户提交记录或超过保护时长，其他用户方可编辑。": "사용 설정 시, 여러 사용자가 동시에 동일한 레코드를 편집할 수 없습니다. 어떤 사용자가 상세 페이지에서 편집을 시작하면 해당 레코드는 보호 상태가 되며, 현재 사용자만 편집할 수 있고 다른 사용자는 조회만 가능합니다. 해당 사용자가 레코드를 제출하거나 보호 시간이 초과되면 다른 사용자도 편집할 수 있습니다.",
  "格式:YYYY-MM-DD HH:mm:ss,为空表示永久有效": "형식: YYYY-MM-DD HH:mm:ss, 비어 있으면 영구 유효",
  "（5）序号打印：如果需要在子表、关联记录、查询记录（列表）中打印系统自动生成的序号字段，可在代码中调用 sequencenumber 字段代码，例如 #{关联表字段代码.sequencenumber}。其中“关联表字段代码”为当前表中关联字段的字段代码，sequencenumber 为系统自动编号字段的固定代码": "(5) 일련번호 출력: 하위 테이블, 연관 레코드, 조회 레코드(목록)에서 시스템이 자동 생성한 일련번호 필드를 출력하려면 코드에서 sequencenumber 필드 코드를 호출하세요. 예: #{연관 테이블 필드 코드.sequencenumber}. 여기서 ‘연관 테이블 필드 코드’는 현재 테이블의 연관 필드의 필드 코드이며, sequencenumber는 시스템 자동 번호 필드의 고정 코드입니다.",
  "按应用时区拼接": "애플리케이션 시간대 기준으로 병합",
  "创建用户": "사용자 생성",
  "每周三": "매주 수요일",
  "记录移动成功": "레코드가 이동되었습니다.",
  "每周一": "매주 월요일",
  "确定批量生成别名？": "대량으로 별칭을 생성할까요?",
  "使用弹窗关联记录，可以配置的筛选器过滤记录并设置弹窗中的显示字段": "팝업으로 레코드를 연결하고, 구성 가능한 필터로 레코드를 걸러 팝업에 표시할 필드를 설정할 수 있습니다.",
  "默认规则：": "기본 규칙:",
  "unit：类型为46时间时传入，1：时分，6：时分秒": "unit: 타입이 46(시간)일 때 전달. 1: 시/분, 6: 시/분/초",
  "设置签名": "서명 설정",
  "列编辑权限": "열 편집 권한",
  "登录后需绑定手机号或者邮箱": "로그인 후 휴대폰 번호 또는 이메일을 연동해야 합니다.",
  "当前记录已锁定，不允许编辑和删除。管理员可在应用内解锁记录。": "현재 레코드가 잠겨 있어 편집 및 삭제할 수 없습니다. 관리자는 애플리케이션에서 레코드 잠금을 해제할 수 있습니다.",
  "千次 / 每日": "천 회/일",
