  "不支持跨页批量修改附件": "페이지를 넘겨 첨부 파일을 일괄 수정할 수 없습니다.",
  "用户权限标签可以用来做什么": "사용자 권한 태그로 무엇을 할 수 있나요?",
  "账号来源类型受限，无法邀请": "계정 소스 유형이 제한되어 초대할 수 없습니다.",
  "设置您的个人状态，让所有协作的同事及时知晓": "개인 상태를 설정해 협업 중인 동료가 즉시 확인할 수 있게 하세요.",
  "发票税号": "세금계산서 번호",
  "锁定%0不允许编辑和删除。管理员可在应用内解锁。": "%0을(를) 잠금하면 편집 및 삭제할 수 없습니다. 관리자가 애플리케이션에서 잠금을 해제할 수 있습니다.",
