  "深夜了，注意休息🌙": "밤이 늦었어요. 쉬면서 하세요 🌙",
  "主属部门": "주관 부서",
  "本文档提供了一个简单的方法来实现实现应用数据和任何外部数据的集成。API严格遵循REST语义，使用JSON编码对象，并依赖标准HTTP代码来指示操作结果。": "이 문서는 애플리케이션 데이터와 외부 데이터의 연동을 간단하게 구현하는 방법을 제공합니다. API는 REST 의미를 엄격히 따르며, JSON 인코딩 객체를 사용하고 표준 HTTP 코드로 작업 결과를 표시합니다.",
  "上午好🌞": "좋은 아침🌞",
  "您是组织：Mingdao App Room  中唯一一个管理员": "조직 Mingdao App Room의 유일한 관리자입니다.",
  "生成 API 可以直接用的筛选条件，可直接传入 filters 字段中": "API에서 바로 사용할 수 있는 필터 조건을 생성하며, filters 필드에 그대로 전달할 수 있습니다.",
