  "当月工作流执行数剩余2%时自动购买当月额度包，费用10信用点/1,000次": "당월 워크플로 실행 수가 2% 남으면 당월 한도 패키지를 자동 구매합니다. 비용: 1,000회당 10 크레딧.",
  "%0：%1": "%0: %1",
  "短信信用点不足，请联系表单发布者": "문자 크레딧이 부족합니다. 양식 게시자에게 문의하세요.",
