  "职位：": "직책:",
  "请选择开票主体": "청구서 발행 주체를 선택하세요.",
  "请在下方输入 / 粘贴内容开始创建 👇": "아래에 입력하거나 붙여넣어 작성을 시작하세요 👇",
  "移动端支持扫码查询": "모바일에서 QR 코드 스캔 조회 지원",
  "1.函数返回值需要保证和当前子表的数据结构完全一致，从而对子表数据进行全量替换更新。否则将会导致未知异常问题。\\n\\n2.此功能仅提供给熟悉代码的用户使用，可以自由处理子表数据实现复杂业务逻辑。普通用户请谨慎使用！\\n\\n%0": "1. 함수 반환값은 현재 하위 테이블의 데이터 구조와 완전히 동일해야 하며, 이를 통해 하위 테이블 데이터를 전면 교체 업데이트합니다. 그렇지 않으면 알 수 없는 예외가 발생할 수 있습니다.\n\n2. 이 기능은 코드에 익숙한 사용자에게만 제공되며, 하위 테이블 데이터를 자유롭게 처리해 복잡한 비즈니스 로직을 구현할 수 있습니다. 일반 사용자는 신중히 사용하세요!\n\n%0",
