  "当前记录不允许多人同时编辑。请稍后重试": "현재 레코드는 동시 편집을 지원하지 않습니다. 잠시 후 다시 시도하세요.",
  "成员信息显示": "구성원 정보 표시",
  "智能体每次执行时接收的原始内容，通常来自用户消息或流程变量，作为模型生成回复的基础内容": "AI 에이전트가 실행될 때마다 수신하는 원본 콘텐츠로, 보통 사용자 메시지나 프로세스 변수에서 오며 모델이 답변을 생성하는 기본 자료로 사용됩니다.",
  "（4）在打印 Excel 模板时，多张图片排列可能导致撑高合并单元格引起错位，此时可以加 F 启用图片填充模式，此模式下图片不会撑高单元格，例如：#{附件$[auto*20_F]$} 或 #{附件$[auto*90_HF]$}": "(4) Excel 템플릿을 인쇄할 때 여러 이미지를 배치하면 병합된 셀이 높게 늘어나며 위치가 어긋날 수 있습니다. 이때 F를 추가해 이미지 채우기 모드를 활성화하면 이미지가 셀 높이를 늘리지 않습니다. 예: #{첨부 파일$[auto*20_F]$} 또는 #{첨부 파일$[auto*90_HF]$}",
