  "附件默认旧文件在前，可拖拽调整顺序，但新上传文件仍会按默认规则排序": "첨부 파일은 기본적으로 오래된 파일이 먼저 표시됩니다. 드래그해 순서를 변경할 수 있지만, 새로 업로드한 파일은 기본 규칙에 따라 다시 정렬됩니다.",
