  "3、微信支付/支付宝支付直连的商户号提现只能在微信支付商户后台、支付宝商户平台操作": "3. WeChat Pay/Alipay 직연동 가맹점 번호의 출금은 WeChat Pay 가맹점 백오피스와 Alipay 가맹점 플랫폼에서만 처리할 수 있습니다.",
