  "%0已锁定，无法保存%1": "%0이(가) 잠금 상태여서 %1을(를) 저장할 수 없습니다.",
  "基于应用成员协作便利考量，若在讨论中 @用户，则表示期望被 @者知晓当前数据。此时即便被 @人无当前视图或记录权限，只要拥有工作表权限，就能通过消息链接以只读形式查看记录。": "애플리케이션 구성원의 협업 편의를 위해, 토론에서 @사용자를 멘션하면 해당 사용자가 현재 데이터를 확인하길 바란다는 의미입니다. 이때 멘션된 사용자에게 현재 보기나 레코드에 대한 권한이 없어도 워크시트 권한이 있으면 메시지 링크를 통해 레코드를 읽기 전용으로 볼 수 있습니다.",
  "显示收藏的应用": "즐겨찾는 애플리케이션 표시",
  "系统将不再定期备份您的应用数据": "시스템에서 애플리케이션 데이터를 더 이상 정기적으로 백업하지 않습니다.",
  "开票测试说明：本操作将生成个人抬头的正式发票（非演示票），发票会入账并发送至你指定的邮箱。如不需要，请及时在电子税务局/百望进行红冲或作废": "개인 명의의 정식 세금계산서(데모용 아님)가 발급됩니다. 발급된 세금계산서는 회계에 반영되며 지정한 이메일로 전송됩니다. 불필요한 경우 전자세무국/百望에서 즉시 붉은 반환 처리 또는 무효 처리하세요.",
  "获得链接的人可以查看记录详情，需点击支付按钮生成支付订单后进行付款": "링크를 가진 사람은 레코드 상세를 볼 수 있습니다. 결제 버튼을 눌러 결제 주문을 생성한 뒤 결제하세요.",
  "1.函数返回值需要保证和当前子表的数据结构完全一致，从而对子表数据进行全量替换更新。否则将会导致未知异常问题。%02.此功能仅提供给熟悉代码的用户使用，可以自由处理子表数据实现复杂业务逻辑。普通用户请谨慎使用！%1": "1. 함수의 반환값은 현재 하위 테이블의 데이터 구조와 완전히 일치해야 하며, 이를 통해 하위 테이블 데이터를 전량 대체 업데이트합니다. 그렇지 않으면 알 수 없는 예외가 발생할 수 있습니다.%02. 이 기능은 코드에 익숙한 사용자에게만 제공되며, 하위 테이블 데이터를 자유롭게 처리하여 복잡한 비즈니스 로직을 구현할 수 있습니다. 일반 사용자는 신중히 사용하세요!%1",
