  "删除成功，锁定或无删除权限的记录已被忽略": "삭제 완료. 잠금 상태이거나 삭제 권한이 없는 레코드는 건너뛰었습니다.",
  "仅详情页内编辑才能生效编辑保护；": "편집 보호는 상세 페이지에서만 편집할 때 적용됩니다.",
