  "%0 条": "%0개",
  "开票类目": "청구서 카테고리",
  "通过在登录地址后增加组织编号参数（?projectId=组织编号），可进入组织专属登录页，展示对应的 logo 和配置的背景图，若配置了LDAP、企业微信、钉钉或飞书集成，也会展示在登录页可快捷登录": "로그인 주소 뒤에 조직 번호 파라미터(?projectId=조직 번호)를 추가하면 조직 전용 로그인 페이지로 이동합니다. 해당 페이지에 조직의 로고와 설정된 배경 이미지를 표시합니다. LDAP, WeCom, DingTalk, Feishu 연동이 설정된 경우 로그인 페이지에서 간편 로그인 옵션으로 표시됩니다.",
