  "%0/%1页": "%0/%1페이지",
  "，请严格按照要求设置签名，否则无法发送短信；短信签名审核需要3-5 个工作日，审核期间签名统一为：明道云。": "요구사항에 맞게 서명을 설정하세요. 그렇지 않으면 문자 메시지를 보낼 수 없습니다. 서명 심사에는 3~5영업일이 소요되며, 심사 기간에는 서명이 ‘明道云’으로 통일됩니다.",
