  "去除重复值后计数（不包括空值）。对于可以选择多个值的字段（如多选、成员/组织角色/部门多选、子表、关联记录多选），会将所有值去重后计数。": "중복 값을 제거한 후 개수를 계산합니다(빈 값 제외). 여러 값을 선택할 수 있는 필드(예: 다중 선택, 구성원/조직 역할/부서 다중 선택, 하위 테이블, 연관 레코드 다중 선택)의 경우 모든 값을 중복 제거한 뒤 개수를 계산합니다.",
