  "当前用户数已超出人数限制": "현재 사용자 수가 인원 제한을 초과했습니다.",
  "当输出参数是“对象数组”时，可以在流程中使用“获取数组对象”节点将发送 API 请求、JSON 解析或代码块节点中返回的数组参数转为多条数据对象，之后可以在对象数组输出参数的子元素中设置值为数组中的对象元素字段。当输出参数是“普通数组”时，可以使用“JSON 解析”节点中输出的“普通数组”作为参数值。": "출력 파라미터가 “객체 배열”일 때는 플로우에서 “배열 객체 가져오기” 노드를 사용해 API 요청, JSON 파싱 또는 코드 블록 노드에서 반환된 배열 파라미터를 여러 데이터 객체로 변환할 수 있습니다. 이후 객체 배열 출력 파라미터의 하위 요소에서 값으로 배열의 객체 요소 필드를 설정할 수 있습니다. 출력 파라미터가 “일반 배열”일 때는 “JSON 파싱” 노드에서 출력된 “일반 배열”을 파라미터 값으로 사용할 수 있습니다.",
