  "仅支持2位小数，超过则四舍五入": "소수점 둘째 자리까지만 지원하며, 초과분은 반올림됩니다.",
  "`currentControl`: 当前字段": "현재 필드",
  "编辑列样式": "열 스타일 편집",
  "1.根据平台部署情况选择": "1. 플랫폼 배포 상황에 따라 선택",
  "委托范围": "위임 범위",
  "请选择对应视图": "해당 보기를 선택하세요.",
  "组件支持 Tailwind CSS 你可以直接使用，组件内已经预置了 lucide icons，用法与官方稍微有些不同，需要使用 `LucideIcon` 组件，name 是具体的图标名称。名称是大驼峰写法，你可以在 [这里][1] 找到，其他属性和 `lucide-react` 一致。": "컴포넌트는 Tailwind CSS를 지원하므로 바로 사용할 수 있습니다. 컴포넌트에는 lucide icons가 미리 포함되어 있으며, 사용 방식이 공식 문서와 조금 다릅니다. LucideIcon 컴포넌트를 사용해야 하며, name에는 아이콘 이름을 지정합니다. 이름은 파스칼 케이스로 작성하며, [여기][1]에서 확인할 수 있습니다. 그 밖의 속성은 lucide-react와 동일합니다.",
  "选择要复制的配置项": "복사할 설정 항목 선택",
  "替换已有明细": "기존 내역 교체",
  "他人代付": "대리 결제",
  "示例：=IFS(A1 > 10, \"大于10\", A1 < 5, \"小于5\", TRUE, \"介于5和10之间\")": "예시: =IFS(A1 > 10, \"10보다 큼\", A1 < 5, \"5보다 작음\", TRUE, \"5와 10 사이\")",
  "组织 ID：%0": "조직 ID: %0",
  " 支付宝 支付以及提现费率 由支付宝制定，具体可在您的": "Alipay 결제 및 출금 수수료는 Alipay에서 책정합니다. 자세한 내용은 내에서 확인하세요.",
  "支付宝支付；费率参考支付宝支付官方规则": "알리페이 결제; 수수료는 알리페이 공식 규정을 따릅니다.",
  "存储类型接收 `value` 和 `onChange`，`value`是当前字段的值，处理好值后可以调用`onChange`来更新值。": "스토리지 타입은 `value`와 `onChange`를 받습니다. `value`는 현재 필드 값이며, 값을 처리한 후 `onChange`를 호출해 값을 업데이트하세요.",
  "输入支付宝应用私钥": "알리페이 애플리케이션 개인 키 입력",
