  "示例：=ACOS(0.54030230586814) 将返回 1。": "예시: =ACOS(0.54030230586814)은 1을 반환합니다.",
  "微信公众号支付；费率参考微信支付官方规则": "WeChat 공식 계정 결제; 수수료는 WeChat Pay 공식 규정을 따릅니다.",
  "反余切函数": "아크코탄젠트 함수",
  "节省 18%": "18% 절약",
  "提交失败！": "제출에 실패했습니다!",
  "重新扫描全组织引用关系？": "조직 전체의 참조 관계를 다시 스캔할까요?",
  "示例：=SUBSTITUTE(\"a a b b b c\", \"b\", \"B\") 返回\"a a B B B c\"": "예시: =SUBSTITUTE(\"a a b b b c\", \"b\", \"B\") 는 \"a a B B B c\" 를 반환합니다.",
  "填写的密钥、证书等信息采用动态加密存储，保存之后掩码显示，保证您的信息安全": "입력한 키와 인증서 등은 동적 암호화로 저장되며, 저장 후 마스킹되어 표시되어 정보 안전을 보장합니다.",
  "中设置APIv2密钥。密钥为32位，推荐使用搜索引擎（如百度）搜索内容：在线密码生成器生成，例如「随机密码生成器」，自己编写密钥无法发起支付。": "APIv2 키를 설정하세요. 키는 32자리입니다. 검색 엔진(예: Baidu)에서 ‘온라인 비밀번호 생성기’를 검색해 생성하세요. 예를 들어 ‘랜덤 비밀번호 생성기’를 사용할 수 있습니다. 직접 만든 키로는 결제가 처리되지 않습니다.",
  "按月订阅": "월간 구독",
  "方便快速选择应用的主题颜色，满足个性化需求": "애플리케이션 테마 색상을 빠르게 선택해 개인화 요구를 충족하세요.",
  "返回在某日期之前或之后、与该日期相隔指定工作日的某一日期的日期值": "특정 날짜를 기준으로 지정한 근무일 수만큼 이전 또는 이후의 날짜 값을 반환합니다.",
  "必须指定下一节点审批人": "다음 노드 결재자를 지정해야 합니다.",
  "如果您需要复用本流程，通过此操作将为本流程创建一个封装业务流程副本": "이 프로세스를 재사용해야 한다면, 이 작업으로 해당 프로세스의 래핑된 비즈니스 프로세스 복사본이 생성됩니다.",
  "示例：=ACOT(1) 将返回弧度为 0.785398163397448 的角度（45 度），其正切值为 1。": "예시: =ACOT(1)은 탄젠트 값이 1인 각도(45도)를 라디안 0.785398163397448로 반환합니다.",
  "3、密钥、证书等字段信息采用动态加密存储，保存后掩码显示，保障信息安全": "3. 키, 인증서 등의 필드 정보는 동적 암호화로 저장되며, 저장 후 마스킹되어 표시되어 정보 보안을 보장합니다.",
  "当前用户数已经达到限额，请去购买": "현재 사용자 수가 한도에 도달했습니다. 구매해 주세요.",
  "4、配置内容请参考": "4. 설정 내용은 다음을 참고하세요.",
  "调整您的座席数": "좌석 수 조정",
  "示例：=DECODEURI('name=%E7%B3%BB%E7%BB%9F')，结果：\"name=系统\"": "예시: =DECODEURI('name=%E7%B3%BB%E7%BB%9F'), 결과: \"name=시스템\"",
  "放弃支付后，当前填写的表单数据不会提交": "결제를 취소하면 현재 작성한 양식 데이터는 제출되지 않습니다.",
  "示例：=FIND(\"1天23小时15分钟\",\"\",天)，结果：1": "예시: =FIND(\"1일23시간15분\",\"\",일), 결과: 1",
