  "重新同步成功": "재동기화 완료",
  "进入“支付宝商家后台”-“账户中心”-“商户信息”页面，获取商户号和商户简称（别名）": "알리페이 상인 백오피스의 ‘계정 센터’ → ‘가맹점 정보’ 페이지로 이동하여 가맹점 번호와 가맹점 약칭(별칭)을 확인하세요.",
