  "5.设置商户API证书": "5. 가맹점 API 인증서 설정",
  "2、资金直达微信，本平台仅收取商户功能费，支持先试用后付费，点击": "2. 자금은 WeChat으로 바로 입금됩니다. 본 플랫폼은 가맹점 기능 요금만 부과합니다. 먼저 체험 후 결제 가능합니다. 클릭하세요.",
  "最近一段时间与您互动频率较高的用户自动显示在最常协作中": "최근에 상호작용 빈도가 높은 사용자는 ‘가장 많이 협업’에 자동 표시됩니다.",
