  "请前往市场-开发者后台完成续费": "마켓 > 개발자 백오피스로 이동해 연장을 완료하세요.",
  "保存当前表格列的冻结、隐藏、汇总、样式（宽度、对齐、显示方式）配置。此配置对所有用户生效": "현재 표의 열에 대한 고정, 숨김, 집계, 스타일(너비, 정렬, 표시 방식) 설정을 저장합니다. 이 설정은 모든 사용자에게 적용됩니다.",
  "证件超过有效期": "증명서 유효 기간이 지났습니다.",
  "向业务流程的流程参数传递初始值，供其执行时使用": "업무 프로세스의 프로세스 매개변수에 초기값을 전달하여 실행 시 사용합니다.",
  "设置LDAP服务器中用于和本系统账号匹配的字段": "LDAP 서버에서 본 시스템 계정과 매칭할 필드를 설정하세요.",
  "数据管理视图中的记录不受字段属性和业务规则的隐藏、只读、验证影响，始终可查看、编辑所有数据。（仅应用管理员可访问此视图）": "데이터 관리 보기에서는 레코드가 필드 속성과 비즈니스 규칙의 숨김, 읽기 전용, 유효성 검사 설정의 영향을 받지 않습니다. 모든 데이터를 항상 조회하고 편집할 수 있습니다. (이 보기는 애플리케이션 관리자만 접근 가능합니다)",
  "10.将前面步骤获取的信息填写到HAP中": "10. 이전 단계에서 가져온 정보를 HAP에 입력하세요.",
  "MM 月": "MM월",
  "日期不是日期类型": "날짜 형식이 아닙니다.",
  "3.使用注册支付宝商家账号填写的邮箱和密码登录": "3. 알리페이 가맹점 계정 등록 시 입력한 이메일과 비밀번호로 로그인하세요.",
  "z：表示需要计算其分布的数值": "z: 분포를 계산해야 하는 수치값을 의미합니다.",
  "当前授权": "현재 권한 부여",
  "为确保首次集成90天后正常使用，需向企业微信购买接口许可，由组织自己支付接口许可的费用，平台收到付费后在企微服务商后台代为缴费": "최초 연동 후 90일이 지나도 정상 사용하려면 WeCom 인터페이스 라이선스를 구매해야 합니다. 라이선스 비용은 조직이 직접 결제하며, 플랫폼이 결제를 확인하면 WeCom 서비스 파트너 콘솔에서 대납 처리합니다.",
  "示例：=PERMUT(5,3) ，结果：60": "예시: =PERMUT(5,3) , 결과: 60",
