  "2.点击”设置接口权限”，开通集成需要用到的接口权限": "2. ‘인터페이스 권한 설정’을 클릭해 연동에 필요한 인터페이스 권한을 활성화하세요.",
  "[周末设置]：指定周末的设置。可以是数字（1 到 17），表示一周中的哪些天是周末。默认值为 1，即周末为周六和周日": "[주말 설정]: 주말을 지정합니다. 1~17 사이의 숫자로 한 주 중 주말 요일을 설정합니다. 기본값은 1이며, 토요일과 일요일이 주말입니다.",
