  "仅修改商户简称无需验证": "가맹점 약칭만 수정 시 인증 불필요",
  "包含免费版的所有功能，此外还包括：": "무료 버전의 모든 기능 포함, 추가로 다음을 제공합니다:",
  "当未设自定义排序，或自定义排序后同顺序下有多条记录时，将追加使用默认排序。默认排序只能使用创建时间或最近更新时间，来确保数据最终有严格顺序。": "사용자 지정 정렬이 없거나, 지정 정렬에서 같은 순서의 레코드가 여러 개일 경우 기본 정렬을 추가로 적용합니다. 기본 정렬은 생성 시간 또는 최근 업데이트 시간만 사용할 수 있으며, 데이터의 최종 순서를 엄격하게 보장합니다.",
  "微信公众号支付；渠道费率参考微信支付官方规则": "WeChat 공식 계정 결제; 채널 수수료율은 WeChat Pay 공식 규정을 따릅니다.",
  "字段被工作流节点的部分配置（筛选、动态值等）使用": "필드가 워크플로 노드의 일부 설정(필터, 동적 값 등)에서 사용됨",
  "对文本\"name%3D%E6%98%8E%E9%81%93%E4%BA%91\"进行解码": "텍스트 \"name%3D%E6%98%8E%E9%81%93%E4%BA%91\" 디코딩 실행",
  "没有可查询内容": "조회할 내용이 없습니다.",
  "示例：=ENCODEURI('name=系统')，结果：'name=%E7%B3%BB%E7%BB%9F'": "예시: =ENCODEURI('name=系统'), 결과: 'name=%E7%B3%BB%E7%BB%9F'",
  "请输入外部公开页面的完整URL地址。注意：无法获取需要登录的页面，且外部页面可能无法完整捕捉或可能出错，建议使用前进行简单的测试。": "외부 공개 페이지의 전체 URL을 입력하세요. 참고: 로그인 필요한 페이지는 가져올 수 없으며, 외부 페이지는 완전히 캡처되지 않거나 오류가 발생할 수 있습니다. 사용 전에 간단히 테스트하는 것을 권장합니다.",
  "该账号已停用": "해당 계정이 비활성화되었습니다.",
  "根据业务需求平台提供不同的支付收款渠道，支持创建多个通道的商户": "비즈니스 요구에 맞춰 다양한 결제 수납 채널을 제공하며, 다중 채널 가맹점 생성을 지원합니다.",
  "自定义字段是一个支持使用 React 语法对当前字段进行样式和交互上的自定义的新字段。": "사용자 지정 필드는 React 문법으로 현재 필드의 스타일과 인터랙션을 자유롭게 구성할 수 있는 신규 필드입니다.",
