  "$": "$",
  "当上一节点审批人同意后，从设置的选择范围中选择本节点的审批人": "이전 노드 결재자가 승인하면, 설정된 선택 범위에서 본 노드의 결재자를 선택합니다.",
  "被替换字符串：原字符串主体中需要被替换的字符串": "대체된 문자열: 원본 문자열 본문에서 대체해야 하는 문자열",
