  "展示其他工作表通过关联记录、子表（实体）、级联字段对当前表的引用情况": "다른 워크시트에서 연관 레코드, 하위 테이블(엔티티), 종속 선택 필드를 통해 현재 테이블을 참조하는 내역을 표시합니다.",
  "1、支付费率及提现费率可在您的": "1. 결제 수수료와 출금 수수료는 고객님의",
  "表格行高": "표 행 높이",
  "使用支付宝商户号开通；费率参考支付宝支付官方规则": "Alipay 가맹점 번호로 개통\n수수료율은 Alipay 결제 공식 규정을 따릅니다.",
  "组件只支持 function 写法，你需要在编辑器里实现这样一个函数。只支持写一个函数，所有逻辑在函数内实现。不可以使用 import，所有逻辑都需要原生实现。React 下的所有属性都已经暴露到组件内，你可以直接使用。": "컴포넌트는 function 방식만 지원합니다. 에디터에서 해당 함수를 구현하세요. 함수는 하나만 작성할 수 있으며, 모든 로직은 함수 내부에서 처리해야 합니다. import는 사용할 수 없으며, 모든 로직은 기본 기능만으로 구현하세요. React의 모든 속성은 컴포넌트 내부에 이미 노출되어 있으니 바로 사용할 수 있습니다.",
