  "切换成功": "전환되었습니다.",
  "国际": "국제",
  "注意：一定要将文件保存到本地，证书申请后微信不支持查看": "주의: 파일을 반드시 로컬에 저장하세요. 인증서 신청 후에는 WeChat에서 확인할 수 없습니다.",
  "通知方式": "알림 방식",
