  "请填写函数、参数和运算符进行运算；函数和字段可从左侧面板选择或直接输入": "함수, 매개변수, 연산자를 입력해 계산하세요. 함수와 필드는 왼쪽 패널에서 선택하거나 직접 입력할 수 있습니다.",
