  "指定地区": "지정 지역",
  "免费版最多可以创建3个应用，请付费升级正式版以扩展更多用量": "무료版에서는 애플리케이션을 최대 3개까지 생성할 수 있습니다. 더 많은 용량이 필요하면 유료 정식版으로 업그레이드하세요.",
  "4.设置APIv2密钥": "4.APIv2 키 설정",
