  "示例：=RADIANS(90) 将返回 1.5707963267949（90 度约为 1.5708 弧度）。": "예시: =RADIANS(90)은 1.5707963267949를 반환합니다(90도는 약 1.5708라디안).",
  "7.获取支付宝应用APPID": "7. Alipay 앱 APPID 가져오기",
  "由上一审批节点选择": "이전 결재 노드에서 선택",
  "6.将商户号与AppID账号关联": "6. 가맹점 번호를 AppID 계정과 연동하기",
  "[返回类型]：指定周数的计算方式。默认值为 1，表示一周从周日开始，周日为一周的第一天": "[반환 유형]: 주차 계산 방식을 지정합니다. 기본값은 1이며, 일요일을 한 주의 첫째 날로 간주합니다.",
  "委托内容": "위임 내용",
  "为完整显示历史引用关系，需通过初始化对全组织工作流节点进行扫描，以获取所有工作流对字段及表的引用情况。": "과거 참조 관계를 완전하게 표시하려면, 초기화 과정에서 전체 조직의 워크플로 노드를 스캔하여 모든 워크플로의 필드 및 테이블 참조 현황을 수집해야 합니다.",
  "本次测试消耗 %0 tokens， 计费 %1 $": "이번 테스트에서 %0 tokens이(가) 소모되었고, 청구 금액은 %1 $입니다.",
  "当可以保证配置的自定义排序严格有序，或已经为自定义排序创建了索引时，可以勾选不追加默认排序。注意：如果不满足以上条件就取消了追加的默认排序，可能会因为同顺序下有多条记录，而导致翻页时数据缺少或重复。": "구성한 사용자 지정 정렬이 엄격한 순서를 보장하거나, 사용자 지정 정렬용 인덱스를 이미 생성했다면 ‘기본 정렬 추가 안 함’을 선택할 수 있습니다. 참고: 위 조건을 충족하지 않은 상태에서 기본 정렬 추가를 해제하면, 동일한 순서에 여러 레코드가 있어 페이지 이동 시 데이터가 누락되거나 중복될 수 있습니다.",
  "API安全": "API 보안",
  "支付宝官网": "Alipay 공식 홈페이지",
  "您已升级至更高的版本": "더 높은 버전으로 업그레이드되었습니다.",
  "3.离线录入时，表单的业务规则、字段验证和权限控制都不生效。数据暂存本地，网络恢复后需手动提交，确保数据结构完整性。": "3. 오프라인 입력 시 양식의 비즈니스 규칙, 필드 검증 및 권한 제어가 적용되지 않습니다. 데이터는 로컬에 임시 저장되며, 네트워크가 복구된 후 수동으로 제출해야 데이터 구조의 무결성을 보장할 수 있습니다.",
  "微信支付商户号": "WeChat Pay 가맹점 번호",
  "点击并开通手机网站支付": "클릭하여 모바일 웹사이트 결제를 개통하세요.",
  "商户APIv2密钥": "가맹점 API v2 키",
  "若想恢复组织，请到个人账户 - 我的组织 找到已关闭的组织列表进行恢复": "조직을 복구하려면 개인 계정 > 내 조직에서 종료된 조직 목록을 찾아 복구하세요.",
  "指定显示在时间块上的内容": "시간 블록에 표시할 내용 지정",
  "正方形": "정사각형",
  "我们正在为您的组织进行授权，预计需要约1分钟。授权完成后，您将收到系统消息通知。": "조직에 대한 권한 부여를 진행 중입니다. 약 1분 정도 소요됩니다. 완료되면 시스템 알림이 발송됩니다.",
  "将于%0到期": "%0에 만료될 예정입니다.",
  "输入商户简称": "가맹점 약칭을 입력하세요.",
  "返回2025年2月19日是该年的第8周（从周一计算）": "2025년 2월 19일은 해당 연도의 8번째 주입니다(월요일 기준).",
  "上传的图标可用于应用配置时的图标选择，建议使用 SVG 格式的单色图标": "업로드한 아이콘은 애플리케이션 설정에서 아이콘 선택에 사용할 수 있습니다. SVG 형식의 단색 아이콘을 권장합니다.",
  "天数：一个正数表示向后推算天数，一个负数表示向前推算天数": "일수: 양수는 앞으로의 일수를, 음수는 이전 일수를 의미합니다.",
  "关闭超过90天的组织，所有应用将自动进入回收站，进入回收站60天后，所有应用将被彻底物理删除": "90일 이상 비활성화된 조직의 모든 애플리케이션은 자동으로 휴지통으로 이동합니다. 휴지통으로 이동한 지 60일이 지나면 모든 애플리케이션이 완전히 물리적으로 삭제됩니다.",
  "示例：=ASIN(0.84114709848079) 返回近似值 0.999400825621613，即正弦值为 0.8411470984807897 的角度的弧度（约为 57.3 度）。": "예시: =ASIN(0.84114709848079)은 약 0.999400825621613을 반환합니다. 이는 사인 값이 0.8411470984807897인 각도의 라디안 값이며(약 57.3도).",
  "标准正态分布累积函数": "표준 정규분포 누적함수",
  "按年计费": "연간 과금",
  "商户号管理": "가맹점 번호 관리",
  "转为封装业务流程": "문구를 패키지형 비즈니스 프로세스로 전환",
  "支付通道": "결제 채널",
  "示例：=SUBSTITUTE(\"a a b b b c\", \"a\", \"A\", 2) 返回\"a A b b b c\"": "예시: =SUBSTITUTE(\"a a b b b c\", \"a\", \"A\", 2)는 \"a A b b b c\"를 반환합니다.",
  "标题与样式": "제목 및 스타일",
  "在审批记录详情页，右侧的当前节点卡片内会显示对审批内容或操作的提示信息": "결재 기록 상세 페이지의 오른쪽 현재 노드 카드에 결재 내용이나 작업에 대한 안내 메시지가 표시됩니다.",
