  "生成一个从本周周一开始的7天的日期选择器，日期以胶囊的形式展示，用户选中日期后保存。如果载入时有值，则显示为值所在的那一周的7天，并默认选中值。当组件参数 env 中的 isDisabled 为 true 时，禁用日期选择器。": "이번 주 월요일부터 7일을 표시하는 날짜 선택기를 생성합니다. 날짜는 캡슐 형태로 표시되며, 사용자가 날짜를 선택하면 저장됩니다. 로드시 값이 있으면 해당 값이 속한 주의 7일을 표시하고, 기본으로 그 값을 선택합니다. 컴포넌트 파라미터 env의 isDisabled가 true이면 날짜 선택기를 비활성화합니다.",
  "同时开启公开表单、支付金额字段选择金额/数值，开启设置交易有效期才能开启，开启后支付成功才能提交表单数据，否则表单数据不提交": "공개 양식과 결제 금액 필드(금액/숫자) 설정을 동시에 켜면, 거래 유효 기간 설정을 활성화해야 합니다. 활성화 후 결제가 성공해야만 양식 데이터가 제출되며, 그렇지 않으면 제출되지 않습니다.",
  "LDAP服务器中对应本系统用户邮箱的字段": "LDAP 서버에서 본 시스템의 사용자 이메일에 해당하는 필드",
