  " 在微信商户后台的“产品中心”—“我的产品”页面中开通JSAPI支付和Native支付，如果其中一个支付方式未开通，在配置微信支付时会报“该商户号未开通公众号支付”的错误提示。": "WeChat 상점 관리자 백오피스의 ‘제품 센터’ → ‘내 제품’ 페이지에서 JSAPI 결제와 Native 결제를 모두 활성화하세요. 둘 중 하나라도 미활성화된 경우, WeChat Pay를 설정할 때 “해당 상점 번호는 공식계정 결제가 미개통되었습니다” 오류가 표시됩니다.",
