  "字符串反转函数": "문자열 역순 변환 함수",
  "1、启用应用内的支付功能必须要先在组织后台申请商户号并完成签约。商户签约是由第三方支付公司提供。": "1. 앱 내 결제 기능을 사용하려면 먼저 조직 백오피스에서 가맹점 번호를 신청하고 계약을 완료해야 합니다. 가맹점 계약은 제3자 결제사가 제공합니다.",
  "这个组件功能是去到名称的值，放大以红色显示出来。组件接收 `formData` 属性，formData 是记录的字段数据，你需要先在编辑器右上角把字段添加到引用并设置别名。这时你可以通过 `formData[env.别名]`来获取到对应的字段。": "이 컴포넌트는 이름 값으로 이동해 해당 값을 확대하고 빨간색으로 표시합니다. 컴포넌트는 `formData` 속성을 받으며, `formData`는 레코드의 필드 데이터입니다. 먼저 에디터 우측 상단에서 필드를 참조에 추가하고 별칭을 설정하세요. 그러면 `formData[env.별칭]`으로 해당 필드를 가져올 수 있습니다.",
  "COMBIN(总对象数,选择对象数)": "COMBIN(총 객체 수, 선택 객체 수)",
  "视图过滤": "보기 필터링",
