  "备份数据": "백업 데이터",
  "管理所有工作表数据。所有字段可见、可编辑；所有打印模版、自定义动作均可用；开启所有功能开关。": "모든 워크시트 데이터를 관리합니다. 모든 필드는 표시 및 편집 가능하며, 모든 인쇄 템플릿과 사용자 지정 동작을 사용할 수 있습니다. 모든 기능 스위치를 활성화합니다.",
  "受托人": "수탁자",
  "英文大写": "영문 대문자",
  "显示当前字段在字段、工作流、业务规则和视图中的具体引用位置。": "현재 필드가 필드, 워크플로, 비즈니스 규칙, 보기에서 참조된 위치를 표시합니다.",
