  "示例：=NORMSDIST(1.96,TRUE) ，结果：0.975": "예시: =NORMSDIST(1.96, TRUE) , 결과: 0.975",
  "空白子表指添加子表字段时选择了从空白添加的子表字段。当前字段正被以下空白子表中的字段使用": "빈 하위 테이블은 하위 테이블 필드를 추가할 때 ‘빈 상태에서 추가’를 선택해 만든 하위 테이블 필드를 의미합니다. 현재 필드는 다음 빈 하위 테이블의 필드에서 사용 중입니다.",
  "微信公众平台": "WeChat 공식账号 플랫폼",
  "清空成功，保存后生效": "초기화했습니다. 저장하면 적용됩니다.",
  "输入支付宝应用 appid": "Alipay 애플리케이션 appid를 입력하세요.",
  "示例：=SUBSTITUTE(\"aaabbccc\", \"bc\", \"BC\", 2) 返回\"aaabbccc\"": "예시: =SUBSTITUTE(\"aaabbccc\", \"bc\", \"BC\", 2) 결과는 \"aaabbccc\" 반환",
  "您的组织当前通过线下渠道购买 Nocoly 服务。请联系销售": "현재 귀 조직은 오프라인 채널을 통해 Nocoly 서비스를 구매하고 있습니다. 영업팀에 문의하세요.",
  "调用支付JSAPI缺少参数": "결제 JSAPI 호출에 필요한 매개변수가 없습니다.",
  "支持聚合支付（微信和支付宝）；费率0.25%": "집합 결제 지원(WeChat, Alipay), 수수료율 0.25%",
  "您确定放弃支付？": "결제를 포기할까요?",
  "2、资金直达支付宝；本平台仅收取商户功能费，支持先试用后付费，点击": "2. 자금은 Alipay로 직접 입금됩니다. 본 플랫폼은 가맹점 기능 이용료만 부과하며, 체험 후 결제가 가능합니다. 클릭하세요.",
  "依次进入": "차례대로 이동",
  "由鲸先企付提供，提交资料需要1-3个工作日完成申请；支持微信和支付宝聚合支付，费率固定为0.25%": "Jingxian Qifu 제공. 자료 제출 후 신청 완료까지 영업일 기준 1~3일 소요됩니다. WeChat·Alipay 통합 결제를 지원하며, 수수료는 고정 0.25%입니다.",
  "仅允许在市场中完成开发版购买与续费，请前往 市场-开发者 后台完成续费": "개발판 구매와 갱신은 마켓에서만 가능합니다. 갱신하려면 마켓-개발자 백오피스로 이동하세요.",
  "群组名称不能超过64个字符": "그룹 이름은 64자를 초과할 수 없습니다.",
  "总行数不限": "총 행 수 제한 없음",
  "组织关闭后，所有人将无法访问组织和应用。": "조직을 닫으면 모든 사용자가 조직과 애플리케이션에 접근할 수 없습니다.",
  "获得的私钥一定要保存好，后面需要复制到平台的 组织后台支付宝商户配置页面。": "발급받은 개인 키는 꼭 저장하세요. 이후 플랫폼의 조직 백오피스에서 Alipay 가맹점 설정 페이지에 복사해야 합니다.",
  "繁体大写": "번체 대문자",
  "WORKDAY(开始日期,天数,[假期列表])": "WORKDAY(시작 날짜, 일수, [휴일 목록])",
  "Markdown 是一种轻量级的标记语言输入方式。除了进行常规文本输入外，还可以添加简单的文本标识来实现对内容的格式化": "Markdown은 경량 마크업 언어 기반의 입력 방식입니다. 일반 텍스트를 입력하는 것뿐 아니라, 간단한 텍스트 표식을 추가해 콘텐츠를 손쉽게 서식화할 수 있습니다.",
  "90天后组织内所有应用将自动进入回收站，进入回收站60天后将被彻底物理删除，": "90일 후 조직 내 모든 애플리케이션이 자동으로 휴지통으로 이동되며, 휴지통으로 이동된 후 60일이 지나면 완전히 물리적으로 삭제됩니다.",
  "开发信息": "개발 정보",
  "恢复组织成功": "조직 복구 완료",
  "相关证书": "관련 인증서",
  "启用后，审批结果会以邮件的形式发送给发起人。": "사용 설정하면 결재 결과가 이메일로 프로세스 시작자에게 전송됩니다.",
  "数据管理": "데이터 관리",
  "完成「注册微信支付商户号」。如果已申请过微信普通商户号则不需要重复申请注册。": "WeChat Pay 가맹점 번호 등록을 완료하세요. 이미 일반 가맹점 번호를 신청했다면 다시 신청할 필요가 없습니다.",
  "保存为个人颜色": "개인 색상으로 저장",
  "在登录界面中显示给用户的名称。根据实际使用的登录账号字段进行设置": "로그인 화면에 사용자에게 표시되는 이름입니다. 실제 사용하는 로그인 계정 필드에 따라 설정하세요.",
  "开发版单个工作表下最多可创建1万条行记录，请联系顾问提供支持": "개발 버전에서는 워크시트당 최대 10,000행의 레코드를 생성할 수 있습니다. 지원이 필요하면 담당 컨설턴트에게 문의하세요.",
  "正切函数": "탄젠트 함수",
  "正在搜索相关应用和字段信息…": "관련 애플리케이션과 필드 정보를 검색하는 중입니다…",
  "计算从5本书中选择3本进行排列时，有60种不同的排列方式": "5권의 책 중 3권을 선택해排列하면 60가지 경우가 있습니다.",
