  "7.开通JSAPI支付、Native支付": "7.JSAPI 결제, 네이티브 결제 활성화",
  "列表中仅显示设置的摘要字段，点击单条明细后查看详情": "목록에는 설정된 요약 필드만 표시됩니다. 단일 항목을 클릭하면 상세 정보를 확인할 수 있습니다.",
