  "包含标准版的所有功能，此外还包括：": "스탠다드 버전의 모든 기능을 포함하며, 추가로 다음을 제공합니다:\"",
  "字段被部分字段配置（他表、汇总、公式、文本组合等）使用": "일부 필드 설정(다른 테이블, 집계, 수식, 텍스트 결합 등)에서 필드를 사용하고 있습니다.",
