  "其他视图": "기타 보기",
  "请用微信、微警或警融App扫下方二维码进行刷脸验证，验证通过后才能提交流程": "아래 QR 코드를 WeChat, 微警 또는 警融 App으로 스캔해 얼굴 인증을 진행하세요. 인증이 완료되어야 프로세스를 제출할 수 있습니다.",
