  "恢复组织": "조직 복구",
  "我确认删除%0和所有数据": "%0 및 모든 데이터를 삭제하는 것에 동의합니다.",
  "开关控制登录页面是否显示 7 天免登录的选项": "로그인 페이지에 ‘7일 자동 로그인’ 옵션 표시 여부를 제어하는 스위치",
  "请选择地区范围": "지역 범위를 선택하세요.",
  "进入支付宝商家后台绑定的网页应用获取其APPID": "알리페이 상가 백오피스에서 연결된 웹 애플리케이션의 APPID를 확인하세요.",
  "请输入请求地址": "요청 주소를 입력하세요.",
  "2.离线模式支持文本、数值、金额、邮箱、日期、时间、电话、附件、检查项、副文本、证件、定位、单选（静态数据）、多选（静态数据）、签名字段数据的录入。": "2. 오프라인 모드에서 텍스트, 숫자, 금액, 이메일, 날짜, 시간, 전화, 첨부 파일, 체크 항목, 부가 텍스트, 신분증, 위치, 단일 선택(정적 데이터), 다중 선택(정적 데이터), 서명 필드 데이터를 입력할 수 있습니다.",
  "请确保手机和邮箱均为可用状态": "휴대폰과 이메일이 모두 사용 가능한 상태인지 확인하세요.",
  "该账号不存在": "해당 계정이 존재하지 않습니다.",
  "支付商户号数量已达上限，请先购买": "결제 가맹점 번호 수가 한도에 도달했습니다. 먼저 구매하세요.",
  "法人姓名不一致": "법인 명의가 일치하지 않습니다.",
  "应用消息:您已被%0@刘兰%1添加为%2：%3销售线索管理%4的负责人": "앱 알림: %0@刘兰%1이(가) %2로 추가했습니다. %3판매 리드 관리%4의 책임자입니다.",
