  "TAN(弧度)": "TAN(라디안)",
  "选择数据": "데이터 선택",
  "请输入自定义显示名称": "사용자 지정 표시 이름을 입력하세요.",
  "请在微信的「账号中心——商户信息」查看自己商户号的类型。": "WeChat의 ‘계정 센터 → 가맹점 정보’에서 가맹점 번호 유형을 확인하세요.",
