  "的报错，请按以下步骤解决。": "오류가 발생했습니다. 다음 단계를 따라 해결하세요.",
  "生成一个 颜色选择器，用户选择颜色后将颜色以\"#XXXXXX\"的格式保存，加载时如果字段有值，将颜色回显到颜色选择器，当组件参数 env 中的 isDisabled 为 true 时，禁用颜色选择器。": "색상 선택기를 생성합니다. 사용자가 색상을 선택하면 색상을 \"#XXXXXX\" 형식으로 저장합니다. 로드 시 필드에 값이 있으면 해당 색상을 색상 선택기에 표시합니다. 컴포넌트 매개변수 env의 isDisabled가 true이면 색상 선택기를 비활성화합니다.",
