  "1、【按设置的排序】和【按关联视图的排序】两种排序方式仅限在关联数量不超过5条时生效，超出后会继续按添加时的顺序。": "문구 1. [설정한 정렬]과 [연결된 보기의 정렬] 방식은 연결 개수가 5개 이하일 때만 적용됩니다. 초과하면 추가한 순서대로 정렬됩니다.",
