  "%0 模型按 $%1 / 1K tokens 计费，直接从组织账户余额中扣除": "%0 모델은 $%1 / 1K tokens 기준으로 과금되며, 조직 계정 잔액에서 바로 차감됩니다.",
  "YYYY年MM月DD日 HH:mm:ss": "YYYY년 MM월 DD일 HH:mm:ss",
  "当前组织内有其他 %0 个用户，为避免您退出后组织无法正常使用，请添加其他超级管理员后再退出组织。如果您已确定不需要使用此组织，可以选择关闭组织": "현재 조직에 다른 사용자 %0명이 있습니다. 조직이 정상적으로 운영되지 않는 것을 방지하려면 다른 슈퍼 관리자 추가 후 조직에서 탈퇴하세요. 이 조직을 더 이상 사용할 필요가 없다면 조직을 종료할 수 있습니다.",
  "订阅方式": "구독 방식",
  "选择对象数：表示每次排列中选择的对象数，也必须是非负整数": "선택 대상 수: 각 순열에서 선택하는 대상의 수를 의미하며, 0 이상의 정수여야 합니다.",
  "配置视图": "설정 보기",
