  "示例：=ENCODEURI('name=系统')，结果：'name%3D%E7%B3%BB%E7%BB%9F'": "문구 예시: =ENCODEURI('name=系统'), 결과: 'name%3D%E7%B3%BB%E7%BB%9F'",
  "表被工作流节点的选择工作表控件使用": "해당 표가 워크플로 노드의 워크시트 선택 컴포넌트에서 사용 중입니다.",
  "示例：=SUBSTITUTE(\"a a b b b c\", \"a\", \"A\", 2) 返回“a A b b b c”": "예시: =SUBSTITUTE(\"a a b b b c\", \"a\", \"A\", 2) → “a A b b b c” 반환",
  "表被部分类型字段（关联记录、子表、查询记录等）使用": "일부 유형의 필드(연결 레코드, 하위 테이블, 조회 레코드 등)에서 이 테이블을 사용하고 있습니다.",
  "此用户未实名认证，谨防诈骗，谨慎沟通。": "이 사용자는 실명 인증되지 않았습니다. 사기에 주의하고 신중히 소통하세요.",
  "1.注册微信服务号": "1. WeChat 서비스 계정 등록",
  "当前选择为关联记录字段，可以继续选择关联表中的层级视图生成树状导航": "현재 선택한 항목이 ‘연관 레코드’ 필드입니다. 연관 테이블의 계층 보기 를 추가로 선택해 트리형 내비게이션을 생성할 수 있습니다.",
  "组织关闭后，所有人将无法访问组织和应用。90天后组织内所有应用将自动进入回收站，进入回收站60天后将被彻底物理删除，请谨慎操作！": "조직을 종료하면 모든 사용자가 조직과 애플리케이션에 접근할 수 없습니다. 90일 후 조직 내 모든 애플리케이션이 자동으로 휴지통으로 이동되며, 휴지통으로 이동된 지 60일 후 영구적으로 삭제됩니다. 신중히 진행하세요.",
  "获取日期时间计算结果的\"天\"": "날짜·시간 계산 결과의 ‘일’",
  "微信/支付宝直连无法获取手续费率": "WeChat/Alipay 직결에서 수수료율을 가져올 수 없습니다.",
  "ATAN(数值)": "ATAN(숫자)",
