  "当发起节点启用邮件通知功能后，这边同步开启相应设置，审批结果将通过邮件的形式及时发送给发起人。": "발신 노드에서 이메일 알림을 켜면, 여기서도 해당 설정이 함께 활성화됩니다. 결재 결과는 이메일로 즉시 프로세스 시작자에게 전송됩니다.",
  "示例：=STRREVERSE('Hello World') ，结果：dlroW olleH": "예시: =STRREVERSE('Hello World') , 결과: dlroW olleH",
  "可恢复60天内删除的应用，超过60天以上的应用会被物理删除，应用和数据不可恢复": "삭제 후 60일 이내의 애플리케이션은 복구할 수 있습니다. 60일이 지나면 물리적으로 삭제되며, 애플리케이션과 데이터는 복구할 수 없습니다.",
  "您也可以": "또한 다음을 할 수 있습니다.",
  "示例：=WORKDAY_INTL('2025-02-19',10,1,['2025-02-23','2025-02-28']) ，结果：2025-03-06": "예시: =WORKDAY_INTL('2025-02-19',10,1,['2025-02-23','2025-02-28']) , 결과: 2025-03-06",
