  "平台不收取任何微信支付手续费，从微信商户号后台提现到银行卡免费，但提现前需要结算，会按单笔订单收取对应的结算手续费，微信支付商户后台提现介绍点击查看，具体费率 点击查看。": "플랫폼은 WeChat Pay 결제 수수료를 일절 부과하지 않습니다. WeChat 가맹점 계정에서 은행 계좌로 출금은 무료입니다. 다만 출금 전 정산이 필요하며, 주문당 정산 수수료가 부과됩니다. WeChat Pay 가맹점센터 출금 안내 보기, 상세 요금 보기.",
  "上传apiclient_cert.p12文件，将其转成base64的文本内容，将文本内容复制粘贴到商户API证书字段内。": "apiclient_cert.p12 파일을 업로드하고, base64 텍스트로 변환하세요. 변환된 텍스트를 상점 API 인증서 필드에 복사해 붙여넣으세요.",
  "登录微信支付商户平台，进入产品中心——开发配置。": "WeChat Pay 가맹점 플랫폼에 로그인하고, 제품 센터 → 개발 설정으로 이동하세요.",
