  "示例：=SUBSTITUTE(\"a b c d e f\", \"b\", \"B\") 返回“a B c d e f”": "예시: =SUBSTITUTE(\"a b c d e f\", \"b\", \"B\") 결과는 \"a B c d e f\" 입니다.",
