  "累积：逻辑值，决定函数返回的形式。如果为TRUE，返回累积分布函数；如果为FALSE，返回概率密度函数。默认为TRUE": "누적: 함수 반환 형식을 결정하는 논리값입니다. TRUE이면 누적분포함수를 반환하고, FALSE이면 확률밀도함수를 반환합니다. 기본값은 TRUE입니다.",
