  "计算从2025年2月19日开始，经过10个工作日后的日期，排除周末和指定的两个假期日期": "2025년 2월 19일부터 시작하여 주말과 지정된 두 공휴일을 제외한 10 근무일 후 날짜 계산",
  "请您填写本人正确的身份信息，系统会自动验证人脸同时保证您的隐私安全，若信息正确但未能有效通过认证，可联系在线客服或专属顾问。": "본인 정확한 신원 정보를 입력하세요. 시스템이 얼굴을 자동으로 인증하며 개인정보는 안전하게 보호됩니다. 정보가 정확한데도 인증이 완료되지 않으면 온라인 고객센터나 전담 매니저에게 문의하세요.",
