  "指在审批流程中当人员设置为直属上级、上级部门负责人时。如果当前人员没有直属上级，则由本人自己处理；如果当前人员、部门没有上级部门，则由本部门负责人处理。未勾选时，则按照为空处理。": "결재 프로세스에서 결재자를 ‘직속 상급자’ 또는 ‘상위 부서 책임자’로 설정했을 때의 동작:\n- 현재 구성원에게 직속 상급자가 없으면 본인이 처리합니다.\n- 현재 구성원 또는 부서에 상위 부서가 없으면 해당 부서 책임자가 처리합니다.\n- 선택을 해제하면 값이 없음으로 처리합니다.",
  "打开你计算机上的「终端(Mac OS)」或 「命令行(Windows)」。": "컴퓨터에서 Terminal(Mac OS) 또는 명령 프롬프트(Windows)를 여세요.",
