  "示例：=IF($分数$>=60,'及格','不及格')，结果：'及格'": "예시: =IF($分数$>=60,'합격','불합격'), 결과: '합격'",
  "定义循环中使用的参数，每次循环可以使用前一次循环中更新的参数值。“index”参数每次循环后自动加1。": "루프에서 사용할 매개변수를 정의합니다. 각 루프에서는 이전 루프에서 업데이트된 매개변수 값을 사용할 수 있습니다. \"index\" 매개변수는 루프가 끝날 때마다 자동으로 1씩 증가합니다.",
  "无打印模板": "인쇄 템플릿 없음",
  "用户通讯录指当前操作人的通讯录；组织通讯录指当前组织的通讯录。此外，使用部门作为选择范围时，所设置部门及所有子部门中的人员可选；使用组织角色作为选择范围时，所设置角色下的所有人员可选。": "사용자 주소록은 현재 작업자의 주소록을 의미합니다. 조직 주소록은 현재 조직의 주소록을 의미합니다. 또한 선택 범위를 부서로 설정하면 해당 부서와 모든 하위 부서의 구성원을 선택할 수 있으며, 선택 범위를 조직 역할로 설정하면 해당 역할의 모든 구성원을 선택할 수 있습니다.",
  "用户通讯录": "사용자 주소록",
  "勾选后，进入视图初始不显示数据，查询后显示符合筛选条件的数据。": "체크하면 보기 진입 시 초기에는 데이터가 표시되지 않으며, 조회 후 필터 조건에 맞는 데이터만 표시됩니다.",
