  "3、已经通过其他支付平台拥有支付宝和微信商户号的企业如果要使用本平台收款依然需要重新完成商户签约。": "3. 다른 결제 플랫폼에서 Alipay 및 WeChat 가맹점 번호가 있는 기업도, 본 플랫폼에서 결제를 사용하려면 가맹점 계약을 다시 완료해야 합니다.",
