  "2.切换到“机器人”，启用机器人功能，这样在%0消息测就能直接收到内部的流程、应用消息": "2. ‘봇’으로 전환하고 봇 기능을 활성화하세요. 그러면 %0 메시지에서 내부 워크플로 및 애플리케이션 메시지를 바로 받을 수 있습니다.",
