  "启用水印配置后，将在组织所有应用内显示水印。可自定义水印文字": "워터마크 설정을 활성화하면 조직의 모든 애플리케이션에 워터마크가 표시됩니다. 워터마크 문구를 사용자 지정할 수 있습니다.",
