  "尚未配置工作地点": "근무지 설정되지 않음",
  "表格视图中的记录在移动端以卡片的形式呈现，为移动端设置记录的显示布局，以便于移动端的数据浏览和操作。": "표 보기의 레코드는 모바일에서 카드 형태로 표시됩니다. 모바일에서 레코드의 표시 레이아웃을 설정해 데이터 조회와 작업을 쉽게 하세요.",
  "勾选时，新的开始值保存后，下一条记录将直接以新开始值作为编号（例如，表中已编号至no.100，修改开始值为5并勾选此配置项，则下一条记录直接以no.5编号）": "체크하면 새 시작 값을 저장한 뒤, 다음 레코드는 새 시작 값을 그대로 번호로 사용합니다. (예: 표의 번호가 no.100까지 매겨진 상태에서 시작 값을 5로 변경하고 이 옵션을 체크하면, 다음 레코드는 바로 no.5로 번호가 매겨집니다.)",
  "已创建工作表（含聚合表）": "생성된 워크시트(집계 테이블 포함)",
  "下一条记录的编号": "다음 레코드의 번호",
  "支持10MB以内的xls、xlsx、csv文件, 最大行数不超过20000行，列数不超过200列；导入多选类型的控件，请确保Excel字段内各个选项/人员用“，”隔开；导入地区控件，省市县之间以“/”隔开，如：江西省/上饶市/铅山县，如填写的地区格式没有“/”，则会按照名称精准匹配": "10MB 이하의 xls, xlsx, csv 파일을 지원합니다. 최대 행 수는 20,000행, 열 수는 200열을 초과할 수 없습니다.\n다중 선택 타입 컴포넌트를 가져올 때는 Excel 필드의 각 옵션/인원을 쉼표(,)로 구분하세요.\n지역 컴포넌트를 가져올 때는 도/시/군·구를 “/”로 구분하세요. 예: 江西省/上饶市/铅山县. 입력한 지역 형식에 “/”가 없으면 이름으로 정확 일치 매칭을 수행합니다.",
