  "用于工作流获取打印文件节点，费用0.15元/次": "워크플로에서 인쇄 파일 가져오기 노드에 사용되며, 비용은 회당 0.15위안입니다.",
  "由于当前系统绑定的密钥技术支持时间已到期（%0 到期），无法升级到 %1 版本（发布时间早于到期时间的版本可升级），现已自动降为免费版，": "현재 시스템에 연결된 키의 기술 지원 기간이 만료되었습니다(%0 만료). %1 버전으로는 업그레이드할 수 없습니다(만료일 이전에 출시된 버전은 업그레이드 가능). 무료 버전으로 자동 전환되었습니다.",
