  "查询或获取一条符合条件的工作表记录": "조건에 맞는 워크시트 레코드 1개 조회 또는 가져오기",
  "批量操作设置": "일괄 작업 설정",
  "绑定服务号后，外部门户将可以通过指定的域名获取该服务号下微信用户的授权及OpenID，可以通过工作流为外部的微信用户推送模板消息": "서비스 번호를 연동하면, 외부 포털이 지정된 도메인을 통해 해당 서비스 번호의 WeChat 사용자 권한 및 OpenID를 얻을 수 있으며, 워크플로를 통해 외부 WeChat 사용자에게 템플릿 메시지를 발송할 수 있습니다.",
