  "%0正在导出，请稍等...": "%0 내보내는 중입니다. 잠시만 기다려 주세요...",
  "已同步账号：": "동기화된 계정:",
  "未支付，订单已过期": "결제되지 않았으며 주문이 만료되었습니다.",
  "扫描关注微信服务号并登录": "QR 코드를 스캔해 WeChat 서비스 계정을 팔로우하고 로그인하세요.",
  "7. 如需打印字段所选成员的工号、邮箱、手机号，请将代码：工号: _ID； 邮箱: _Email； 手机号: _Phone。插入到模版中，如#{[member]字段ID$[(_ID;_Email;_Phone)]$}  实现拼接样式：张三(888;1511515@qq.com;13475236985)": "7. 필드에서 선택한 구성원의 사번, 이메일, 휴대폰 번호를 출력하려면 코드: 사번: _ID; 이메일: _Email; 휴대폰: _Phone. 를 템플릿에 삽입하세요. 예: #{[member]字段ID$[(_ID;_Email;_Phone)]$} 결합 결과 예시: 张三(888;1511515@qq.com;13475236985)",
