  "可直接输入创建新的职位": "바로 입력하여 새 직무를 생성할 수 있습니다.",
  "邮件收费标准：邮件%0/封，自动从企业账务中心扣费。": "메일 요금 기준: 메일 %0/건, 기업 결제 센터에서 자동 차감됩니다.",
  "用量不足时自动消耗余额增补，10元/1,000次": "용량이 부족하면 잔액에서 자동 보충됩니다. 1,000회당 10위안.",
  "选择关联表的一个字段作为映射的匹配字段，支持的字段类型包括：文本框、电话号码、邮件地址、证件、文本拼接、自动编号、记录ID": "매핑용 기준 필드로 연결된 테이블의 필드 하나를 선택하세요. 지원되는 필드 유형: 텍스트 상자, 전화번호, 이메일 주소, 신분증, 텍스트 결합, 자동 번호, 레코드 ID.",
  "授权已更新": "권한 부여가 업데이트되었습니다.",
  "修复建议": "수정 권장사항",
