  "添加网页应用能力": "웹 애플리케이션 기능 추가",
  "可自定义组织别名和登录背景图片": "조직 별칭과 로그인 배경 이미지를 사용자 지정할 수 있습니다.",
  "记录打印模版数量已达上限（%0）": "레코드 인쇄 템플릿 수가 한도(%0)에 도달했습니다.",
  "导入失败，组织下应用数量已达上限": "가져오기에 실패했습니다. 조직의 애플리케이션 수가 한도에 도달했습니다.",
  "发送服务号消息是指向已关注服务号的微信用户发送模版消息。发送对象支持使用人员字段（通过微信授权注册的外部门户用户）或文本字段（存储微信服务号openid）。使用微信服务号模板消息需要组织后台绑定已认证的企业服务号，并在微信服务号后台开通“模板消息”功能。": "서비스 번호 메시지 발송은 서비스 번호를 팔로우한 WeChat 사용자에게 템플릿 메시지를 보내는 기능입니다. 발송 대상은 인원 필드(WeChat 인증을 통해 등록한 외부 포털 사용자) 또는 텍스트 필드(WeChat 서비스 번호 openid 저장)를 사용할 수 있습니다. WeChat 서비스 번호 템플릿 메시지를 사용하려면 조직 백엔드에서 인증된 기업 서비스 번호를 연동하고, WeChat 서비스 번호 콘솔에서 ‘템플릿 메시지’ 기능을 활성화해야 합니다.",
  "%0属于必填项，请填写后提交": "%0은(는) 필수 항목입니다. 입력 후 제출하세요.",
