  "选择一条已有记录，模拟表单字段有数据的情况": "기존 레코드 한 개를 선택하여 양식 필드에 데이터가 있는 상태를 시뮬레이션합니다.",
  "搜索群组": "그룹 검색",
  "升级受限提醒": "업그레이드 제한 알림",
