  "您可以": "사용할 수 있습니다",
  "万行": "만 행",
  "绑定后会占组织额度，且不可取消": "연동 후에는 조직 할당량이 차감되며, 취소할 수 없습니다.",
  "2、余额的变动会影响后续退款是否成功": "2. 잔액 변동은 이후 환불 성공 여부에 영향을 줍니다.",
  "%0天内可在 回收站 内找回已删除%1，无编辑权限的数据无法删除。": "%0일 이내에 휴지통에서 삭제된 %1을(를) 복구할 수 있습니다. 편집 권한이 없는 데이터는 삭제할 수 없습니다.",
  "请输入天数": "일수를 입력하세요.",
  "混合显示": "혼합 표시",
  "允许审批人撤回上次审批结果": "결재자가 지난 결재 결과를 제출 취소할 수 있도록 허용합니다.",
  "新增应用": "애플리케이션 추가",
  "未匹配或匹配到多个": "일치하지 않음 또는 다중 일치",
  "创建新职位：%0": "새 직무 생성: %0",
  "在进行工作表和工作流的所有下级部门检索时，若所有下级部门总数超过2000（含），系统将默认仅获取当前部门的“一级子部门”所有部门。": "워크시트와 워크플로에서 모든 하위 부서를 검색할 때, 하위 부서 총수가 2,000개 이상이면 시스템이 기본으로 현재 부서의 1단계 하위 부서만 가져옵니다.",
  "当前应用已过期，如要继续使用，请立即续订": "현재 애플리케이션의 사용 기간이 만료되었습니다. 계속 사용하려면 지금 바로 갱신하세요.",
  "已加载记录": "로드된 레코드",
  "所有流程": "모든 프로세스",
  "1.导入的数据": "1. 가져온 데이터",
  "安装的应用和授权的应用不一致": "설치된 애플리케이션과 권한 부여된 애플리케이션이 일치하지 않습니다.",
  "未勾选时，对于错误的数据仅跳过错误字段，其他字段仍然导入。勾选后将跳过整行数据。": "선택 해제 시, 오류가 있는 데이터는 오류 필드만 건너뛰고 나머지 필드는 그대로 가져옵니다. 선택하면 해당 행 전체를 건너뜁니다.",
  "签名规范：签名内容长度为2-12个字；由中英文组成，不能纯英文；签名内容必须能辨别所属公司名称或品牌名称；不符合规范的签名平台会清空需重新输入，同时运营商也会拦截。": "서명 규칙: 서명은 2~12자여야 합니다. 영문과 한중문 조합으로 구성해야 하며, 영문만으로는 사용할 수 없습니다. 서명은 소속 회사명 또는 브랜드명을 식별할 수 있어야 합니다. 규칙에 맞지 않으면 플랫폼에서 서명이 초기화되며 재입력이 필요하고, 통신사에서도 차단됩니다.",
  "向工作表新增一条或多条记录": "워크시트에 레코드를 하나 이상 추가",
  "将选项等复杂字段作为文本使用时请使用STRING函数，比如": "옵션 등 복합 필드를 텍스트로 사용하려면 STRING 함수를 사용하세요. 예:\"",
  "即可开始集成以及同步通讯录": "지금 바로 연동을 시작하고 주소록을 동기화하세요.",
  "建议上传图片大小限制5M以内。": "이미지는 5MB 이하로 업로드하는 것을 권장합니다.",
  "发起一个包含流转图的完整审批流程": "흐름도를 포함한 전체 결재 프로세스 시작",
  "强制中止当前流程，后续所有节点不再执行": "현재 프로세스를 강제로 중지합니다. 이후 모든 노드는 더 이상 실행되지 않습니다.",
  "将所有不重复的数据作为新记录导入工作表": "중복되지 않는 모든 데이터를 새 레코드로 워크시트에 가져오기",
  "工作流执行/月": "워크플로 실행/월",
  "存在必填参数未填": "필수 매개변수가 비어 있습니다.",
  "设为部门负责人": "부서 책임자로 지정",
  "您获取的多条数据可供本流程的数据处理节点或子流程节点使用。被数据处理节点（新增、更新、删除）使用，最多支持%0条。被子流程节点使用，最多支持%1条。": "가져온 여러 데이터는 본 워크플로의 데이터 처리 노드 또는 하위 워크플로 노드에서 사용할 수 있습니다. 데이터 처리 노드(추가, 업데이트, 삭제)에서 사용하는 경우 최대 %0개까지 지원합니다. 하위 워크플로 노드에서 사용하는場合 최대 %1개까지 지원합니다.",
  "勾选后，组织下所有人都可查看组织中的管理员角色（除超级管理员外），并申请加入": "선택하면 조직의 모든 사용자가 조직 내 관리자 역할(슈퍼 관리자 제외)을 조회하고 가입을 신청할 수 있습니다.",
  "成功离职后，也可以在 “离职交接” 中交接工作。": "퇴사 완료 후에도 ‘퇴사 인수인계’에서 업무를 인수인계할 수 있습니다.",
