  "该应用在组织下已存在，请勿重复导入": "해당 애플리케이션이 조직에 이미 존재합니다. 중복으로 가져오지 마세요.",
  "2、商户签约是验证收款商户合规性的基本流程，请完成以下四步操作，并依法依规提供真实有效的信息。": "2. 가맹점 계약은 수납 가맹점의 준법성을 검증하는 기본 절차입니다. 아래 4단계를 완료하고, 관련 법규에 따라 사실이고 유효한 정보를 제공하세요.",
