  "编号=开始值+创建记录数-1。若修改开始值，则之后的编号将根据新的开始值计算。例如，原来的开始值为1，已创建记录数为10，则当前最后一条编号为no.10；若此时将开始值修改为10，则下一条记录的编号为no.20。": "번호 = 시작 값 + 생성된 레코드 수 - 1. 시작 값을 변경하면 이후 번호는 새로운 시작 값으로 계산됩니다. 예를 들어 시작 값이 1이고 생성된 레코드 수가 10이면 현재 마지막 번호는 no.10입니다. 이때 시작 값을 10으로 변경하면 다음 레코드의 번호는 no.20입니다.",
  "非法的文件类型": "허용되지 않는 파일 형식",
