  "将 '-1' 和 5 相加（if输出的结果类型固定为文本）": "문구를 “-1”과 5를 더하기로 변경하세요(If 출력 결과 타입은 텍스트로 고정).",
  "返回 2021-5-1 的年份": "2021-5-1의 연도 반환",
  "未勾选时，用户可查看所有查询结果。勾选后，按照用户对数据的权限查看，隐藏无权限的数据或字段": "선택 해제 시 모든 조회 결과가 표시됩니다. 선택하면 사용자 데이터 권한에 따라 표시되며, 권한 없는 데이터나 필드는 숨겨집니다.",
