  "向 Access Token URL 发送请求并接收返回值": "Access Token URL로 요청을 보내고 반환 값을 받습니다.",
  "查询并批量更新": "조회 및 일괄 업데이트",
  "若要确保数据绝对唯一，可创建该字段的唯一索引。": "데이터를 절대적으로 고유하게 유지하려면 이 필드에 고유 인덱스를 생성하세요.",
  "从组织角色字段获取": "조직 역할 필드에서 가져오기",
  "选择AI模型": "AI 모델 선택",
  "您确定要删除审批结果分支吗？": "결재 결과 분기를 삭제할까요?",
  "否决/退回时必须认证": "반려/반송 시 인증이 필요합니다.",
  "项目已删除": "프로젝트가 삭제되었습니다.",
  "还没有短信模版": "아직 문자 메시지 템플릿이 없습니다.",
  "基于多条数据邀请多名用户": "여러 데이터 항목을 기반으로 다수 사용자 초대",
  "大写字母": "대문자",
  "小时: h": "시간: h",
  "设置筛选条件后，满足条件的数据才能进入该分支": "필터 조건을 설정하면, 조건을 충족하는 데이터만 이 분기로 이동합니다.",
  "增加": "추가",
  "没有与当前工作表关联的表": "현재 워크시트와 연동된 테이블이 없습니다.",
  "新版发送记录可以选择一个视图，按照所选视图配置的显示字段发送。如果通知人分发了此视图，可以直接按权限编辑记录、执行自定义动作。": "새로운 발송 기록에서 보기를 선택할 수 있으며, 선택한 보기의 표시 필드 구성에 따라 발송합니다. 알림 수신자가 이 보기를 배포한 경우, 권한에 따라 레코드를 바로 편집하고 사용자 지정 동작을 실행할 수 있습니다.",
  "该操作不可逆，请谨慎。": "이 작업은 되돌릴 수 없습니다. 신중히 진행하세요.",
  "等待分支汇集后再执行下方节点": "분기 합류 후 아래 노드를 실행합니다.",
  "分支下方的节点整体放置在": "분기 하단의 노드를 전체적으로 배치할 위치",
  "允许上传": "업로드 허용",
  "将“%0”转为子流程": "“%0”를 하위 워크플로로 전환",
  "发送API请求数组": "API 요청 배열 보내기",
  "相同选项集": "동일한 옵션 세트",
  "数值运算": "수치 연산",
  "请填写限制结尾显示的字符": "제한할 끝 문자 수를 입력하세요.",
  "校准工作表": "교정 워크시트",
  "从外部用户字段获取批量用户的相关信息": "외부 사용자 필드에서 다수 사용자의 관련 정보를 가져오기",
  "没有可用的节点对象": "사용 가능한 노드 객체가 없습니다.",
