  "本月消费": "이번 달 소비",
  "必须选择节点": "노드를 선택하세요.",
  "注意：切换为新方式并保存配置后，将无法恢复到旧的配置方式": "주의: 새 방식으로 전환해 설정을 저장하면, 이전 설정 방식으로 되돌릴 수 없습니다.",
  "校准": "보정",
  "流程进入此节点且审批开始前，更新数据对象的字段值（退回至此节点也会触发更新）": "프로세스가 이 노드에 진입해 결재를 시작하기 전, 데이터 객체의 필드 값을 업데이트합니다. (이 노드로 반려되어 돌아와도 업데이트가 트리거됩니다)",
  "请填写限制开头显示的字符": "시작 부분에 표시할 최대 글자 수를 입력하세요.",
  "结果小数点后保留": "결과 소수점 이하 자리수",
  "计算发生错误": "계산 중 오류가 발생했습니다.",
  "选择要执行的动作": "실행할 작업을 선택하세요.",
  "如：可以将 2008/11/11 12:23 格式化为“日期”，以2008/11/11参与运算。+8h后，得到时间结果：2008/11/11 8:00": "예: 2008/11/11 12:23을(를) ‘날짜’로 포맷해 2008/11/11 기준으로 계산할 수 있습니다. +8h 적용 후 시간 결과: 2008/11/11 8:00",
  "设置当前节点负责人为空时的处理方式。当使用默认设置时，按照流程发起节点中设置的统一的处理方式": "현재 노드의 책임자가 비어 있을 때의 처리 방식 설정. 기본 설정을 사용하면, 프로세스 시작 노드에 지정된 공통 처리 방식을 따릅니다.",
