  "分页": "페이지네이션",
  "使用「发起审批流程」节点可提供更完整的审批能力，旧「审批」节点即将被下线。流程中已添加的审批节点不受影响，仍可以继续使用。": "‘결재 프로세스 시작’ 노드를 사용하면 결재 기능을 더 완전하게 활용할 수 있습니다. 기존 ‘결재’ 노드는 곧 지원이 종료됩니다. 프로세스에 이미 추가된 결재 노드는 영향 없이 계속 사용할 수 있습니다.",
