  "仅通过自定义页面上的按钮调用的PBP支持界面推送功能（通过API和工作流调用时此节点无法生效）。": "사용자 지정 페이지의 버튼으로 호출되는 경우에만 PBP의 화면 푸시 기능을 지원합니다. API나 워크플로로 호출하면 이 노드는 동작하지 않습니다.",
  "设置筛选条件，获得满足条件的数据。如果未添加筛选条件，则获得所有来自该字段的外部用户的相关信息": "필터 조건을 설정해 조건에 맞는 데이터를 가져옵니다. 필터 조건을 추가하지 않으면 해당 필드의 모든 외부 사용자 관련 정보를 가져옵니다.",
  "正在编辑记录，无法触发自定义按钮": "레코드를 편집 중이라 사용자 지정 버튼을 실행할 수 없습니다.",
  "发送服务号消息是指向已关注公众号的微信用户发送模版消息。发送对象支持使用人员字段（通过微信授权注册的外部门户用户）或文本字段（存储微信公众号openid）。使用微信公众号模板消息需要组织后台绑定已认证的企业服务号，并在微信公众号后台开通“模板消息”功能。": "서비스 번호 메시지 발송은 해당 공식 계정을 팔로우한 WeChat 사용자에게 템플릿 메시지를 보내는 기능입니다. 발송 대상은 인원 필드(WeChat 인증으로 등록한 외부 포털 사용자) 또는 텍스트 필드(공식 계정의 openid 저장)를 사용할 수 있습니다. WeChat 공식 계정 템플릿 메시지를 사용하려면 조직 백엔드에서 인증된 기업 서비스 번호를 연결하고, WeChat 공식 계정 백엔드에서 ‘템플릿 메시지’ 기능을 활성화해야 합니다.",
  "打印记录": "인쇄 기록",
  "b. 批量申请以下权限": "b. 다음 권한 일괄 신청",
