  "根据当前流程节点中的记录对象，生成特定的对外分享链接。可以通过在邮件、短信的正文里引用此节点，邀请外部用户查看或填写指定的记录。": "현재 워크플로 노드의 레코드 객체를 기준으로 대외 공유 링크를 생성합니다. 메일이나 문자 본문에서 이 노드를 참조해 외부 사용자를 초대하고, 지정한 레코드를 조회하거나 작성하도록 할 수 있습니다.",
  "上一条（⌘ + ⇧ + ,）": "이전 항목(⌘ + ⇧ + ,)",
  "定位到“网页应用”的 H5应用配置信息，讲以下链接填入对应输入框内": "문안을 ‘웹 애플리케이션’의 H5 애플리케이션 설정 정보로 이동한 뒤, 아래 링크를 해당 입력란에 입력하세요.",
