  "在左侧显示卡片列表，可切换查看记录详情": "왼쪽에 카드 목록을 표시하고, 레코드 상세를 전환해 확인할 수 있습니다.",
  "添加参数": "매개변수 추가",
  "提示类型": "알림 유형",
  "结束执行时间": "실행 종료 시간",
  "企业微信管理员扫码并完成授权": "WeCom 관리자 QR 코드를 스캔하고 권한 부여를 완료하세요.",
  "多条业务流程的执行方式": "여러 비즈니스 프로세스의 실행 방식",
  "短信内容不能为空": "문자 메시지 내용을 입력하세요.",
  "执行到本节点时保存该记录更新前的数据，供流程中的其他节点使用": "이 노드에 도달하면 레코드 업데이트 전 데이터를 저장하여 워크플로의 다른 노드에서 사용할 수 있습니다.",
  "设置填写内容%02060": "설정 작성 내용%02060",
  "设置筛选条件，获得满足条件的数据。如果未添加筛选条件，则只从当前组织的所有组织角色中获得第一个（最新创建）角色的相关信息": "필터 조건을 설정해 조건에 맞는 데이터를 가져옵니다. 필터 조건을 추가하지 않으면, 현재 조직의 모든 조직 역할 중 첫 번째(가장 최근 생성) 역할의 관련 정보만 가져옵니다.",
  "获取记录数量上限": "레코드 조회 개수 상한",
  "没有搜索到\"": "검색 결과가 없습니다.",
  "1.什么是“企业微信用户账号”": "1. ‘WeCom 사용자 계정’이란 무엇인가요?",
  "短信%0/条，自动从企业账务中心扣费。70字计一条短信，超过70字以67字每条计费。每个标点、空格、英文字母都算一个字。短信实际发送可能有10-20分钟的延时。": "문자 메시지 %0/건, 기업 결제 센터에서 자동 차감됩니다. 70자까지 1건으로 과금되며, 70자를 초과하면 67자당 1건으로 과금됩니다. 문장부호, 공백, 영문자도 각 1자로 계산됩니다. 실제 발송에는 10~20분 지연될 수 있습니다.",
  "设置筛选条件，获得满足条件的数据。如果未添加筛选条件，则只从字段中获得第一名人员的相关信息": "필터 조건을 설정해 조건을 만족하는 데이터를 가져옵니다. 필터 조건을 추가하지 않으면 필드에서 첫 번째 담당자의 관련 정보만 가져옵니다.",
  "记录创建次数": "레코드 생성 횟수",
  "没有可导入Sheet": "가져올 수 있는 시트가 없습니다.",
  "从工作表中通过筛选条件和排序规则直接删除符合条件的唯一数据": "워크시트에서 필터 조건과 정렬 규칙을 적용해 조건에 맞는 고유 데이터를 바로 삭제합니다.",
  "被以下工作流触发": "다음 워크플로로 트리거됨",
  "3. 在开放平台，选择“企业内部应用”下的“轻应用”，创建轻应用": "3. 오픈 플랫폼에서 ‘기업 내부 애플리케이션’의 ‘라이트 애플리케이션’을 선택하고 라이트 애플리케이션을 생성하세요.",
  "参数满足下面条件时退出循环，请在循环中更新参数值以触发条件": "매개변수가 아래 조건을 만족하면 반복을 종료합니다. 조건을 충족하도록 반복 내에서 매개변수 값을 업데이트하세요.",
  "自定义同步字段（可选）": "사용자 지정 동기화 필드(선택)",
  "设置筛选条件，获得满足条件的数据。如果未添加筛选条件，则获得所有来自该字段的组织角色的相关信息": "필터 조건을 설정해 조건에 맞는 데이터를 가져옵니다. 필터 조건을 추가하지 않으면 해당 필드의 조직 역할에서 모든 관련 정보를 가져옵니다.",
  "生成链接": "링크 생성",
  "打开记录（空格）": "레코드 열기(스페이스)",
  "必须选择一个目标工作表": "목표 워크시트를 선택하세요.",
  "文档标题": "문서 제목",
  "此模式下允许发送10M以内附件": "이 모드에서는 10MB 이하의 첨부 파일을 보낼 수 있습니다.",
  "必须选择一个自定义页面": "사용자 지정 페이지를 하나 선택하세요.",
  "填写人操作": "작성자 작업",
  "设置筛选条件，获得满足条件的数据。如果未添加筛选条件，则获得所有来自该字段的人员的相关信息": "필터 조건을 설정해 조건에 맞는 데이터를 가져옵니다. 필터 조건을 추가하지 않으면 해당 필드의 모든 담당자 관련 정보를 가져옵니다.",
  "注意：切换后您需要重新配置查找规则": "주의: 전환 후 검색 규칙을 다시 설정해야 합니다.",
  "按累计成员数降序排列": "누적 구성원 수 기준 내림차순 정렬",
  "指定填写人": "지정 작성자",
  "不需要": "불필요함",
