  "删除前保留记录数据，供之后的流程节点使用": "삭제 전에 레코드 데이터를 보존하여 이후 워크플로 노드에서 사용합니다.",
  "页面宽度": "페이지 너비",
  "JSON格式有错误": "JSON 형식에 오류가 있습니다.",
  "短信类型": "문자 메시지 유형",
  "重复：%0": "중복: %0",
  "勾选后，当子流程数据源为单条对象，之后节点可使用子流程中的参数": "이 옵션을 선택하면, 하위 프로세스의 데이터 소스가 단일 객체일 때 이후 노드에서 하위 프로세스의 파라미터를 사용할 수 있습니다.",
  "被之后节点使用时": "이후 노드에서 사용될 때",
  "分开始，每隔": "분 시작, 매 간격",
  "触发条件": "트리거 조건",
  "可以根据成员属性去创建职位，如，技术、生产、销售设置后应用和工作流可以直接选择职位": "구성원 속성으로 직위를 생성할 수 있습니다. 예: 기술, 생산, 영업 등을 설정하면 애플리케이션과 워크플로에서 직위를 바로 선택할 수 있습니다.",
  "工作表不允许为空": "워크시트를 비워둘 수 없습니다.",
  "取消加星": "즐겨찾기 해제",
  "在底部显示并可设为不自动消失。可包含标题、描述、按钮，适合较多文字或带有操作的通知": "문안을 하단에 표시하고 자동으로 사라지지 않도록 설정할 수 있습니다. 제목, 설명, 버튼을 포함할 수 있으며, 긴 텍스트나 동작이 필요한 알림에 적합합니다.",
  "更新详情": "업데이트 상세",
  "API URL必填": "API URL은 필수입니다.",
  "请谨慎选择您的短信类型，后续如果在发送时出现实际类型不符合预设类型的，可能面临模版被停用的风险": "문자 메시지 유형을 신중히 선택하세요. 이후 발송 시 실제 유형이 사전 설정과 다르면 템플릿이 비활성화될 수 있습니다.",
  "通过工作流发送邮件时，链接可以按照设置的链接名称显示。如：在邮件中将链接显示为【点击查看记录】": "워크플로로 이메일을 보낼 때, 링크는 설정한 링크 이름으로 표시됩니다. 예: 이메일에서 링크를 [레코드 보기 클릭]으로 표시.",
  "密码必须由字母+数字组成": "비밀번호는 영문자와 숫자로 구성해야 합니다.",
  "记录创建人数": "레코드 생성 인원 수",
  "请填写新建关联记录": "신규 연관 레코드를 입력하세요.",
  "查看次数": "조회수",
  "3. 填写应用信息": "3. 애플리케이션 정보 작성",
  "默认值 (人员ID)": "기본값 (인원 ID)",
  "数组范例数据有错误": "배열 예시 데이터에 오류가 있습니다.",
  "回到组织管理后台的钉钉对接部分，开启第四步的功能开关": "조직 관리 백오피스의 DingTalk 연동 섹션으로 돌아가서 4단계의 기능 스위치를 켜세요.",
  "图片标题": "이미지 제목",
  "按照所选视图配置的显示字段发送，如果操作者被分发了此视图，可以直接按权限编辑记录、执行自定义动作": "선택한 보기에 설정된 표시 필드로 문안을 발송합니다. 이 보기가 운영자에게 배포된 경우, 권한에 따라 레코드를 바로 편집하거나 사용자 지정 동작을 실행할 수 있습니다.",
  "没有搜索到": "검색 결과가 없습니다.",
  "填写内容%02063": "작성 내용%02063",
  "全部顶层": "모두 최상위",
  "按创建任务数降序排列": "생성된 작업 수 기준 내림차순 정렬",
  "关联到": "연결 대상",
  "按发表动态更新数量降序排列": "게시 동적 업데이트 수 기준 내림차순 정렬",
  "获取多名人员的相关信息，包含个人信息（姓名、性别、生日、手机、邮箱）和组织信息（部门、职位、工号、上下级（可选）），供流程中的其他节点使用。": "여러 사람의 정보를 가져옵니다. 개인 정보(이름, 성별, 생일, 휴대폰, 이메일)와 조직 정보(부서, 직위, 사번, 상하 관계(선택))를 포함하며, 프로세스의 다른 노드에서 사용할 수 있습니다.",
  "这些是您短信模板中使用到的动态值，请给出范例数据用于人工审核时验证您的短信类型": "SMS 템플릿에서 사용하는 동적 값입니다. 심사 시 메시지 유형 검증을 위해 예시 데이터를 입력하세요.",
  "开始执行时间": "시작 실행 시간",
  "该字段不支持自定义填写": "이 필드는 사용자 지정 입력을 지원하지 않습니다.",
  "%0链接": "%0 링크",
  "被隐藏的成员 被限制后，不能看到企业所有通讯录": "숨김 처리된 구성원은 제한되며, 회사 전체 주소록을 볼 수 없습니다.",
  "获取一名人员的相关信息，包含个人信息（姓名、性别、生日、手机、邮箱）和组织信息（部门、职位、工号、上下级（可选）），供流程中的其他节点使用。": "한 명의 인원 정보를 가져옵니다. 개인 정보(이름, 성별, 생일, 휴대폰, 이메일)와 조직 정보(부서, 직무, 사번, 상하 관계(선택))를 포함하며, 프로세스의 다른 노드에서 사용할 수 있습니다.",
  "勾选后，将会生成一个记录Body全文的文本格式参数": "체크하면 Body 전체 내용을 기록하는 텍스트 형식 파라미터가 생성됩니다.",
  "公开表单仅统计非平台登录用户上传的附件": "공개 양식은 플랫폼에 로그인하지 않은 사용자가 업로드한 첨부 파일만 집계합니다.",
  "上一条（Ctrl + Shift + ,）": "이전 항목(Ctrl + Shift + ,)",
  "下一条（⌘ + ⇧ + .）": "다음 항목 (⌘ + ⇧ + .)",
  "此列表仅显示产生过数据的成员": "이 목록에는 데이터가 발생한 구성원만 표시됩니다.",
  "文件类型错误，仅支持xls、xlsx、csv文件": "파일 형식이 올바르지 않습니다. xls, xlsx, csv 파일만 지원합니다.",
  "同时执行多条业务流程，即便某条业务流程运行中止，也不影响其他业务流程的执行。": "여러 개의 비즈니스 프로세스를 동시에 실행합니다. 특정 프로세스가 중지되어도 다른 프로세스의 실행에는 영향을 주지 않습니다.",
  "在筛选条件的基础上，随机获取一个": "필터 조건을 기반으로 임의의 하나 가져오기",
  "跳出并终止循环，继续后面的流程": "루프를 종료하고 다음 프로세스를 계속 진행합니다.",
  "更改我的投票": "내 투표 변경",
  "该评论已被删除": "해당 댓글이 삭제되었습니다.",
  "审核时间约为1小时，非工作时间提交审核会延长": "검토 소요 시간은 약 1시간입니다. 근무 시간 외에 제출하면 지연될 수 있습니다.",
  "%0的组织用户": "%0의 조직 사용자",
