  "用户点击按钮后，立即弹出对话框并填写指定的内容": "사용자가 버튼을 클릭하면 즉시 대화상자가 열리고 지정된 내용을 입력합니다.",
  "如果某条子流程运行中止，则跳过该条继续执行下一条子流程": "어떤 하위 워크플로가 중지되면 해당 항목을 건너뛰고 다음 하위 워크플로를 계속 실행합니다.",
  "时开始，每隔": "시작 시간, 간격마다",
  "存在无权限删除的记录，有权限的已删除": "삭제 권한이 없는 레코드가 있습니다. 권한이 있는 레코드는 삭제되었습니다.",
