  "获取一名外部用户的相关信息，包含用户名、手机号、角色、用户状态、openid和自定义字段，供流程中的其他节点使用。": "외부 사용자 1명의 관련 정보를 조회합니다. 사용자명, 전화번호, 역할, 사용자 상태, openid 및 사용자 지정 필드를 포함하며, 워크플로의 다른 노드에서 사용할 수 있습니다.",
  "抱歉，此功能只开放给基于钉钉开通的组织": "죄송합니다. 이 기능은 DingTalk 기반으로 개설된 조직에만 제공됩니다.",
  "；解除与组织用户绑定关系": "조직 사용자와의 연결 해제",
  "勾选后，当执行次数为单次时，之后节点可使用业务流程的输出参数": "체크하면 실행 횟수가 1회일 때 이후 노드에서 업무 프로세스 출력 매개변수를 사용할 수 있습니다.",
