  "告诉AI模型在生成响应时应该如何行为以及需要参考的任何上下文。你可以描述助手的个性，告诉它应该回答什么和不应该回答什么，并告诉它如何格式化响应。系统消息将按所消耗token数进行计费。": "AI 모델이 응답을 생성할 때의 동작 방식과 참고해야 할 컨텍스트를 안내하세요. 어시스턴트의 성격을 설명하고, 무엇에 답해야 하는지와 답하지 말아야 하는지를 지정하며, 응답 형식도 지시할 수 있습니다. 시스템 메시지는 사용된 토큰 수에 따라 과금됩니다.",
