  "选择一个一对多关系的本表关联字段，数据将按此字段的父级（单条）、子级（多条）关系构成树形表格": "일대다 관계의 본 테이블 연동 필드를 선택하세요. 해당 필드의 상위(단일)·하위(다중) 관계를 기준으로 트리형 테이블이 구성됩니다.",
