  "勾选后，将对图片压缩后再进行上传。未勾选时，用户可自行选择是否上传原图。": "체크하면 이미지를 압축한 후 업로드합니다. 체크하지 않으면 원본 이미지 업로드 여부를 사용자가 선택할 수 있습니다.",
