  "，无结果时新增记录": "결과가 없으면 레코드 추가",
  "1列": "1열",
  "用于在邮件节点中插入动态值时指代当前节点，比使用节点ID更有辨识度。节点别名仅允许使用字母（不区分大小写）、数字和下划线组合，且必须以字母开头，不可重复。": "메일 노드에서 동적 값을 삽입할 때 현재 노드를 지칭하는 용도로 사용합니다. 노드 ID보다 식별하기 쉽습니다. 노드 별칭은 영문자(대소문자 구분 없음), 숫자, 밑줄만 사용할 수 있으며, 반드시 영문자로 시작해야 하고 중복될 수 없습니다.",
  "指定一个日期字段，将字段的日期作为时间表来触发流程。如：指定工作表中的员工生日或客户注册日期来发送短信通知": "날짜 필드를 지정하여 해당 날짜를 일정으로 삼아 프로세스를 트리거합니다. 예: 워크시트의 직원 생일 또는 고객 등록일을 지정해 문자 알림을 보냅니다.",
  "从当前应用获取多条信息": "현재 애플리케이션에서 여러 정보 가져오기",
  "当组织中有人员入职/离职时触发": "조직에 입사자/퇴사자가 발생하면 트리거됨",
  "必须先选择一个对象后，才能设置数据更新": "데이터 업데이트를 설정하려면 먼저 객체를 선택하세요.",
  "按照设定的时间周期循环触发流程": "설정된 주기에 따라 프로세스를 주기적으로 트리거합니다.",
