  "添加关联当前": "현재와 연동 추가",
  "获取多条组织角色信息": "여러 조직 역할 정보 가져오기",
  "勾选后，当用户选中“其他”时，必须在后面的文本框中填写内容。": "선택 시, 사용자가 ‘기타’를 선택하면 뒤의 텍스트 박스에 반드시 내용을 입력해야 합니다.",
  "发起审批流程": "결재 프로세스 시작",
  "每月第一天的00:00, 自动从初始值开始编号": "매월 1일 00:00에 초기값부터 자동으로 번호를 시작합니다.",
  "扣费说明": "요금 차감 안내",
  "分支固定为“通过”和“否决”。如果你同时需要对“否决”审批的数据进行处理时选择此分支": "분기를 ‘승인’과 ‘반려’로 고정합니다. ‘반려’된 결재 데이터를 함께 처리해야 하면 이 분기를 선택하세요.",
