  "对 数值/金额 等数字类型字段进行数学运算": "숫자/금액 등 숫자형 필드에 수학 연산 적용",
  "收件人：": "수신자:",
  "设置输入参数": "입력 매개변수 설정",
  "请输入指定错误码，如：400,401(多个状态码用英文逗号隔开)": "지정할 오류 코드를 입력하세요. 예: 400,401(여러 상태 코드는 영어 콤마로 구분)",
  "在审批节点下添加分支有两种选择：": "결재 노드에서 분기를 추가하는 방법은 두 가지입니다.",
  "字数": "글자 수",
  "开启后无论子表中是否存在记录，都会显示固定数量的行数。当子表没有记录时，将显示空白行。": "활성화하면 하위 테이블에 레코드가 있든 없든 고정된 행 수가 표시됩니다. 하위 테이블에 레코드가 없으면 빈 행이 표시됩니다.",
  "从工作表获取多条记录": "워크시트에서 여러 레코드 가져오기",
  "查询到的每行记录添加为一行子表明细。请选择需要写入的字段。": "조회된 각 레코드를 하위 테이블의 한 행으로 추가합니다. 작성할 필드를 선택하세요.",
  "绝对值": "절대값",
  "审批过程中更新": "결재 진행 중 문구 업데이트",
  "无主题": "제목 없음",
  "输出参数配置有误": "출력 매개변수 설정이 올바르지 않습니다.",
  "汇总结果": "집계 결과",
  "传入 JSON 对象数组格式的会话历史，将有助于AI理解上下文并进行连续对话。会话历史将按所消耗 token 数进行计费。": "문안을 JSON 객체 배열 형식의 대화 기록으로 전달하면 AI가 맥락을 이해하고 연속 대화를 진행하는 데 도움이 됩니다. 대화 기록은 사용된 token 수에 따라 과금됩니다.",
  "预置常用的意见作为模板，帮助审批人快捷填写": "자주 쓰는 결재 의견을 템플릿으로 미리 설정해 결재자가 빠르게 입력할 수 있도록 합니다.",
  "右侧（否决分支）": "오른쪽(반려 분기)",
  "取消勾选后，则编号不允许超出指定的位数，到达最大后将从0开始重新计数。如果位数设置不足会导致编号重复": "옵션 선택을 해제하면 번호가 지정한 자릿수를 초과할 수 없습니다. 최대값에 도달하면 0부터 다시 시작해 순번을 매깁니다. 자릿수가 부족하면 번호가 중복될 수 있습니다.",
  "发送指定数据对象": "지정한 데이터 객체로 전송",
  "第16层级": "16단계",
  "允许扫描条形码": "바코드 스캔 허용",
  "下拉框；": "드롭다운",
  "主题：": "테마:",
  "邀请多名用户": "여러 사용자 초대",
  "从记录链接获取": "레코드 링크에서 가져오기",
  "创建一个系统内日程。可同时生成一个ICS文件在其他节点中使用": "시스템 내 일정을 생성합니다. 동시에 다른 노드에서 사용할 수 있는 ICS 파일도 생성됩니다.",
  "配置 Access Token 刷新条件": "Access Token 새로 고침 조건 설정",
  "唯一分支": "고유 분기",
  "未配置 PDF 转换服务": "PDF 변환 서비스가 설정되지 않았습니다.",
  "获取关联记录": "연결된 레코드 가져오기",
  "的直接部门负责人": "직속 부서 책임자",
  "从工作表中筛选符合条件的数据并进行汇总计算，如：记录数量、求和、平均、最大、最小等。注意：当汇总他表字段或者数据频繁变更时可能有一定延时": "워크시트에서 조건에 맞는 데이터를 필터링해 집계합니다. 예: 레코드 수, 합계, 평균, 최댓값, 최솟값 등. 참고: 다른 테이블의 필드를 집계하거나 데이터 변경이 잦으면 지연이 발생할 수 있습니다.",
  "对查找到的数据进行分支处理。未查找到数据时，流程中止": "조회된 데이터를 기준으로 분기 처리합니다. 데이터가 없으면 프로세스를 중지합니다.",
  "请填写限制结尾显示的字数": "제한된 끝부분에 표시할 글자 수를 입력하세요.",
  "向上19级": "위로 19단계",
  "审批设置": "결재 설정",
  "数据源：": "데이터 소스:",
  "向上7级": "위로 7단계",
  "校准刷新符合筛选条件的工作表记录的计算结果、选项排序和分值、他表字段和汇总结果，此节点为异步排队执行，一次最多刷新10万行记录。每次校准必须间隔120分钟以上，否则将跳过节点": "필터 조건에 맞는 워크시트 레코드의 계산 결과, 선택 항목 정렬과 점수, 다른 테이블 참조 필드와 집계 결과를 보정 새로고침합니다. 이 노드는 비동기 대기열로 실행되며, 한 번에 최대 10만 행을 새로고침합니다. 보정은 최소 120분 간격으로만 수행되며, 간격 미만이면 노드를 건너뜁니다.",
  "请输入补充信息": "추가 정보를 입력하세요.",
  "通道：${routerList[v]}": "채널: ${routerList[v]}",
  "这是一个兼容保留的历史配置，现在此字段类型已不再支持此设置。如果你不需要此功能可以取消勾选，避免性能浪费。": "이 설정은 호환성 유지를 위해 남겨둔 기존 구성입니다. 현재 이 필드 유형에서는 더 이상 지원하지 않습니다. 기능이 필요 없으면 체크를 해제해 성능 낭비를 줄이세요.",
  "获取多条人员信息": "여러 명의 인원 정보 가져오기",
  "选中后，不允许用户填写和已有字段值重复的数据，但对工作流或API写入、批量导入等操作不做限制。": "선택하면 사용자가 기존 필드 값과 중복되는 데이터를 입력할 수 없습니다. 다만 워크플로 또는 API 쓰기, 대량 가져오기 등의 작업에는 제한을 두지 않습니다.",
  "查询并更新记录": "레코드 조회 및 업데이트",
  "点击编辑函数": "함수 편집 클릭",
  "正在查看历史执行详情（${dayStr} ${time}），本月新增、本月排队指截止到 ${dayStr} ${time} 的值": "히스토리 실행 내역을 조회 중입니다 (${dayStr} ${time}). ‘이번 달 신규’, ‘이번 달 대기’는 ${dayStr} ${time} 기준 값입니다.",
