  "在本节点内更新最大支持1000行。更新后数据可供流程中其他数据处理节点或子流程节点继续使用。被数据处理节点（新增、更新、删除）使用，最多支持100条。": "이 노드에서 최대 1,000행까지 업데이트할 수 있습니다. 업데이트된 데이터는 워크플로의 다른 데이터 처리 노드나 하위 워크플로 노드에서 계속 사용할 수 있습니다. 데이터 처리 노드(추가, 업데이트, 삭제)에서 사용할 경우 최대 100건까지 지원합니다.",
