  "经典模式：点整行打开记录": "클래식 모드: 행을 클릭하면 레코드가 열립니다.",
  "第15层级": "15단계",
  "更换为新的工作表后，所有相关节点配置的字段都将被重置，你需要重新配置这些节点。请确认你需要执行此操作": "새 워크시트로 변경하면 관련 노드 설정의 필드가 모두 초기화됩니다. 해당 노드를 다시 설정해야 합니다. 이 작업을 진행할까요?",
  "工作流将被删除，请确认执行此操作": "워크플로가 삭제됩니다. 이 작업을 진행할까요?",
  "可编辑已有明细": "기존 내역 편집 가능",
  "根据 Refresh token 刷新 Access Token": "Refresh token으로 Access Token 새로고침",
