  "添加转审候选人": "전결 이관 후보자 추가",
  "工作表无效或已删除": "워크시트가 유효하지 않거나 삭제되었습니다.",
  "将所选流程的排队计数重置为0。长期运行监控时可能偶发计数不准的问题，可通过此操作将计数归0": "선택한 프로세스의 대기열 카운트를 0으로 초기화합니다. 장기간 모니터링 시 간헐적으로 집계가 부정확할 수 있으며, 이 작업으로 카운트를 0으로 맞출 수 있습니다.",
  "代码片段库": "코드 스니펫 라이브러리",
  "代码错误": "코드 오류",
  "必须选择他表字段": "다른 테이블의 필드를 선택하세요.",
  "显示格式": "표시 형식",
  "右移一位": "오른쪽으로 한 칸 이동",
  "获取关联记录、子表、级联选择字段中的记录": "연결된 레코드, 하위 테이블, 종속 선택 필드의 레코드 가져오기",
  "富文本（支持html样式）": "리치 텍스트(HTML 스타일 지원)",
  "，无结果时继续执行": "결과가 없어도 계속 실행",
  "编辑节点别名和说明": "노드 별칭과 설명 편집",
  "向上6级": "위로 6단계",
  "发送方式": "발송 방식",
  "去插件中心添加": "플러그인 센터에서 추가",
  "将字段值显示为掩码，应用管理员和有解码权限的用户可以点击后解码查看（解码权限需要在用户-角色-字段权限中配置）。在对外公开分享时始终掩盖": "필드 값을 마스킹으로 표시합니다. 애플리케이션 관리자와 디코딩 권한이 있는 사용자는 클릭하여 디코딩 후 확인할 수 있습니다(디코딩 권한은 사용자-역할-필드 권한에서 설정). 외부 공개 공유 시에는 항상 마스킹됩니다.",
  "节点结果通知发起人": "노드 결과를 발신자에게 알림",
  "从记录获取关联记录": "레코드에서 연관 레코드 가져오기",
  "仅主部门负责人需要审批": "주 부서 책임자만 결재가 필요합니다.",
  "选择关联表中的关联本表字段": "연결된 테이블에서 본 테이블과 연결된 필드 선택",
  "复制已有节点": "기존 노드 복사",
  "节点否决后，更新数据对象的字段值": "노드 반려 후 데이터 객체의 필드 값 업데이트",
  "虚拟掩码长度应在1～100以内": "가상 마스킹 길이는 1~100 사이여야 합니다.",
  "注：此方式最多获取1000条关联记录，如果需要获取更多数据，请使用“从工作表获取记录”的方式。": "참고: 이 방식은 최대 1000개의 연관 레코드만 가져올 수 있습니다. 더 많은 데이터가 필요하면 ‘워크시트에서 레코드 가져오기’를 사용하세요.",
  "设为摘要的字段可以在待办列表和邮件通知中直接查看。": "요약으로 설정한 필드는 할 일 목록과 이메일 알림에서 바로 확인할 수 있습니다.",
  "从存有记录链接的文本字段获取一条指定记录": "레코드 링크가 포함된 텍스트 필드에서 지정한 레코드 1건 가져오기",
  "两个日期间的时长": "두 날짜 사이의 기간",
  "最多获取条数不能为空": "최대 가져오기 개수는 비워 둘 수 없습니다.",
  "选择要执行的动作，或": "실행할 동작을 선택하거나",
  "指定字符之后的字": "지정한 문자 이후의 문자",
  "获取一名人员的相关信息，包含个人信息（姓名、性别、生日、手机、邮箱）和组织信息（部门、职位、工号、上下级（可选））": "한 명의 인원 정보를 조회합니다. 개인 정보(이름, 성별, 생일, 휴대폰, 이메일)와 조직 정보(부서, 직책, 사번, 상하 관계(선택))를 포함합니다.",
  "电子表格模式：点单元格选中字段，按空格键打开记录": "스프레드시트 모드: 셀을 클릭해 필드를 선택하고, Space 키로 레코드를 열기",
  "从多条数据节点获取一条符合条件的记录": "여러 데이터 노드에서 조건에 맞는 레코드 1개 가져오기",
  "选择统计图表": "통계 차트 선택",
  "第18层级": "18단계",
  "会签（只需一名审批人通过，否决需全员否决）": "전원 승인(결재자 1명 승인 시 통과, 반려는 전원 반려 시 처리)\"",
  "彻底删除后数据不可恢复，请谨慎操作": "완전히 삭제하면 데이터를 복구할 수 없습니다. 신중히 진행하세요.",
