  "腾讯云SQLServer 产品": "Tencent Cloud SQL Server 제품",
  "在 Oracle 12c 之前的版本中，数据库被组织为一个个独立的实例，每个实例可以包含一个或多个数据库。这些数据库被称为非容器数据库，每个数据库都有自己的系统表空间和用户表空间。简而言之，Oracle 12c 之后的版本都是容器数据库CDB。": "Oracle 12c 이전 버전에서는 데이터베이스가 독립적인 인스턴스로 구성되며, 각 인스턴스에 하나 이상의 데이터베이스가 포함될 수 있습니다. 이러한 데이터베이스는 비 컨테이너 데이터베이스(non-CDB)로 불리며, 각 데이터베이스는 자체 시스템 테이블스페이스와 사용자 테이블스페이스를 가집니다. 요약하면, Oracle 12c 이후 버전은 컨테이너 데이터베이스(CDB)입니다.",
