  "如果分解后的任务比较复杂、需要分别指派负责人，或需要在每条任务中分别记录跟进情况的，建议使用子任务。其他情况下，建议使用检查清单来做关键结果追踪，支持将重要检查项一键转为任务": "세부 작업이 복잡해 각기 책임자를 지정해야 하거나, 항목별로 진행 상황을 별도로 기록해야 한다면 하위 작업을 사용하세요. 그 외에는 체크리스트로 핵심 결과를 추적하는 것을 추천하며, 중요 체크 항목은 한 번에 작업으로 전환할 수 있습니다.",
  "轮播图设置": "캐러셀 설정",
  "截止到目前为止任务负责人负责的任务逾期时间统计，包含进行中和已完成的逾期时间，向下取整。如：3个进行中任务逾期时间累计为15小时，则显示总逾期0天，若累计为26小时，则显示总逾期1天，以此类推": "현재까지 책임자가 맡은 작업의 지연 시간 합계를 집계합니다. 진행 중과 완료된 작업의 지연 시간을 포함하며, 일 단위로 내림합니다. 예: 진행 중 작업 3개의 지연 시간이 합계 15시간이면 총 지연 0일로 표시되고, 26시간이면 총 지연 1일로 표시됩니다.",
  "确认要以原始附件名作为发布动态内容？": "원본 첨부 파일 이름을 게시 동적 콘텐츠로 사용할까요?",
