  "勾选后，在移动端App获得拍摄结果后会自动提交表单。配合上个功能，用户在拍摄录入的特定场景下可以无需中间步骤，一次完成操作。此功能在自定义按钮填写时也会生效。": "체크하면 모바일 앱에서 촬영 결과를 받은 뒤 양식이 자동으로 제출됩니다. 이전 기능과 함께 사용하면 특정 촬영 입력 상황에서 중간 단계 없이 한 번에 처리할 수 있습니다. 이 기능은 사용자 지정 버튼 작성 시에도 적용됩니다.",
