  "勾选后，在激活搜索下拉框时先进行一次请求，此时向接口传入的搜索参数为空，并将返回结果作为预设的选项以供选择。当API的搜索参数支持传空时，可以勾许此项。": "체크하면 검색 드롭다운을 활성화할 때 먼저 한 번 요청을 보냅니다. 이때 인터페이스로 전달되는 검색 파라미터는 비어 있으며, 반환된 결과를 미리 선택 가능한 옵션으로 사용합니다. API의 검색 파라미터가 빈 값 전달을 지원할 경우 이 항목을 체크하세요.",
