  "建立唯一索引后，字段的值不允许重复。如果字段为非必填，则整个工作表只能有一条为空的数据，以保证数据的唯一性": "고유 인덱스를 설정하면 해당 필드 값은 중복될 수 없습니다. 필드가 필수가 아니라면 데이터의 고유성을 보장하기 위해 워크시트 전체에서 비어 있는 값은 한 건만 허용됩니다.",
  "最多输入%0条记录，超出的记录不写入": "최대 %0개의 레코드만 입력할 수 있으며, 초과된 레코드는 저장되지 않습니다.",
  "个节点指定的对象已删除": "선택한 노드의 지정 대상이 삭제되었습니다.",
  "将来14天": "향후 14일",
  "人工节点（旧）": "수동 노드(구)",
  "检测到您输入了 %0 行内容,可以为您创建 %0 条记录。您也可以只创建一条记录": "입력한 내용이 %0행 감지되었습니다. %0개의 레코드를 생성할 수 있습니다. 한 개만 생성할 수도 있습니다.",
  "并非如此。索引只会加速检索，而在新增、更新、删除记录时系统会花费更多的时间用于更新索引，过多的索引会很明显的降低这些操作的速度，甚至影响到查询的速度。": "그렇지 않습니다. 인덱스는 검색만 빠르게 해 줍니다. 반면 레코드를 추가·수정·삭제할 때는 인덱스 갱신에 더 많은 시간이 들기 때문에, 인덱스가 많으면 이러한 작업 속도가 눈에 띄게 느려지고 심지어 조회 성능에도 영향을 줄 수 있습니다.",
  "重置编号失败": "번호 재설정에 실패했습니다.",
  "参数对象": "파라미터 객체",
  "已排期": "일정 확정됨",
