  "市场购买应用不属于该组织": "마켓에서 구매한 애플리케이션이 해당 조직에 속하지 않습니다.",
  "为你的每一个业务对象创建工作表，如：线索表、客户表、订单表。": "각 비즈니스 객체마다 워크시트를 생성하세요. 예: 리드 워크시트, 고객 워크시트, 주문 워크시트.",
  "只有表头下方的数据才会被导入": "표 헤더 아래의 데이터만 임포트됩니다.",
  "文件原始名": "파일 원본 이름",
  "彻底删除不触发工作流": "영구 삭제는 워크플로를 트리거하지 않습니다.",
