  "共导入%0张表，总计%1行数据": "총 %0개 테이블을 가져왔습니다. 총 %1개 행입니다.",
  "后恢复": "복구 후",
  "保存表格当前的列宽配置，并应用给所有用户": "현재 표의 열 너비 설정을 저장하고 모든 사용자에게 적용합니다.",
  "待办、通知发送方式": "할 일, 알림 발송 방식",
  "勾选时，自动匹配与表头行名称的一致的字段。取消勾选时，默认按照字段顺序依次匹配": "체크하면 표 헤더의 행 이름과 동일한 필드를 자동 매칭합니다. 체크 해제 시 필드 순서대로 매칭합니다.",
  "个节点未指定人员或人员异常": "일부 노드에 담당자가 지정되지 않았거나 담당자 정보에 문제가 있습니다.",
  "无数据或无权限查看": "데이터가 없거나 권한이 없습니다.",
  "审批、填写节点无需操作，将会自动通过。": "결재·작성 노드는 조치할 필요가 없습니다. 자동으로 승인됩니다.",
  "查找": "찾기",
  "60天内可在 回收站 内找回已删除%0，无编辑权限的数据无法删除。": "삭제된 %0는 60일 이내 휴지통에서 복구할 수 있습니다. 편집 권한이 없으면 데이터를 삭제할 수 없습니다.",
  "关联已有%0": "기존 %0 연결",
  "执行成功": "실행 완료",
  "选择群组": "그룹 선택",
  "当前工作表没有可以校准的字段。": "현재 워크시트에 보정할 수 있는 필드가 없습니다.",
  "本人": "본인",
  "6小时": "6시간",
  "流程撤回": "프로세스 제출 취소",
  "显示交替行颜色": "교차 행 색상 표시",
  "尺寸": "크기",
  "将所选节点的字段值结果立即返回给请求方，支持选择返回格式;请控制请求频率在500次/小时以内，流程执行时间30s以内，私有部署不限直接返回输出参数给请求地址": "선택한 노드의 필드 값 결과를 즉시 요청자에게 반환합니다. 반환 형식을 선택할 수 있습니다.\n요청 빈도를 시간당 500회 이하로 제한하세요. 워크플로 실행 시간은 30초 이내로 유지하세요. 프라이빗 배포는 제한 없음.\n출력 파라미터를 요청 주소로 바로 반환합니다.",
  "内部": "내부",
  "草稿箱中的数量已达到10条": "임시보관함에 10개의 초안이 있습니다.",
  "纯文本": "순수 텍스트",
  "解析失败，不是有效的应用文件": "분석에 실패했습니다. 유효한 애플리케이션 파일이 아닙니다.",
  "视图插件调试中，使用的是提交历史中的版本。": "보기 플러그인 디버깅 중에는 커밋 기록의 버전을 사용합니다.",
  "A4打印机": "A4 프린터",
  "全显示": "전체 표시",
  "索引名称": "인덱스 이름",
  "失败，所有记录都不满足执行条件，或流程尚未启用": "실패했습니다. 모든 레코드가 실행 조건을 만족하지 않거나 프로세스가 아직 활성화되지 않았습니다.",
  "按定位显示数据，区域分布更直观": "위치 기반으로 데이터를 표시해 영역 분포를 더 직관적으로 보여줍니다.",
  "高度不能小于%0": "높이는 %0보다 작을 수 없습니다.",
  "如果一些字段总是需要一起参与检索，它们组合起来之后的重复率更低，例如「First Name」和「Last Name」，那么你可以同时选择这两个字段创建一个复合索引，比为这两个字段分别创建索引效果更好。": "일부 필드는 항상 함께 검색되는 경우가 많습니다. 예를 들어 First Name과 Last Name처럼 함께 묶으면 중복률이 더 낮아집니다. 이런 경우 두 필드를 동시에 선택해 복합 인덱스를 생성하세요. 각 필드에 개별 인덱스를 만드는 것보다 더 효과적입니다.",
  "组织发布的": "조직에서 게시함",
  "仅在移动端隐藏": "모바일에서만 숨기기",
  "已选择%0条记录": "%0개의 레코드를 선택했습니다",
  "宽度不能小于%0": "너비는 %0보다 작을 수 없습니다.",
  "彻底删除所有%0行记录": "모든 %0개 행 레코드를 완전히 삭제합니다.",
  "批量操作 “": "일괄 작업",
  "数据不存在": "데이터가 없습니다.",
  "以图片为主要元素查看数据，浏览更高效": "이미지를 중심으로 데이터를 확인해 더 빠르게 탐색하세요.",
  "去集成中心创建": "연동 센터에서 생성",
  "有必填字段未填写": "필수 필드가 입력되지 않았습니다.",
  "文件已加密，需验证通过才能导入": "파일이 암호화되었습니다. 검증을 통과해야 가져올 수 있습니다.",
  "是否为%0开启审批功能项": "%0에 대해 결재 기능을 활성화할까요?",
  "创建自定义页面。自由配置页面按钮、统计图、嵌入链接等，减少繁琐操作，并快速掌握宏观数据情况。": "사용자 지정 페이지를 생성하세요. 페이지 버튼, 통계 차트, 임베드 링크 등을 자유롭게 구성해 번거로운 작업을 줄이고, 주요 지표를 빠르게 파악하세요.",
  "图标和颜色": "아이콘과 색상",
  "二维码设置": "QR 코드 설정",
  "无权限删除选择的记录": "선택한 레코드를 삭제할 권한이 없습니다.",
  "点击【发给我自己测试】时，实际执行人不收到消息，由我作为节点的执行人进行测试。": "[나에게 테스트 발송]을 클릭하면 실제 담당자에게는 메시지가 전송되지 않으며, 내가 해당 노드의 담당자로 테스트를 진행합니다.",
  "查看草稿箱": "초안함 보기",
  "你确定要取消关联吗？": "연결을 해제할까요?",
  "当看板滚动时，始终固定第1个看板在左侧，方便向其他看板中拖拽记录。": "칸반을 스크롤해도 1번째 칸반을 왼쪽에 고정하여 다른 칸반으로 레코드를 끌어다 놓기 쉽게 합니다.",
  "默认视图": "기본 보기",
  "直接返回固定文本给请求地址": "요청 주소로 고정 텍스트를 바로 반환합니다.",
  "保存导出配置": "내보내기 설정 저장",
