  "相同组不需要移动": "같은 그룹은 이동할 필요가 없습니다.",
  "将向对应的HTTP地址，以POST方式发送JSON格式数据": "해당 HTTP 주소로 POST 방식의 JSON 데이터를 전송합니다.",
  "这里是一个应用，你所有的业务数据、流程和用户都可以在这里进行管理。我们一起来看看一个应用是如何搭建和构成的吧！": "여기는 애플리케이션입니다. 모든 비즈니스 데이터, 프로세스, 사용자 관리를 한곳에서 할 수 있습니다. 함께 애플리케이션이 어떻게 구성되고 구축되는지 살펴봅시다!",
  "未设置流程的触发方式": "프로세스의 트리거 방식이 설정되지 않았습니다.",
  "代码片段名称": "코드 스니펫 이름",
  "回收站（应用）": "휴지통(애플리케이션)",
  "没有可选的应用": "선택할 수 있는 애플리케이션이 없습니다.",
  "当前版本单个sheet最多支持200列": "현재 버전에서는 시트당 최대 200열까지 지원합니다.",
  "○ 一张工作表只能创建一个「文本索引」或「所有文本字段全文索引」；": "워크시트 한 개당 ‘텍스트 인덱스’ 또는 ‘모든 텍스트 필드 전체 인덱스’ 중 하나만 생성할 수 있습니다.",
  "打印条形码": "바코드 인쇄",
  "的值": "값",
  "使用时清空现有input参数与代码块": "사용 시 기존 input 매개변수와 코드 블록 초기화",
  "暂时仅主流程中的节点支持此功能。引用的子流程、PBP中的节点仍为实际执行人，可单独去测试这些节点。": "현재는 메인 프로세스의 노드에서만 이 기능을 지원합니다. 참조된 하위 프로세스와 PBP의 노드는 여전히 실제 담당자로 처리되며, 해당 노드별로 개별 테스트할 수 있습니다.",
  "设置流程的运行方式，仅支持新增记录触发，自定义动作触发的流程": "프로세스 실행 방식을 설정합니다. 신규 레코드 트리거와 사용자 지정 액션 트리거만 지원합니다.",
  "启用按钮": "활성화 버튼",
  "加速导出": "내보내기 가속화",
  "您确认提交表单？": "양식을 제출할까요?",
  "将直接物理删除，永远无法恢复": "즉시 물리적으로 삭제되며 복구할 수 없습니다.",
  "请选择数据来源字段": "데이터 소스 필드를 선택하세요.",
  "修改保存": "수정 사항 저장",
  "只展示该发布版本的流程历史": "이 배포 버전의 프로세스 이력만 표시합니다.",
  "切换分隔符，仅针对新粘贴数据有效，已有数据不会产生影响”": "구분 기호를 변경합니다. 새로 붙여넣은 데이터에만 적용되며, 기존 데이터에는 영향을 주지 않습니다.",
  "自定义筛选": "사용자 지정 필터",
  "参数映射": "매개변수 매핑",
  "流程开始运行时生成，可以用以执行运算，或实现两个流程间的数据传递；命名时请以英文字母打头，名称中禁止出现汉字": "프로세스가 시작될 때 생성되며, 계산 수행이나 두 프로세스 간 데이터 전달에 사용할 수 있습니다. 이름은 영문자로 시작해야 하며, 한자는 사용할 수 없습니다.",
  "当前内容已失效": "현재 콘텐츠가 만료되었습니다.",
  "原负责人": "원래 책임자",
  "12小时": "12시간",
  "编辑按钮": "편집 버튼",
  "按字段原始值取所有小数位数，如：3.14159": "필드의 원본 값을 기준으로 모든 소수 자릿수를 가져옵니다. 예: 3.14159",
  "不导入此列": "이 열은 가져오지 않기",
  "通过批量编辑可快速统一修改相同字段的数据内容，无编辑权限的记录无法修改。": "일괄 편집으로 동일한 필드의 데이터 내용을 빠르게 일괄 변경할 수 있습니다. 편집 권한이 없는 레코드는 수정할 수 없습니다.",
  "添加新连接": "새 연결 추가",
  "删除失败请稍后再试": "삭제에 실패했습니다. 나중에 다시 시도하세요.",
  "示例：": "예시",
  "通过工作流，你可以将业务中的重复工作自动化执行，还可以发通知、短信，对接外部系统，彻底打通上下游业务。": "워크플로를 통해 반복 업무를 자동화하고, 알림과 문자 메시지를 발송하며, 외부 시스템과 연동해 상·하류 업무를 완전하게 연결할 수 있습니다.",
  "卡片设置": "카드 설정",
  "没有支持填写的字段": "작성할 수 있는 필드가 없습니다.",
