  "已执行": "실행됨",
  "可以使用 GET/POST 方式发送参数。当使用 POST 时，请求的主体必须是 JSON 格式，而且 HTTP header 的 Content-Type 需要设置为 application/json": "GET/POST 방식으로 파라미터를 보낼 수 있습니다. POST를 사용할 때는 요청 본문을 JSON 형식으로 보내야 하며, HTTP 헤더의 Content-Type을 application/json으로 설정하세요.",
  "重置后从%0开始编号": "재설정 후 %0부터 번호를 매깁니다.",
