  "选择一个代码块、发送API请求、JSON解析或调用已集成API节点，把它的返回数据对象立即返回给请求方；请控制请求频率在500次/小时以内，流程执行时间30s以内，私有部署不限": "코드 블록 선택, API 요청 전송, JSON 파싱 또는 연동된 API 노드 호출 중 하나를 선택해, 반환된 데이터 객체를 즉시 요청자에게 반환합니다. 요청 빈도는 시간당 500회 이내, 프로세스 실행 시간은 30초 이내로 제한됩니다. 프라이빗 배포는 제한 없음.",
