  "%0 于 %1 发起": "%1에서 %0가 시작됨",
  "冻结": "고정",
  "预览模式下，不能参与讨论": "미리보기 모드에서는 토론에 참여할 수 없습니다.",
  "设为隐藏后，普通用户在导航中将看不到此应用项入口，仅系统角色在导航中可见（包含管理员、开发者），应用项权限依然遵循角色权限原则。此配置通常用于不需要用户直接访问，仅作为配置用途的应用项，如：关联的明细表、参数表等。": "문구를 숨기면 일반 사용자는 내비게이션에서 해당 애플리케이션 항목 진입점을 볼 수 없고, 시스템 역할(관리자, 개발자)에만 표시됩니다. 애플리케이션 항목 권한은 여전히 역할 권한 원칙을 따릅니다. 이 설정은 사용자 직접 접근이 필요 없고 설정 용도로만 사용하는 애플리케이션 항목(예: 연동된 상세 테이블, 파라미터 테이블 등)에 주로 사용됩니다.",
