  "季度": "분기",
  "没有更多数据": "더 이상 데이터가 없습니다.",
  "删除成功，无编辑权限的记录无法删除": "삭제되었습니다. 편집 권한이 없는 레코드는 삭제할 수 없습니다.",
  "搜索应用名称/操作者": "애플리케이션 이름/작업자 검색",
  "密码必须包含数字或者字母": "비밀번호에는 숫자 또는 영문자가 포함되어야 합니다.",
  "数据各自同步执行，适合运行实例间互不影响的流程。执行速度快，适合大多数流程使用": "데이터를 각각 동기화 실행하여 인스턴스 간에 서로 영향을 주지 않는 프로세스에 적합합니다. 실행 속도가 빨라 대부분의 프로세스에 적합합니다.",
