  "结构化展示大量数据，编辑更方便": "대량 데이터를 구조적으로 표시하여 편집을 더 쉽게 합니다.",
  "每张工作表只能创建一个「文本索引」或者「文本字段全文索引」；创建「文本索引」时，不能包含「选项字段」；每个索引只能包含一个「选项字段」": "각 워크시트에는 ‘텍스트 인덱스’ 또는 ‘텍스트 필드 전체 인덱스’ 중 하나만 생성할 수 있습니다. ‘텍스트 인덱스’를 생성할 때는 ‘옵션 필드’를 포함할 수 없습니다. 각 인덱스에는 ‘옵션 필드’를 하나만 포함할 수 있습니다.",
