  "此时对方请求时必须附带参数callbackURL，我方流程运行结束后会向此URL传递输出参数": "이 시점에는 상대 측 요청에 반드시 callbackURL 파라미터가 포함되어야 합니다. 우리 쪽 프로세스가 완료되면 이 URL로 출력 파라미터를 전달합니다.",
