  "文件夹名和附件名的最大长度为90个汉字。超限的文件不会被导出。": "폴더 이름과 첨부 파일 이름의 최대 길이는 한자 90자입니다. 길이를 초과한 파일은 내보내지 않습니다.",
  "值为空": "값이 비어 있습니다.",
  "为你的应用添加用户。你可以创建角色来管理用户权限，一条数据，谁能查看，谁能修改，谁能删除，都能自由设定。": "애플리케이션에 사용자를 추가하세요. 역할을 생성해 사용자 권한을 관리할 수 있습니다. 각 데이터에 대해 누가 조회하고, 누가 수정하며, 누가 삭제할 수 있는지 자유롭게 설정하세요.",
  "数据为空，暂不支持导出！": "데이터가 없어 내보내기를 지원하지 않습니다.",
  "关联表：显示方式为卡片或下拉框": "연결된 테이블: 표시 방식은 카드 또는 드롭다운",
