  "你确定重置显示列吗？": "표시 열을 초기화할까요?",
  "仅限应用内成员登录系统后根据权限访问": "애플리케이션 내부 구성원만 로그인 후 권한에 따라 접근할 수 있습니다.",
  "导出以下字段时，将使用冗余值，可能会导出旧数据：": "다음 필드를 내보낼 때 중복 값을 사용하므로, 이전 데이터가 내보내질 수 있습니다.",
