  "点击确定后，将会立即开始执行此流程": "확인을 클릭하면 즉시 이 프로세스가 실행됩니다.",
  "字段名": "필드명",
  "如何利用索引加速检索？": "인덱스로 검색 속도를 높이려면 어떻게 하나요?",
  "文件解析失败！": "파일을 해석하지 못했습니다!",
