  "当前节点未进行操作的成员将设为提交": "현재 노드에서 작업하지 않은 멤버는 제출 상태로 처리됩니다.",
  "立即导出": "지금 내보내기",
  "刷新选项排序和分值": "옵션 정렬과 점수 새로고침",
  "插件设置": "플러그인 설정",
  "通知节点设置": "알림 노드 설정",
  "是的，我们会根据公有云平台每天的访问日志，自动学习和智能分析被频繁使用的查询语句，并自动创建合适的索引。所以，请不要随意修改和删除不是由你自己创建的索引。私有部署环境暂不支持自动创建索引。": "네. 공용 클라우드 플랫폼의 일일 액세스 로그를 바탕으로, 자주 사용되는 쿼리를 자동 학습·지능 분석하여 적합한 인덱스를 자동 생성합니다. 따라서 본인이 생성하지 않은 인덱스는 임의로 수정하거나 삭제하지 마세요. 프라이빗 배포 환경에서는 자동 인덱스 생성이 아직 지원되지 않습니다.",
  "插件 “%0” 存在错误！": "플러그인 “%0”에 오류가 있습니다!",
  "你可以根据业务数据自定义工作表字段，并建立数据关联。": "업무 데이터에 맞춰 워크시트 필드를 사용자 지정하고 데이터 연관을 설정할 수 있습니다.",
  "已选择%0条草稿": "%0개 초안 선택됨",
  "添加视图": "보기 추가",
  "为工作表建立索引，就像是为一本字典建立一个可以用拼音检索的目录。创建适合的索引可以非常有效的加快特定查询条件下的记录检索速度。在创建索引之前，你需要了解创建索引的一些基本原则。": "워크시트에 인덱스를 생성하는 것은, 한 권의 사전에 음가로 찾을 수 있는 목차를 만드는 것과 같습니다. 적절한 인덱스를 만들면 특정 조회 조건에서 레코드 검색 속도를 크게 높일 수 있습니다. 인덱스를 생성하기 전에 몇 가지 기본 원칙을 먼저 이해하세요.",
  "视图配置错误,请联系管理员": "보기 설정에 오류가 발생했습니다. 관리자에게 문의하세요.",
  "找不到分组": "그룹을 찾을 수 없습니다.",
  "执行此操作后，流程将回滚到当前版本。您未发布的流程修改将会被清除，此操作无法撤回": "이 작업을 수행하면 프로세스가 현재 버전으로 롤백됩니다. 게시하지 않은 프로세스 변경 사항은 모두 삭제되며, 이 작업은 되돌릴 수 없습니다.",
  "索引字段的排序和你在视图中使用此字段参与排序的规则有关。当索引只有一个字段时，视图中排序的方向不会影响检索的加速；除此之外，请尽量保证在视图中的字段排序方式与索引中设置的一致，否则检索可能不会被加速。": "인덱스 필드의 정렬은 보기에서 해당 필드를 정렬에 사용하는 방식과 관련됩니다. 인덱스가 단일 필드만 포함할 경우, 보기의 정렬 방향은 검색 가속에 영향을 주지 않습니다. 그 외에는 보기에서의 필드 정렬 방식이 인덱스에 설정된 방식과 일치하도록 하세요. 일치하지 않으면 검색이 가속되지 않을 수 있습니다.",
  "触发Webhook": "웹훅 트리거",
  "详细地址": "상세 주소",
  "未设置触发方式的工作流将不会被保存": "트리거 방식이 설정되지 않은 워크플로는 저장되지 않습니다.",
  "插件开发中": "플러그인 개발 중",
