  "选择索引字段时请记住一个原则：记录中重复值越少的字段，越适合建立索引。例如一个不允许重复的「商品编号」字段，就非常适合创建索引；反之，一个用于记录男、女的「性别」字段，则不适合创建索引。": "인덱스 필드를 선택할 때는 한 가지 원칙을 기억하세요. 레코드에서 중복 값이 적은 필드일수록 인덱스에 적합합니다. 예를 들어 중복을 허용하지 않는 ‘상품 번호’ 필드는 인덱스 생성에 매우 적합합니다. 반대로 남·녀를 기록하는 ‘성별’ 필드는 인덱스 생성에 적합하지 않습니다.",
  "选择一组一对多关系的关联本表的“关联表”字段，数据将按照此字段的父级（单条）、子级（多条）关系来从左往右排列构成树状层级": "본 테이블과 1:N 관계로 연동된 ‘연동 테이블’ 필드를 선택하세요. 데이터는 해당 필드의 상위(단일)–하위(다중) 관계에 따라 왼쪽에서 오른쪽으로 배열되어 트리 형태의 계층을 이룹니다.",
  "当前尺寸下最大容纳%0行文字，字段内容超过1行后，默认向下换行直到完整显示。": "현재 크기에서 최대 %0행의 텍스트를 표시합니다. 필드 내용이 1행을 초과하면 완전히 보일 때까지 기본적으로 줄바꿈됩니다.",
