  "移动到自定义页面": "사용자 지정 페이지로 이동",
  "用户扩展信息表非常类似于组织中的用户管理表。在组织中，可以全局管理成员基础信息，如：部门、职位、组织角色等。其中部门、组织角色可用于数据权限范围，在工作表添加部门字段，可以使用户对自己所在部门的记录都拥有权限。同样在具体应用中，往往也需要额外管理用户在本应用中的扩展信息。如：销售管理应用中，需要管理销售人员所在的团队、区域、职能等，同时也希望这些信息可以类似部门一样用于数据权限范围。此时就可以建立一张销售人员表。": "사용자 확장 정보 표는 조직의 사용자 관리 표와 매우 유사합니다. 조직에서는 부서, 직위, 조직 역할 등 구성원의 기본 정보를 전역으로 관리할 수 있습니다. 이 중 부서와 조직 역할은 데이터 권한 범위에 활용할 수 있으며, 워크시트에 부서 필드를 추가하면 사용자가 자신이 속한 부서의 레코드에 권한을 가질 수 있습니다. 마찬가지로 개별 애플리케이션 내에서도 해당 애플리케이션에서의 사용자 확장 정보를 추가로 관리해야 하는 경우가 많습니다. 예를 들어 영업 관리 애플리케이션에서는 영업 사원이 속한 팀, 지역, 직무 등을 관리하고, 이러한 정보도 부서처럼 데이터 권한 범위에 활용하길 원할 수 있습니다. 이때 영업 사원 표를 생성하면 됩니다.",
