  "如：还是在销售管理应用中，用户扩展信息表中已设置了团队作为用户权限标签（关联团队表），并且订单表也关联了所属团队时。那么当用户访问应用时，系统就可以根据读取到的用户所在团队，并从订单表中过滤出关联了相同团队的订单，从而实现用户对属于自己团队的订单拥有查看、编辑或删除权限（可以在角色权限中进行设置）。": "예를 들어 판매 관리 애플리케이션에서 사용자 확장 정보 워크시트에 팀을 사용자 권한 태그로 설정하고(팀 워크시트와 연동), 주문 워크시트에도 소속 팀을 연동해 두었다면, 사용자가 애플리케이션에 접속할 때 시스템이 사용자의 소속 팀을 확인하고 주문 워크시트에서 같은 팀과 연동된 주문만 필터링합니다. 이렇게 하면 사용자는 본인 팀에 속한 주문에 대해 보기, 편집 또는 삭제 권한을 가질 수 있습니다(역할 권한에서 설정 가능).",
