  "7.明道云用户必须防范和抵制制作、复制、发布含有下列内容的不良信息：使用夸张标题，内容与标题严重不符的；炒作绯闻、丑闻、劣迹等的；不当评述自然灾害、重大事故等灾难的；带有性暗示、性挑逗等易使人产生性联想的；展现血腥、惊悚、残忍等致人身心不适的；煽动人群歧视、地域歧视等的；宣扬低俗、庸俗、媚俗内容的；可能引发未成年人模仿不安全行为和违反社会公德行为、诱导未成年人不良嗜好等的；其他对网络生态造成不良影响的内容。": "7. Mingdao Cloud 사용자는 다음과 같은 콘텐츠를 제작·복제·게시하는 불량 정보의 생성과 유포를 방지하고 거부해야 합니다: 과장된 제목을 사용해 내용과 심각하게 불일치하는 경우, 스캔들·추문·불미사건 등을 부각해 조작하는 경우, 자연재해·중대 사고 등 재난을 부적절하게 평하는 경우, 성적 암시·도발 등 성적 연상을 유발하는 경우, 혈흔·공포·잔혹 등 신체·정신적 불쾌감을 유발하는 표현, 인종·지역 등 차별을 선동하는 내용, 저속·통속·상업적 저질 취향을 조장하는 내용, 미성년자의 위험한 모방 행동이나 사회적 도덕에 반하는 행동을 유발하거나 미성년자의 바람직하지 않은 기호를 유도하는 내용, 그 밖에 네트워크 생태계에 악영향을 미치는 내용.",
