  "记录操作": "레코드 작업",
  "8.明道云账户一旦被注销将不可恢复，请明道云用户在操作之前自行备份账户相关的所有信息和数据。注销明道云账户，明道云用户将无法再使用本明道云账户，也将无法找回用户的明道云账户中及与账户相关的任何内容或信息（即使使用相同的手机号码再次注册并使用明道云软件），包括但不限于：": "8. Mingdao 계정을 한 번 삭제하면 복구할 수 없습니다. 진행 전에 계정 관련 모든 정보와 데이터를 직접 백업하세요.\nMingdao 계정을 삭제하면 더 이상 해당 계정을 사용할 수 없으며, 계정 내 및 계정과 관련된 모든 콘텐츠 또는 정보를 복구할 수 없습니다(동일한 휴대폰 번호로 다시 가입해도 마찬가지). 포함하되 이에 제한되지 않음:",
