  "集成%01002": "연동",
  "如果就本协议的解释或执行发生争议，双方应首先力争通过友好协商解决该争议。如果在一方向其他方送达要求开始协商的书面通知后六十天内未能通过协商解决争议，那么任何一方均可将争议提交至中国国际经济贸易仲裁委员会上海分会，按照其届时有效的规则进行仲裁。仲裁裁决是终局的，对各方均有约束力，不可上诉。仲裁费用由败诉方承担，除非仲裁裁决另有规定。当任何争议发生时以及在对任何争议进行仲裁时，除争议事项外，各方应继续行使各自在本协议项下的其他权利，履行各自在本协议项下的其他义务。": "본 계약의 해석 또는 이행과 관련하여 분쟁이 발생할 경우, 당사자들은 우선 우호적인 협의를 통해 분쟁 해결을 위해 노력해야 합니다. 일방 당사자가 다른 당사자에게 협의 개시를 요구하는 서면 통지를 발송한 날로부터 60일 이내에 협의로 분쟁이 해결되지 않을 경우, 어느 당사자든 당시 유효한 규정에 따라 분쟁을 중국국제경제무역중재위원회 상하이 분회에 회부하여 중재를 신청할 수 있습니다. 중재 판정은 최종적이며, 각 당사자를 구속하고, 불복 신청이 불가합니다. 중재 비용은 중재 판정에 달리 정함이 없는 한 패소 당사자가 부담합니다. 어떠한 분쟁이 발생하더라도, 그리고 분쟁에 대한 중재가 진행되는 동안에도, 분쟁 사항을 제외한 부분에 관해서는 각 당사자는 본 계약에 따른 기타 권리를 계속 행사하고 기타 의무를 계속 이행해야 합니다.",
  "统计范围": "통계 범위",
