  "3.在发生需要从备份文件中恢复数据的情形时，明道云通常需要4小时，最长48小时完成，在此时间范围内的数据恢复视作服务是连续的。": "3. 백업 파일에서 데이터를 복구해야 하는 경우, Mingdao Cloud는 일반적으로 4시간, 최대 48시간 내에 완료합니다. 이 시간 내 복구는 서비스 연속으로 간주됩니다.",
  "支持 jpg、jpeg、png、gif格式，2MB以内": "jpg, jpeg, png, gif 형식 지원, 2MB 이하",
  "1.明道云将尽最大努力保障软件平台的连续可靠运行，对付费版用户，明道云承诺99%以上的正常在线率，低于此比例，明道云有义务按照服务中断时间比例向客户退还相应的服务费用，客户理解该等赔偿。明道云对免费模式用户不提供任何补偿。": "Mingdao Yun은 소프트웨어 플랫폼의 연속적이고 안정적인 운영을 위해 최선을 다합니다. 유료 버전 사용자에 대해 Mingdao Yun은 99% 이상의 정상 가동률을 보장하며, 이 비율을 밑돌 경우 서비스 중단 시간 비율에 따라 해당 서비스 요금을 고객에게 환불할 의무가 있습니다. 고객은 이러한 보상을 이해합니다. 무료 모드 사용자에게는 어떠한 보상도 제공되지 않습니다.",
  "知识中心": "지식 센터",
  "4.本使用协议依据国家相关法律法规规章制定，明道云用户同意严格遵守以下义务：（1）不得利用明道云产品从事洗钱、窃取商业秘密、窃取个人信息等违法犯罪活动；（2）不得干扰明道云产品的正常运转，不得明道云产品及国家计算机信息系统；（3）不得传输或发表任何违法犯罪的、骚扰性的、中伤他人的、辱骂性的、恐吓性的、伤害性的、庸俗的、不文明的等信息；（4）不得教唆他人从事违法违规或本使用协议所禁止的行为；（5）不得利用在明道云注册的账户买卖进行牟利性经营活动；（6）不得发布任何侵犯他人个人信息、著作权、商标权等知识产权或合法权利的内容；": "4. 본 이용 약관은 관련 법령과 규정에 따라 제정되었으며, Mingdao Cloud 사용자 는 다음 의무를 엄격히 준수해야 합니다.\n(1) Mingdao Cloud 제품을 이용해 자금 세탁, 영업비밀 절취, 개인정보 절취 등 불법 범죄 행위를 해서는 안 됩니다.\n(2) Mingdao Cloud 제품의 정상적인 운영을 방해하거나, Mingdao Cloud 제품 및 국가 컴퓨터 정보 시스템을 침해해서는 안 됩니다.\n(3) 불법·범죄, 괴롭힘, 중상모략, 모욕, 협박, 폭력·상해, 저속, 비문명적 등의 정보를 전송하거나 게시해서는 안 됩니다.\n(4) 타인을 불법·위반 행위 또는 본 이용 약관에서 금지하는 행위로 교사해서는 안 됩니다.\n(5) Mingdao Cloud에 등록한 계정을 매매하거나 이를 통해 영리 목적의 영업 활동을 해서는 안 됩니다.\n(6) 타인의 개인정보, 저작권, 상표권 등 지식재산권 또는 합법적 권리를 침해하는 내용을 게시해서는 안 됩니다.",
  "购买年限": "구매 기간",
  "隐私": "개인정보",
  "解绑失败，账号不存在": "연결 해제에 실패했습니다. 계정이 존재하지 않습니다.",
  "生成密钥": "키 생성",
  "飞书登录": "Feishu 로그인",
  "5.在法律允许的范围内，明道云对因：（1）明道云产品受到计算机病毒、木马或其他恶意程序、黑客攻击的破坏；（2）明道云用户操作不当或用户通过非明道云授权的方式使用本服务；（3）程序版本过时、设备的老化和/或其兼容性问题；（4）其他明道云无法控制或合理预见的情形，导致的明道云服务中断或终止，不承担赔偿责任。": "5. 법이 허용하는 범위 내에서, 다음 사유로 인해 Mingdao Cloud 서비스가 중단되거나 종료되는 경우 Mingdao Cloud는 손해배상 책임을 지지 않습니다: (1) Mingdao Cloud 제품이 컴퓨터 바이러스, 트로이 목마 또는 기타 악성 프로그램, 해커 공격으로 인해 손상된 경우; (2) Mingdao Cloud 사용자의 부적절한 조작 또는 사용자가 Mingdao Cloud의 승인 없이 본 서비스를 이용한 경우; (3) 프로그램 버전 노후, 장비의 노후 및/또는 호환성 문제; (4) 그 외 Mingdao Cloud가 통제하거나 합리적으로 예견할 수 없는 상황.",
  "添加记录成功！": "레코드가 추가되었습니다!",
  "Welink": "Welink",
  "1.本协议是明道云用户（包括使用的个人和代表的企业）与明道云运营企业上海万企明道软件有限公司之间的协议，用户注册明道云服务即代表接受本协议的约束，并自注册成功之时即成为本协议一方，付费版用户签署本协议并回传（包括使用传真，电子邮件等电子通信手段）给明道云即代表接受本协议中的计费和支付协议，并自发出协议之时即受该等协议约束。": "1. 본 계약은 Mingdao Cloud 사용자(개인을 포함하며, 기업을 대리하는 경우를 포함)와 Mingdao Cloud 운영사인 上海万企明道软件有限公司 간의 계약입니다. 사용자가 Mingdao Cloud 서비스에 등록하면 본 계약에 동의한 것으로 간주되며, 등록이 완료된 시점부터 본 계약의 당사자가 됩니다. 유료 버전 사용자가 본 계약에 서명하고 Mingdao Cloud에 회신(팩스, 이메일 등 전자 통신 수단 포함)하면 본 계약의 요금 및 결제 조건에 동의한 것으로 간주되며, 발송 시점부터 해당 조건의 적용을 받습니다.",
  "绑定": "연결",
