  "新建": "신규 생성",
  "下文中的“明道云”指应用平台“明道云”（包括但不限于明道云网页、明道云App以及明道云微信小程序）或其运营企业上海万企明道软件有限公司，也是本协议的契约方之一。": "아래 문구에서의 ‘明道云’은 애플리케이션 플랫폼 ‘明道云’(明道云 웹, 明道云 앱, 明道云 WeChat 미니 프로그램을 포함하되 이에 한정하지 않음) 또는 그 운영사인 上海万企明道软件有限公司을 의미하며, 본 계약의 당사자 중 하나입니다.",
  "2.明道云使用客户所拥有的手机号作为用户权证的唯一识别信息。当客户不再拥有在明道云登记的手机号时，明道云有权终止提供服务，客户亦可以通过变更手机号的方式继续使用明道云服务。在付费版下，系统支持多个域名电子邮件地址，当最早登记的主域名权属发生改变时，明道云有权终止提供服务。": "2. Mingdao Cloud는 고객이 보유한 휴대폰 번호를 사용자 자격 증명의 유일한 식별 정보로 사용합니다. 고객이 더 이상 Mingdao Cloud에 등록된 휴대폰 번호를 보유하지 않을 경우, Mingdao Cloud는 서비스 제공을 중단할 수 있으며, 고객은 휴대폰 번호를 변경하여 서비스를 계속 이용할 수 있습니다. 유료 버전에서는 시스템이 여러 도메인 이메일 주소를 지원하며, 최초로 등록된 기본 도메인의 소유권이 변경될 경우 Mingdao Cloud는 서비스 제공을 중단할 수 있습니다.",
