  "1.明道云有权随时对本协议的协议进行修订，并在修订生效日前一个工作日更新在明道云网站。": "Mingdao Cloud는 본 계약을 언제든지 수정할 수 있으며, 수정 사항은 발효일 전 영업일 1일 전에 Mingdao Cloud 웹사이트에 업데이트됩니다.",
  "免费 %0 人": "무료 %0명",
  "2.明道云将尽最大努力保障客户数据的安全备份，对付费版用户，明道云承诺在有任何用户数据因服务器存储设备损坏时以最快的速度从最近的备份中恢复数据，但无法承诺100%的数据恢复，对因数据丢失带来的其他连带或间接损失不承担任何责任。": "2. Mingdao Cloud는 고객 데이터의 안전한 백업을 위해 최선을 다합니다. 유료 버전 사용자에 대해서는 서버 저장 장치 손상으로 사용자 데이터가 유실된 경우, 가장 최근 백업에서 가능한 한 신속히 데이터를 복구할 것을 약속합니다. 다만 데이터의 100% 복구는 보장하지 않으며, 데이터 유실로 인한 기타 연대 또는 간접 손해에 대해서는 어떠한 책임도 지지 않습니다.",
