  "明道顾问为您按需搭建业务定制应用包。包括销售、营销、生成、研发、运营等业务环节。": "Mingdao 컨설턴트가 요구에 맞춰 비즈니스 맞춤 애플리케이션 패키지를 구축합니다. 영업, 마케팅, 생산, R&D, 운영 등 전 과정이 포함됩니다.",
  "3.明道云用户应当对其明道云账户下的一切行为负责，包括发布的任何内容以及由此产生的任何后果。明道云不对用户使用明道云服务而上传、存储或共享的内容承担任何责任。": "3. Mingdao Cloud 사용자는 자신의 Mingdao Cloud 계정에서 이루어지는 모든 행위에 대해 책임을 집니다. 게시한 모든 콘텐츠와 그로 인한 결과를 포함합니다. Mingdao Cloud는 사용자가 Mingdao Cloud 서비스를 이용하여 업로드, 저장 또는 공유한 콘텐츠에 대해 어떠한 책임도 지지 않습니다.",
  "3)通过明道云账号进行登录的明道云旗下APP（包括但不限于明道云APP等）所有记录都将无法找回。无法再登录、使用前述服务，曾获得的SaaS服务、外部用户包、工作流执行行数付费包、应用附件上传量扩充包等视为自行放弃，将无法继续使用。明道云用户应当理解并同意，明道云无法协助重新恢复前述服务。": "3) Mingdao Cloud 계정으로 로그인해 사용하던 Mingdao Cloud 산하 APP(예: Mingdao Cloud APP 등 포함)에 저장된 모든 레코드는 복구할 수 없습니다. 이후에는 로그인 및 해당 서비스 이용이 불가하며, 기존에 제공되었던 SaaS 서비스, 외부 사용자 패키지, 워크플로 실행 건수 유료 패키지, 애플리케이션 첨부 파일 업로드량 확장 패키지 등은 자진 포기한 것으로 간주되어 더 이상 사용할 수 없습니다. Mingdao Cloud 사용자는 Mingdao Cloud가 상기 서비스의 복구를 지원할 수 없음을 이해하고 동의해야 합니다.",
