  "2.明道云账号的所有权及相关权益属于明道云所有，明道云用户不得以任何方式转让或向提供他人使用其使用的明道云账号，否则明道云有权立即不经通知收回该账号，由此带来的因明道云用户使用明道云产品产生的全部数据、信息等被清空、丢失等损失，明道云用户应自行承担。": "2. Mingdao Cloud 계정의 소유권과 관련 권리는 Mingdao Cloud에 귀속됩니다. 사용자는 자신의 Mingdao Cloud 계정을 어떤 방식으로도 양도하거나 타인에게 사용하게 해서는 안 됩니다. 이를 위반할 경우 Mingdao Cloud는 별도 통지 없이 즉시 해당 계정을 회수할 수 있으며, 이에 따라 해당 사용자가 Mingdao Cloud 제품을 사용하면서 생성된 모든 데이터와 정보가 삭제되거나 손실될 수 있습니다. 이러한 손실에 대한 책임은 사용자에게 있습니다.",
