  "3.请您务必审慎阅读、充分理解各协议内容，特别是免除或者限制责任的协议、争议解决和法律适用协议。免除或者限制责任的协议可能将以加粗字体显示，您应重点阅读。": "3. 각 약관을 신중히 읽고 충분히 이해하세요. 특히 면책 또는 책임 제한 조항, 분쟁 해결 및 준거법 관련 조항을 확인하세요. 면책 또는 책임 제한 조항은 굵게 표시될 수 있으니 반드시 집중해서 읽으세요.",
