  "应用备份/还原": "애플리케이션 백업/복원",
  "本合约是明道云用户与明道云授权销售方之间的法律契约，高级模式（标准版、专业版、旗舰版都属于高级模式）用户签署本合约并回传（包括使用传真，电子邮件等电子通信手段）给明道云授权销售方即代表接受本合约中的计费和支付条款，并自发出合约之时即受该等条款约束。": "본 계약은 Mingdao Cloud 사용자와 Mingdao Cloud 권한 판매자 간의 법적 계약입니다. 고급 모드(스탠다드, 프로, 플래그십 포함) 사용자가 본 계약에 서명하고 팩스, 이메일 등 전자 통신 수단으로 Mingdao Cloud 권한 판매자에게 회신하면, 본 계약의 요금 및 결제 조건을 수락한 것으로 간주되며, 계약 발송 시점부터 해당 조건이 적용됩니다.",
  "选择已提交的代码进行发布。发布后，组织内的所有应用均可安装使用该代码插件。": "제출된 코드를 선택해 배포하세요. 배포 후 조직 내 모든 애플리케이션에서 해당 코드 플러그인을 설치해 사용할 수 있습니다.",
  "应用授权密钥是极为重要的凭证，关闭时需要验证身份": "애플리케이션 권한 부여 키는 매우 중요한 자격 증명입니다. 끌 때 신원 확인이 필요합니다.",
  "是否升序（false：降序）": "오름차순 여부( false: 내림차순 )",
