  "网络ID": "네트워크 ID",
  "输入参数用于在工作表或工作流中使用 API 查询时，可以传入动态值": "입력 매개변수는 워크시트 또는 워크플로에서 API 쿼리를 사용할 때 동적 값을 전달하는 데 사용됩니다.",
