  "应用定制服务交付验收后，甲方应当在乙方提供的应用定制服务交付通知书签字确认，作为服务交付的依据。甲方在收到交付通知书后7日内无异议的，则认为甲方已经确认服务交付完成。": "애플리케이션 맞춤형 서비스의 납품 검수 후, 갑은 을이 제공한 애플리케이션 맞춤형 서비스 납품 통지서에 서명하여 납품 근거로 확인해야 합니다. 갑이 통지서를 수령한 후 7일 이내 이의가 없으면, 서비스 납품이 완료된 것으로 간주합니다.",
