  "1.明道云应当从组织结构和技术角度尽最大努力保护用户数据安全，只根据用户在网站上的行为指示来分发用户的信息。明道云永远不会将用户产生的具体数据提供给任何无关第三方。": "Mingdao Cloud는 조직 구조와 기술 측면에서 사용자 데이터 보안을 최우선으로 보호하기 위해 최선을 다하며, 웹사이트에서의 사용자 행동 지시에 따라서만 사용자 정보를 배포합니다. 또한 사용자 생성 데이터의 구체적인 내용은 어떤 무관한 제3자에게도 절대 제공하지 않습니다.",
