  "6.明道云用户不得制作、传输或发表以下违法信息：反对宪法所确定的基本原则的；危害国家安全，泄露国家秘密，颠覆国家政权，破坏国家统一的；损害国家荣誉和利益的；歪曲、丑化、亵渎、否定英雄烈士事迹和精神，以侮辱、诽谤或者其他方式侵害英雄烈士的姓名、肖像、名誉、荣誉的；宣扬恐怖主义、极端主义或者煽动实施恐怖活动、极端主义活动的；煽动民族仇恨、民族歧视，破坏民族团结的；破坏国家宗教政策，宣扬邪教和封建迷信的；散布谣言，扰乱经济秩序和社会秩序的；散布淫秽、色情、赌博、暴力、凶杀、恐怖或者教唆犯罪的；侮辱或者诽谤他人，侵害他人名誉、隐私和其他合法权益的；法律、行政法规禁止的其他内容。": "6. Mingdao Cloud 사용자는 다음과 같은 불법 정보의 제작, 전송 또는 게시를 해서는 안 됩니다: 헌법이 정한 기본 원칙에 반하는 내용; 국가 안보를 해치거나, 국가 기밀을 누설하거나, 국가 정권을 전복하거나, 국가 통일을 파괴하는 내용; 국가의 명예와 이익을 손상시키는 내용; 영웅·열사의 사적과 정신을 왜곡·비하·모독·부정하거나, 모욕·명예훼손 등으로 영웅·열사의 성명, 초상, 명예, 영예를 침해하는 내용; 테러리즘·극단주의를 선전하거나 테러·극단주의 활동을 선동하는 내용; 민족 증오·차별을 선동하거나 민족 단결을 해치는 내용; 국가의 종교 정책을 파괴하거나 사이비 종교와 봉건 미신을 선전하는 내용; 유언비어를 유포하여 경제·사회 질서를 교란하는 내용; 음란물, 포르노, 도박, 폭력, 살인, 테러 또는 범죄를 교사하는 내용; 타인을 모욕하거나 비방하여 타인의 명예, 사생활 및 기타 합법적 권익을 침해하는 내용; 그 밖에 법률 및 행정 법규에서 금지하는 내용.",
