  "5.除非法律允许或本公司书面许可，使用明道云产品过程中不得从事下列行为：（1）删除明道云产品及其副本上关于著作权的信息；（2）对明道云产品进行反向工程、反向汇编、反向编译，或者以其他方式尝试发现明道云产品的源代码；（3）对明道云拥有知识产权的内容进行使用、出租、出借、复制、修改、链接、转载、汇编、发表、出版、建立镜像站点等；（4）对明道云产品或其运行过程中释放到任何终端内存中的数据、运行过程中客户端与服务器端的交互数据，以及明道云产品运行所必需的系统数据，进行复制、修改、增加、删除、挂接运行或创作任何衍生作品，形式包括但不限于使用插件、外挂或非经明道云授权的第三方工具/服务接入明道云产品和相关系统；（5）通过修改或伪造明道云产品运行中的指令、数据，增加、删减、变动明道云产品的功能或运行效果，或者将用于上述用途的软件、方法进行运营或向公众传播，无论这些行为是否为商业目的；（6）通过非明道云开发、授权的第三方软件、插件、外挂、系统，登录或使用明道云产品及服务，或制作、发布、传播上述工具；（7）自行或者授权他人、第三方软件对明道云产品及其组件、模块、数据进行干扰。": "5. 법률에 의해 허용되거나 당사의 서면 허가가 없는 한, Mingdao Cloud 제품 사용 중 다음 행위를 해서는 안 됩니다.\n(1) Mingdao Cloud 제품 및 그 복제본에 표시된 저작권 관련 정보를 삭제하는 행위\n(2) Mingdao Cloud 제품에 대해 리버스 엔지니어링, 리버스 어셈블리, 리버스 컴파일을 하거나, 기타 방법으로 소스 코드를 탐지·확인하려는 시도\n(3) Mingdao Cloud가 지식재산권을 보유한 콘텐츠를 사용, 임대, 대여, 복제, 수정, 링크, 전재, 편집, 게시, 출판하거나 미러 사이트를 구축하는 행위\n(4) Mingdao Cloud 제품 또는 그 실행 과정에서 어떤 단말 메모리에 로드되는 데이터, 실행 중 클라이언트와 서버 간의 통신 데이터, 제품 실행에 필수적인 시스템 데이터를 복제·수정·추가·삭제·후킹 실행하거나, 플러그인, 외掛 또는 Mingdao Cloud의 허가를 받지 않은 제3자 도구/서비스를 통해 Mingdao Cloud 제품 및 관련 시스템에 접속하는 등 어떠한 형태로든 파생 저작물을 제작하는 행위\n(5) Mingdao Cloud 제품 실행 중의 명령·데이터를 변경하거나 위조하여 제품의 기능 또는 동작 효과를 추가·삭제·변경하는 행위, 혹은 위 목적에 사용되는 소프트웨어나 방법을 운영하거나 대중에 배포하는 행위(영리 목적 여부와 무관)\n(6) Mingdao Cloud가 개발·허가하지 않은 제3자 소프트웨어, 플러그인, 외掛, 시스템을 통해 Mingdao Cloud 제품 및 서비스를 로그인 또는 사용하거나, 위 도구를 제작·배포·전파하는 행위\n(7) 자체적으로 또는 타인이나 제3자 소프트웨어에 권한을 부여하여 Mingdao Cloud 제품 및 그 컴포넌트, 모듈, 데이터에 간섭하는 행위.",
