  "2.客户应当按照本订单载明的支付义务及时支付价款，用户逾期支付账单超过30天后系统会停止付费版服务，而转入免费模式，用户在付费版下的设定参数数据可能因此丢失或恢复缺省设置。即使在停止付费版服务后，任何未支付的账单均会作为客户的欠款，明道云保留追讨欠款及滞纳金的权利，滞纳金将根据拖欠天数，每天按欠款金额的万分之五计收。": "2. 고객은 본 주문서에 명시된 결제 의무에 따라 대금을 기한 내 지급해야 합니다. 청구서 결제가 30일을 초과해 연체되면 유료 서비스가 중단되고 무료 모드로 전환됩니다. 이 경우 유료 버전에서 설정한 파라미터와 데이터가 삭제되거나 기본값으로 복원될 수 있습니다. 유료 서비스가 중단된 이후에도 미지급 청구서는 고객의 미납금으로 간주되며, 명도우는 미납금 및 연체료를 청구할 권리를 보유합니다. 연체료는 연체 일수에 따라 매일 미납금의 0.05%로 부과됩니다.",
  "为您的成员安装App（支持IOS或者Andriod)": "구성원을 위해 앱 설치(IOS 또는 Android 지원)",
  "根据字段名的拼音自动生成别名，若字段名为英文则直接取字段名作为别名，此操作不会影响已设置的别名。": "필드 이름의 병음을 기준으로 별칭을 자동 생성합니다. 필드 이름이 영어인 경우 해당 필드 이름을 그대로 별칭으로 사용합니다. 이 작업은 이미 설정된 별칭에 영향을 주지 않습니다.",
  "完整显示": "전체 표시",
  "ETL:可以在数据同步的过程中对数据进行处理": "ETL: 데이터 동기화 과정에서 데이터를 처리할 수 있습니다.",
