  "管理所有数据和人员，不可配置应用": "모든 데이터와 구성원을 관리, 애플리케이션은 설정 불가",
  "门户设置": "포털 설정",
  "暂无权限操作": "권한이 없습니다.",
  "在向用户提供服务的过程中，明道云可能会接入第三方的产品或服务，该产品或服务由明道云以外的第三方提供。在法律允许的范围内，明道云不对第三方的产品或服务承担任何责任。用户需遵守所有第三方的产品或服务的使用条款和隐私政策。": "서비스 제공 과정에서 명도운은 제3자의 제품 또는 서비스를 연동할 수 있습니다. 해당 제품 또는 서비스는 명도운이 아닌 제3자가 제공합니다. 법이 허용하는 범위 내에서 명도운은 제3자의 제품 또는 서비스에 대해 어떠한 책임도 지지 않습니다. 사용자는 모든 제3자 제품 또는 서비스의 이용 약관과 개인정보 처리방침을 준수해야 합니다.",
  "电子邮箱": "이메일 주소",
  "全选%0条可批量审批的记录": "일괄 결재 가능한 레코드 %0개 모두 선택",
  "通过设置工作表和字段别名，使得它们在API、webhook、自定义打印等场景使用的时候更具有辨识度。": "워크시트와 필드의 별칭을 설정해 API, 웹훅, 사용자 지정 출력 등의 사용 시 식별성을 높입니다.",
  "3.明道云保留面向免费模式用户刊载广告的权利，这些广告刊载过程中将可能使用必要的定向技术来提高广告相关度，但明道云不会将用户的个人信息透露给广告商，而只会在匿名的基础上通过自动化匹配技术实现广告优化刊载。": "3. Mingdao Cloud는 무료 요금제 사용자에게 광고를 게재할 권리를 보유합니다. 광고 게재 과정에서 광고 관련성을 높이기 위해 필요한 타기팅 기술을 사용할 수 있으나, 사용자 개인정보는 광고주에게 제공하지 않으며, 익명화된 상태에서 자동 매칭 기술로 광고 최적화를 수행합니다.",
  "输入关键词搜索": "키워드를 입력해 검색하세요.",
