  "5)账户已经解除了与其他第三方账户的绑定。": "5) 계정이 다른 서드파티 계정과의 연동을 해제했습니다.",
  "可在此配置分享后的文件是否允许用户下载（分享到“消息”的将自动设为可下载）": "공유한 파일의 다운로드 허용 여부를 여기서 설정할 수 있습니다. ‘메시지’로 공유한 경우 자동으로 다운로드 가능으로 설정됩니다.",
