  "验证码发送过于频繁，%0收不到验证码？%1": "인증 코드 전송이 너무 빈번합니다. %0에서 인증 코드를 받지 못하나요? %1",
  "上传 Excel 模板": "Excel 템플릿 업로드",
  "API集成": "API 연동",
  "1.服务将按照“现状”和“可得到”的状态提供。明道云在此明确声明，除本协议有明确约定外，明道云对服务不作任何明示或暗示的保证，包括但不限于对服务的适用性、准确性、持续性、可靠性、服务没有错误或疏漏等。": "1. 서비스는 “있는 그대로(as is)” 및 “사용 가능한 범위(as available)”로 제공됩니다. 본 계약에 명시된 경우를 제외하고, Mingdao Cloud는 서비스의 적합성, 정확성, 지속성, 신뢰성, 무오류성 또는 누락 없음 등에 대해 명시적 또는 묵시적으로 어떠한 보증도 하지 않습니다.",
  "当前记录无权限，无法查看": "현재 레코드에 권한이 없어 볼 수 없습니다.",
  "取消关联(%0)": "연결 해제(%0)",
  "可根据配置的打印模板将记录转为PDF、Word或Excel文件，可以通过新增记录、更新记录或发送邮件节点将文件写入附件": "설정한 인쇄 템플릿에 따라 레코드를 PDF, Word, Excel 파일로 변환할 수 있습니다. 새 레코드 생성, 레코드 업데이트, 메일 발송 노드를 통해 파일을 첨부 파일로 저장할 수 있습니다.",
  "时区为beta功能，仅适用于工作表中日期时间类型的日期字段和系统字段。您可以设置个人时区，便于您录入和查看时间数据。例如，您在东京时，可以将个人时区设置为东九时区(UTC+9:00)。你输入的时间被平台视作东京时间，同时，工作表中的日期时间数据以东京时间呈现。": "시간대는 베타 기능으로, 워크시트의 날짜/시간 타입 필드와 시스템 필드에만 적용됩니다. 개인 시간대를 설정하여 시간 데이터를 입력하고 조회하기 편리합니다. 예를 들어 도쿄에 있는 경우 개인 시간대를 동경 표준시(UTC+9:00)로 설정할 수 있습니다. 입력한 시간은 플랫폼에서 도쿄 시간으로 인식되며, 워크시트의 날짜/시간 데이터도 도쿄 시간으로 표시됩니다.",
